  // Ricava il nome del comune dall'ultima parte dell'indirizzo (es. "Via X 20, Zona, Legnano" -> "Legnano")
  function ricavaComuneDaIndirizzo(paeseVia) {
    if (!paeseVia) return '';
    const parti = paeseVia.split(',').map(p => p.trim()).filter(p => p);
    return parti.length ? parti[parti.length - 1] : '';
  }

  // Ricava il nome della via dalla prima parte dell'indirizzo, togliendo il civico finale
  // (es. "Via X 20, Zona, Legnano" -> "Via X")
  function ricavaViaDaIndirizzo(paeseVia) {
    if (!paeseVia) return '';
    const primaParte = paeseVia.split(',')[0].trim();
    return primaParte.replace(/\s+\d+[A-Za-z\/\-]*\s*$/, '').trim();
  }

  /* Il civico e' il numero in coda alla prima parte: "Via Roma 20/A, Legnano" -> "20/A" */
  function ricavaCivicoDaIndirizzo(paeseVia) {
    if (!paeseVia) return '';
    const primaParte = String(paeseVia).split(',')[0].trim();
    const trovato = primaParte.match(/(\d+[A-Za-z\/\-]*)\s*$/);
    return trovato ? trovato[1] : '';
  }

  /* L'indirizzo completo si ricompone sempre dalle tre colonne: e' quello che
     usiamo per la geolocalizzazione e per il link a Google Maps. */
  /* La colonna Mappa: verde quando le coordinate sono gia' salvate, grigia quando
     l'indirizzo c'e' ma non e' ancora stato geolocalizzato, trattino se manca tutto. */
  function cellaMappaConcorrenza(r) {
    const indirizzo = componiIndirizzoConcorrenza(r);
    if (!indirizzo) return `<td style="text-align:center;"><span style="color:#64748b; font-size:12px;" title="Compila Comune e Via">-</span></td>`;
    const geolocalizzato = r.lat !== null && r.lat !== undefined && r.lat !== '' && !isNaN(Number(r.lat));
    const colore = geolocalizzato ? '#00c875' : '#5f6672';
    const titolo = geolocalizzato ? 'Sulla mappa &middot; apri in Google Maps' : 'Non ancora geolocalizzato &middot; apri in Google Maps';
    return `<td style="text-align:center;">
      <button onclick="apriGoogleMaps('${indirizzo.replace(/'/g, "\\'")}')" title="${titolo}"
        style="background:none; border:none; color:${colore}; cursor:pointer; font-size:16px;">
        <i class="fa-solid fa-map-location-dot"></i></button></td>`;
  }

  function componiIndirizzoConcorrenza(r) {
    if (!r) return '';
    const strada = [r.via, r.civico].filter(x => x && String(x).trim() && String(x).trim() !== 'N.D.').join(' ').trim();
    const comune = (r.comune || '').trim();
    return [strada, comune].filter(Boolean).join(', ');
  }

  async function ricavaComuneSuRigheEsistenti() {
    const daCorreggere = REGISTRO_CONCORRENZA_CLOUD.filter(r => !r.comune || !r.via);
    if (daCorreggere.length === 0) { alert("Tutte le righe hanno già Comune e Via assegnati."); return; }
    if (!confirm(`Trovate ${daCorreggere.length} righe senza Comune e/o Via. Ricavarli automaticamente dall'indirizzo?`)) return;

    let corrette = 0;
    for (const r of daCorreggere) {
      const aggiornamenti = {};
      if (!r.comune) { const c = ricavaComuneDaIndirizzo(r.paeseVia); if (c) aggiornamenti.comune = c; }
      if (!r.via) { const v = ricavaViaDaIndirizzo(r.paeseVia); if (v) aggiornamenti.via = v; }
      if (Object.keys(aggiornamenti).length) {
        for (const [campo, valore] of Object.entries(aggiornamenti)) {
          await aggiornaCampoConcorrenza(r._id, campo, valore);
        }
        corrette++;
      }
    }
    alert(`Comune/Via ricavati e salvati per ${corrette} annunci.`);
    ridisegnaVistaConcorrenzaCorrente();
  }

  function importaFileExcelConcorrenza(input) {
    const file = input.files[0]; if (!file) return;
    const reader = new FileReader();
    reader.onload = async function(e) {
      const data = new Uint8Array(e.target.result);
      const workbook = XLSX.read(data, { type: 'array' });
      const sheetName = workbook.SheetNames[0];
      const rows = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName]);
      const mapped = rows.map(r => {
        // L'export di immobiliare mette tutto in una stringa sola: la spezzo nelle tre colonne
        const indirizzoOriginale = r["Paese Via"] || r["paeseVia"] || r["Indirizzo"] || "";
        const comune = (r["Comune"] || r["comune"] || "").trim() || ricavaComuneDaIndirizzo(indirizzoOriginale);
        const via = (r["Via"] || r["via"] || "").trim() || ricavaViaDaIndirizzo(indirizzoOriginale);
        const civico = String(r["Civico"] || r["civico"] || "").trim() || ricavaCivicoDaIndirizzo(indirizzoOriginale);
        const paeseVia = componiIndirizzoConcorrenza({ via, civico, comune }) || indirizzoOriginale || "N.D.";
        return {
          titolo: r["Titolo"] || r["titolo"] || "N.D.",
          comune: comune,
          via: via,
          paeseVia,
          civico: civico, contesto: r["Tipologia Contesto"] || r["contesto"] || "Residenziale",
          unita: r["Tipologia unità"] || r["unita"] || "Appartamento", piano: r["Piano"] || r["piano"] || "N.D.",
          bagni: String(r["N° bagni"] || r["bagni"] || "1"), prezzo: r["Prezzo Pubblicità"] || r["prezzo"] || "N.D.",
          agenzia: r["Agenzia Immobiliare"] || r["agenzia"] || "N.D.", privato: r["Privato"] || r["privato"] || "",
          dataAnnuncio: r["Data Annuncio"] || r["dataAnnuncio"] || "19/07/2026",
          link: r["Link Annuncio"] || r["link"] || ""
        };
      });
      const res = await fetch(`${API_CONCORRENZA}/massivo`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(mapped) });
      if(res.ok) {
        const esito = await res.json();
        let messaggio = `Importazione completata! Aggiunti ${esito.count} nuovi annunci.`;
        if (esito.saltatiPerDoppione > 0) messaggio += `\n${esito.saltatiPerDoppione} annunci saltati perché già presenti (stesso link).`;
        if (esito.agenzieNuoveCreate > 0) messaggio += `\n${esito.agenzieNuoveCreate} nuove agenzie censite automaticamente.`;
        alert(messaggio);
        cambiaVistaCrmLocale('info-concorrenza');
      }
    };
    reader.readAsArrayBuffer(file);
  }

  async function svuotaInteraPlanciaConcorrenza() {
    if(!confirm("Svuotare concorrenza?")) return;
    await fetch(`${API_CONCORRENZA}/svuota`, { method: 'DELETE' });
    cambiaVistaCrmLocale('info-concorrenza');
  }

  async function eliminaAnnuncioConcorrenza(id, titolo) {
    if(!confirm(`Eliminare ${titolo}?`)) return;
    const res = await fetch(`${API_CONCORRENZA}/${id}`, { method: 'DELETE' });
    if(res.ok) { await sincronizzaConcorrenzaDaRender(); ridisegnaVistaConcorrenzaCorrente(); }
  }

  // --- Agenzia Immobiliari & Agenti Immobiliari (Capitale Sociale, schede collegate) ---
  let REGISTRO_AGENZIE_CLOUD = [];
  let REGISTRO_AGENTI_CLOUD = [];
  let NODI_AGENZIA_APERTI = new Set();

  async function sincronizzaAgenzieImmobiliariDaRender() {
    try { const res = await fetch(API_AGENZIE_IMMOBILIARI); if (res.ok) { const dati = await res.json(); if (Array.isArray(dati)) REGISTRO_AGENZIE_CLOUD = dati; } } catch(e){}
  }
  async function sincronizzaAgentiImmobiliariDaRender() {
    try { const res = await fetch(API_AGENTI_IMMOBILIARI); if (res.ok) { const dati = await res.json(); if (Array.isArray(dati)) REGISTRO_AGENTI_CLOUD = dati; } } catch(e){}
  }

  function campoEditabileGenerico(id, campo, valore, funzioneAggiorna, stile) {
    return `<span contenteditable="true" spellcheck="false" style="outline:none; display:inline-block; min-width:20px; ${stile||''}" onblur="${funzioneAggiorna}('${id}','${campo}', this.innerText)" onkeydown="if(event.key==='Enter'){event.preventDefault(); this.blur();}">${valore || ''}</span>`;
  }

  function disegnaTabellaAgenzieImmobiliari() {
    const container = document.getElementById("monday-tables-container");
    let html = `
      <div style="margin-bottom:14px;">
        <button class="btn-new-element" style="background:#0086d6;" onclick="toggleFormNuovaAgenzia()"><i class="fa-solid fa-plus"></i> Nuova Agenzia</button>
      </div>
      <div id="form-nuova-agenzia" style="display:none; background:#1c1f24; padding:16px; border-radius:8px; margin-bottom:16px; display:none;">
        <div style="display:flex; gap:10px; flex-wrap:wrap;">
          <input type="text" id="nuova-agenzia-nome" placeholder="Nome Agenzia" style="flex:1; min-width:160px; padding:8px; background:#18191c; border:1px solid #3e4147; color:white; border-radius:4px;">
          <input type="text" id="nuova-agenzia-sede" placeholder="Sede" style="flex:1; min-width:160px; padding:8px; background:#18191c; border:1px solid #3e4147; color:white; border-radius:4px;">
          <input type="text" id="nuova-agenzia-mail" placeholder="Mail" style="flex:1; min-width:160px; padding:8px; background:#18191c; border:1px solid #3e4147; color:white; border-radius:4px;">
          <input type="text" id="nuova-agenzia-telefono" placeholder="Numero di Telefono" style="flex:1; min-width:160px; padding:8px; background:#18191c; border:1px solid #3e4147; color:white; border-radius:4px;">
        </div>
        <button onclick="salvaNuovaAgenzia()" style="margin-top:10px; background:#00c875; border:none; color:#18191c; padding:8px 16px; border-radius:4px; cursor:pointer; font-weight:700;">Salva Agenzia</button>
      </div>
      <table class="monday-table-centralino">
      <thead><tr><th>Nome Agenzia</th><th>Sede</th><th>Mail</th><th>Numero di Telefono</th><th></th></tr></thead><tbody>`;

    if (REGISTRO_AGENZIE_CLOUD.length === 0) {
      html += `<tr><td colspan="5" style="text-align:center; padding:30px; color:#868b98;">Nessuna agenzia presente.</td></tr>`;
    } else {
      REGISTRO_AGENZIE_CLOUD.forEach(a => {
        const idNodo = `agenzia-sub-${a._id}`;
        const aperto = NODI_AGENZIA_APERTI.has(idNodo);
        const agentiCollegati = REGISTRO_AGENTI_CLOUD.filter(ag => ag.agenziaId === a._id);
        html += `<tr>
          <td>
            <span onclick="toggleSubAgentiAgenzia('${idNodo}')" style="cursor:pointer; color:#868b98; margin-right:6px;"><i class="fa-solid fa-users"></i></span>
            <strong>${campoEditabileGenerico(a._id, 'nomeAgenzia', a.nomeAgenzia, 'aggiornaCampoAgenzia')}</strong>
          </td>
          <td>${campoEditabileGenerico(a._id, 'sede', a.sede, 'aggiornaCampoAgenzia')}</td>
          <td>${campoEditabileGenerico(a._id, 'mail', a.mail, 'aggiornaCampoAgenzia')}</td>
          <td>${campoEditabileGenerico(a._id, 'telefono', a.telefono, 'aggiornaCampoAgenzia')}</td>
          <td><button class="btn-cestino-riga" onclick="eliminaAgenziaImmobiliare('${a._id}', '${(a.nomeAgenzia||'').replace(/'/g,"\\'")}')"><i class="fa-solid fa-trash-can"></i></button></td>
        </tr>`;
        if (aperto) {
          html += `<tr><td colspan="5" style="background:#16181c; padding:14px;">
            <div style="color:#e2b13c; font-weight:700; margin-bottom:8px; font-size:12px; text-transform:uppercase;">Agenti collegati a ${a.nomeAgenzia}</div>`;
          if (agentiCollegati.length === 0) {
            html += `<div style="color:#868b98; font-size:13px;">Nessun agente collegato a questa agenzia.</div>`;
          } else {
            html += `<table class="monday-sub-table"><thead><tr><th class="valore-specchio">Nome e Cognome</th><th class="valore-specchio">Telefono</th><th class="valore-specchio">Mail</th></tr></thead><tbody>`;
            agentiCollegati.forEach(ag => {
              html += `<tr><td class="valore-specchio">${ag.nomeCognome}</td><td class="valore-specchio">${ag.telefono}</td><td class="valore-specchio">${ag.mail}</td></tr>`;
            });
            html += `</tbody></table>`;
          }
          html += `</td></tr>`;
        }
      });
    }
    container.innerHTML = html + `</tbody></table>`;
  }

  function toggleSubAgentiAgenzia(idNodo) {
    if (NODI_AGENZIA_APERTI.has(idNodo)) NODI_AGENZIA_APERTI.delete(idNodo); else NODI_AGENZIA_APERTI.add(idNodo);
    disegnaTabellaAgenzieImmobiliari();
  }

  function toggleFormNuovaAgenzia() {
    const form = document.getElementById("form-nuova-agenzia");
    form.style.display = (form.style.display === "none" || form.style.display === "") ? "block" : "none";
  }

  async function salvaNuovaAgenzia() {
    const nomeAgenzia = document.getElementById("nuova-agenzia-nome").value.trim();
    if (!nomeAgenzia) { alert("Il nome dell'agenzia è obbligatorio."); return; }
    const payload = {
      nomeAgenzia,
      sede: document.getElementById("nuova-agenzia-sede").value.trim(),
      mail: document.getElementById("nuova-agenzia-mail").value.trim(),
      telefono: document.getElementById("nuova-agenzia-telefono").value.trim()
    };
    await fetch(API_AGENZIE_IMMOBILIARI, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
    await sincronizzaAgenzieImmobiliariDaRender();
    disegnaTabellaAgenzieImmobiliari();
  }

  async function aggiornaCampoAgenzia(id, campo, valore) {
    try {
      await fetch(`${API_AGENZIE_IMMOBILIARI}/${id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ [campo]: valore }) });
      const record = REGISTRO_AGENZIE_CLOUD.find(a => a._id === id);
      if (record) record[campo] = valore;
    } catch (e) { console.error('Errore aggiornamento agenzia:', e); }
  }

  async function eliminaAgenziaImmobiliare(id, nome) {
    if (!confirm(`Eliminare l'agenzia "${nome}"? Gli agenti collegati resteranno ma senza agenzia assegnata.`)) return;
    await fetch(`${API_AGENZIE_IMMOBILIARI}/${id}`, { method: 'DELETE' });
    await sincronizzaAgenzieImmobiliariDaRender();
    disegnaTabellaAgenzieImmobiliari();
  }

  function disegnaTabellaAgentiImmobiliari() {
    const container = document.getElementById("monday-tables-container");
    const opzioniAgenzie = REGISTRO_AGENZIE_CLOUD.map(a => `<option value="${a._id}">${a.nomeAgenzia}</option>`).join('');
    let html = `
      <div style="margin-bottom:14px;">
        <button class="btn-new-element" style="background:#c9a876; color:#18191c;" onclick="toggleFormNuovoAgente()"><i class="fa-solid fa-plus"></i> Nuovo Agente</button>
      </div>
      <div id="form-nuovo-agente" style="background:#1c1f24; padding:16px; border-radius:8px; margin-bottom:16px; display:none;">
        <div style="display:flex; gap:10px; flex-wrap:wrap;">
          <input type="text" id="nuovo-agente-nome" placeholder="Nome e Cognome" style="flex:1; min-width:160px; padding:8px; background:#18191c; border:1px solid #3e4147; color:white; border-radius:4px;">
          <input type="text" id="nuovo-agente-telefono" placeholder="Numero di Telefono" style="flex:1; min-width:160px; padding:8px; background:#18191c; border:1px solid #3e4147; color:white; border-radius:4px;">
          <input type="text" id="nuovo-agente-mail" placeholder="Mail" style="flex:1; min-width:160px; padding:8px; background:#18191c; border:1px solid #3e4147; color:white; border-radius:4px;">
          <select id="nuovo-agente-agenzia" style="flex:1; min-width:160px; padding:8px; background:#18191c; border:1px solid #3e4147; color:white; border-radius:4px;">
            <option value="">-- Nessuna agenzia --</option>
            ${opzioniAgenzie}
          </select>
        </div>
        <button onclick="salvaNuovoAgente()" style="margin-top:10px; background:#00c875; border:none; color:#18191c; padding:8px 16px; border-radius:4px; cursor:pointer; font-weight:700;">Salva Agente</button>
      </div>
      <table class="monday-table-centralino">
      <thead><tr><th>Nome e Cognome</th><th>Numero di Telefono</th><th>Mail</th><th>Agenzia Immobiliare</th><th></th></tr></thead><tbody>`;

    if (REGISTRO_AGENTI_CLOUD.length === 0) {
      html += `<tr><td colspan="5" style="text-align:center; padding:30px; color:#868b98;">Nessun agente presente.</td></tr>`;
    } else {
      REGISTRO_AGENTI_CLOUD.forEach(ag => {
        html += `<tr>
          <td><strong>${campoEditabileGenerico(ag._id, 'nomeCognome', ag.nomeCognome, 'aggiornaCampoAgente')}</strong></td>
          <td>${campoEditabileGenerico(ag._id, 'telefono', ag.telefono, 'aggiornaCampoAgente')}</td>
          <td>${campoEditabileGenerico(ag._id, 'mail', ag.mail, 'aggiornaCampoAgente')}</td>
          <td>
            <select onchange="aggiornaCampoAgente('${ag._id}','agenziaId', this.value)" style="background:#18191c; border:1px solid #3e4147; color:white; border-radius:4px; padding:4px 6px;">
              <option value="" ${!ag.agenziaId ? 'selected':''}>-- Nessuna agenzia --</option>
              ${REGISTRO_AGENZIE_CLOUD.map(a => `<option value="${a._id}" ${ag.agenziaId === a._id ? 'selected':''}>${a.nomeAgenzia}</option>`).join('')}
            </select>
          </td>
          <td><button class="btn-cestino-riga" onclick="eliminaAgenteImmobiliare('${ag._id}', '${(ag.nomeCognome||'').replace(/'/g,"\\'")}')"><i class="fa-solid fa-trash-can"></i></button></td>
        </tr>`;
      });
    }
    container.innerHTML = html + `</tbody></table>`;
  }

  function toggleFormNuovoAgente() {
    const form = document.getElementById("form-nuovo-agente");
    form.style.display = (form.style.display === "none" || form.style.display === "") ? "block" : "none";
  }

  async function salvaNuovoAgente() {
    const nomeCognome = document.getElementById("nuovo-agente-nome").value.trim();
    if (!nomeCognome) { alert("Il nome e cognome dell'agente è obbligatorio."); return; }
    const payload = {
      nomeCognome,
      telefono: document.getElementById("nuovo-agente-telefono").value.trim(),
      mail: document.getElementById("nuovo-agente-mail").value.trim(),
      agenziaId: document.getElementById("nuovo-agente-agenzia").value
    };
    await fetch(API_AGENTI_IMMOBILIARI, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
    await sincronizzaAgentiImmobiliariDaRender();
    disegnaTabellaAgentiImmobiliari();
  }

  async function aggiornaCampoAgente(id, campo, valore) {
    try {
      await fetch(`${API_AGENTI_IMMOBILIARI}/${id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ [campo]: valore }) });
      const record = REGISTRO_AGENTI_CLOUD.find(a => a._id === id);
      if (record) record[campo] = valore;
    } catch (e) { console.error('Errore aggiornamento agente:', e); }
  }

  async function eliminaAgenteImmobiliare(id, nome) {
    if (!confirm(`Eliminare l'agente "${nome}"?`)) return;
    await fetch(`${API_AGENTI_IMMOBILIARI}/${id}`, { method: 'DELETE' });
    await sincronizzaAgentiImmobiliariDaRender();
    disegnaTabellaAgentiImmobiliari();
  }

  /* Due cose diverse, che prima erano una sola variabile e si pestavano i piedi:
     TIPO  = quali annunci guardo, e lo decide la scheda di menu (Concorrenza / Vdp / Vdp No Numero)
     MODO  = come li guardo: tabella, mappa o classifica agenzie */
  let TIPO_CONCORRENZA = 'agenzia';   // 'agenzia' | 'vdp' | 'vdp-no-numero'
  let MODO_CONCORRENZA = 'tabella';   // 'tabella' | 'mappa' | 'classifica'
  let VISTA_ATTIVA_CONCORRENZA = 'agenzia'; // mantenuta per compatibilita' con il codice esistente

  /* I pulsanti in alto cambiano solo il MODO: il tipo di annuncio resta quello della scheda */
  function cambiaVistaConcorrenza(nuovoModo) {
    MODO_CONCORRENZA = (nuovoModo === 'mappa' || nuovoModo === 'classifica' || nuovoModo === 'kanban' || nuovoModo === 'consulenti') ? nuovoModo : 'tabella';
    VISTA_ATTIVA_CONCORRENZA = TIPO_CONCORRENZA;
    ridisegnaVistaConcorrenzaCorrente();
  }

  /* Lo cambia il menu di sinistra quando passi da una scheda all'altra */
  function impostaTipoConcorrenza(tipo) {
    TIPO_CONCORRENZA = tipo;
    VISTA_ATTIVA_CONCORRENZA = tipo;
    MODO_CONCORRENZA = 'tabella';
    PAGINA_CONCORRENZA = 1;
  }

  function ridisegnaVistaConcorrenzaCorrente() {
    if (MODO_CONCORRENZA === 'classifica') disegnaClassificaAgenzieConcorrenza();
    else if (MODO_CONCORRENZA === 'mappa') disegnaMappaConcorrenza();
    else if (MODO_CONCORRENZA === 'kanban') disegnaKanbanConcorrenza();
    else if (MODO_CONCORRENZA === 'consulenti') disegnaAnalisiConsulentiConcorrenza();
    else disegnaTabellaConcorrenzaCloud();
  }

  const CACHE_GEOCODING_CONCORRENZA = {};
  let MAPPA_GOOGLE_CONCORRENZA = null;
  let SCRIPT_GOOGLE_MAPS_CARICATO = false;

  function messaggioMappaConcorrenza(testo, colore) {
    const box = document.getElementById("mappa-concorrenza-container");
    if (!box) return;
    box.style.display = 'flex';
    box.innerHTML = `<div style="text-align:center; color:${colore || '#868b98'}; padding:20px; max-width:520px;">${testo}</div>`;
  }

  function ricalcolaGeotagConcorrenza() {
    Object.keys(CACHE_GEOCODING_CONCORRENZA).forEach(k => delete CACHE_GEOCODING_CONCORRENZA[k]);
    disegnaMappaConcorrenza();
  }

  /* Cancella le coordinate salvate di un annuncio (utile se ne correggi l'indirizzo) */
  async function azzeraCoordinateConcorrenza(id) {
    const record = REGISTRO_CONCORRENZA_CLOUD.find(r => r._id === id);
    if (record) { record.lat = null; record.lng = null; }
    try {
      await fetch(`${API_CONCORRENZA}/${id}`, {
        method: 'PUT', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ lat: null, lng: null })
      });
    } catch (e) { console.warn('Coordinate non azzerate:', e); }
  }

  function riprovaMappaConcorrenza() {
    SCRIPT_GOOGLE_MAPS_CARICATO = false;
    disegnaMappaConcorrenza();
  }

  /* Google chiama questa funzione quando la chiave API viene rifiutata
     (dominio non autorizzato, fatturazione spenta, API non abilitata). */
  window.gm_authFailure = function () {
    messaggioMappaConcorrenza(
      `<i class="fa-solid fa-triangle-exclamation" style="font-size:22px; color:#f43f5e;"></i>
       <div style="margin-top:10px; color:#f43f5e; font-weight:700;">Google ha rifiutato la chiave API</div>
       <div style="margin-top:8px; font-size:12.5px; line-height:1.6;">Nella Google Cloud Console verifica che per questa chiave siano attive
       <strong>Maps JavaScript API</strong> e <strong>Geocoding API</strong>, che la fatturazione sia abilitata e che il dominio del sito
       sia tra i referrer autorizzati.</div>`, '#f43f5e');
  };

  function disegnaMappaConcorrenza() {
    const container = document.getElementById("monday-tables-container");
    let html = renderizzaBarraViste('concorrenza', COLONNE_META_CONCORRENZA, COLONNE_RAGGRUPPABILI_CONCORRENZA, REGISTRO_CONCORRENZA_CLOUD);
    html += `<div id="riepilogo-mappa-concorrenza" style="color:#868b98; font-size:12px; margin-bottom:10px;"></div>`;
    html += `<div id="mappa-concorrenza-container" style="width:100%; height:600px; border-radius:8px; overflow:hidden; background:#1c1f24; display:flex; align-items:center; justify-content:center; color:#868b98;">Caricamento mappa...</div>`;
    container.innerHTML = html;

    if (typeof google === 'undefined' || !google.maps || !google.maps.Map) {
      if (SCRIPT_GOOGLE_MAPS_CARICATO) {
        messaggioMappaConcorrenza(
          `Google Maps risulta gi&agrave; in caricamento ma non &egrave; ancora pronto.
           <div style="margin-top:12px;"><button onclick="riprovaMappaConcorrenza()" style="background:#0086d6; border:none; color:#fff; padding:8px 16px; border-radius:6px; cursor:pointer;">Riprova</button></div>`);
        return;
      }
      SCRIPT_GOOGLE_MAPS_CARICATO = true;
      window.disegnaMappaConcorrenza = disegnaMappaConcorrenza; // il callback di Google cerca la funzione su window
      const script = document.createElement('script');
      // NB: "geocoding" non e' una libreria valida di Google Maps (il Geocoder e' gia' nel core):
      // indicarla faceva fallire il caricamento dello script.
      script.src = `https://maps.googleapis.com/maps/api/js?key=${GOOGLE_MAPS_API_KEY}&loading=async&callback=disegnaMappaConcorrenza`;
      script.async = true;
      script.onerror = () => {
        SCRIPT_GOOGLE_MAPS_CARICATO = false;
        messaggioMappaConcorrenza(
          `<i class="fa-solid fa-plug-circle-xmark" style="font-size:22px; color:#f43f5e;"></i>
           <div style="margin-top:10px; color:#f43f5e; font-weight:700;">Impossibile caricare Google Maps</div>
           <div style="margin-top:8px; font-size:12.5px; line-height:1.6;">Lo script non &egrave; stato scaricato: pu&ograve; dipendere dalla connessione,
           da un blocco del browser (adblock) o da restrizioni del sito.</div>
           <div style="margin-top:12px;"><button onclick="riprovaMappaConcorrenza()" style="background:#0086d6; border:none; color:#fff; padding:8px 16px; border-radius:6px; cursor:pointer;">Riprova</button></div>`, '#f43f5e');
      };
      document.head.appendChild(script);
      return;
    }
    caricaGeotagConcorrenza();
  }

  /* Quanti indirizzi nuovi geolocalizzare a ogni apertura della mappa.
     Google frena (OVER_QUERY_LIMIT) se glieli chiedi tutti insieme, quindi si va a lotti
     e ogni coordinata trovata viene salvata sul database: la volta dopo non serve piu' chiederla. */
  const LOTTO_GEOCODING_CONCORRENZA = 25;
  const PAUSA_TRA_GEOCODING_MS = 220;

  function aggiungiMarkerConcorrenza(map, bounds, record, posizione) {
    // il pallino prende il colore dello stato di sviluppo, come la cella in tabella
    const coloreMarker = statoSviluppoDi(record).colore;
    const marker = new google.maps.Marker({
      position: posizione, map,
      title: record.titolo,
      icon: { path: google.maps.SymbolPath.CIRCLE, scale: 8, fillColor: coloreMarker, fillOpacity: 1, strokeColor: 'white', strokeWeight: 2 }
    });
    const linkAnnuncio = String(record.link || '').trim();
    const infoWindow = new google.maps.InfoWindow({
      content: `<div style="color:#18191c; font-size:13px; max-width:250px; line-height:1.5;">
        <strong>${record.titolo || ''}</strong><br>${record.paeseVia || ''}<br>
        <span style="color:#00a45e; font-weight:700;">&euro; ${record.prezzo || 'N.D.'}</span><br>
        <span style="color:#868b98;">${record.agenzia || 'Privato'}${record.privato ? ' &middot; ' + record.privato : ''}</span>
        ${linkAnnuncio
          ? `<div style="margin-top:9px;"><a href="${linkAnnuncio}" target="_blank" rel="noopener"
               style="display:inline-block; background:#0086d6; color:#fff; padding:6px 13px; border-radius:5px; text-decoration:none; font-weight:700; font-size:12px;">
               Apri annuncio &nearr;</a></div>`
          : `<div style="margin-top:7px; color:#b0b6bd; font-size:11.5px;">nessun link salvato su questo annuncio</div>`}
      </div>`
    });
    marker.addListener('click', () => infoWindow.open(map, marker));
    bounds.extend(posizione);
  }

  function indirizzoDiConcorrenza(r) {
    return componiIndirizzoConcorrenza(r) || String(r.paeseVia || '').trim();
  }

  async function caricaGeotagConcorrenza(quantiGeocodificare) {
    const configConcorrenza = ottieniConfigVista('concorrenza');
    // solo gli annunci della scheda aperta: agenzie in Concorrenza, privati in Vdp, senza numero in Vdp No Numero
    const registro = applicaFiltriAvanzati(filtraRegistroConcorrenzaPerVista(), configConcorrenza.filtriAvanzati);
    const mapContainer = document.getElementById("mappa-concorrenza-container");
    const riepilogo = document.getElementById("riepilogo-mappa-concorrenza");
    if (!mapContainer) return;

    // La mappa non puo' nascere dentro un contenitore flex: i tile si sgretolano.
    mapContainer.innerHTML = '';
    mapContainer.style.display = 'block';
    mapContainer.style.alignItems = '';
    mapContainer.style.justifyContent = '';

    let map;
    try {
      map = new google.maps.Map(mapContainer, { center: { lat: 45.5945, lng: 8.9161 }, zoom: 11 }); // Alto Milanese
    } catch (e) {
      console.error('Errore creazione mappa:', e);
      messaggioMappaConcorrenza(`Errore nella creazione della mappa: ${e.message}`, '#f43f5e');
      return;
    }
    MAPPA_GOOGLE_CONCORRENZA = map;

    const bounds = new google.maps.LatLngBounds();
    let trovati = 0, falliti = 0;
    const statiIncontrati = {};
    let primoIndirizzoFallito = '';

    // 1) Chi ha gia' le coordinate salvate finisce subito sulla mappa, senza chiamare Google
    const daGeocodificare = [];
    let senzaIndirizzo = 0;

    registro.forEach(r => {
      const lat = Number(r.lat), lng = Number(r.lng);
      if (r.lat !== null && r.lat !== undefined && r.lat !== '' && !isNaN(lat) && !isNaN(lng)) {
        aggiungiMarkerConcorrenza(map, bounds, r, { lat, lng });
        trovati++;
        return;
      }
      const indirizzo = indirizzoDiConcorrenza(r);
      if (indirizzo && indirizzo.length > 3) daGeocodificare.push({ record: r, indirizzo });
      else senzaIndirizzo++;
    });

    if (trovati > 0) map.fitBounds(bounds);

    const scriviRiepilogo = (mancanti, inCorso) => {
      if (!riepilogo) return;
      const pezzi = [`<strong style="color:#00c875;">${trovati}</strong> sulla mappa`];
      if (mancanti > 0) pezzi.push(`<strong style="color:#e2b13c;">${mancanti}</strong> da geolocalizzare`);
      if (falliti > 0) pezzi.push(`<strong style="color:#f43f5e;">${falliti}</strong> non riusciti`);
      if (senzaIndirizzo > 0) pezzi.push(`<strong style="color:#868b98;">${senzaIndirizzo}</strong> senza indirizzo`);

      // la legenda segue gli stati di sviluppo, gli stessi colori dei pallini
      let coda = ' &middot; ' + STATI_SVILUPPO_CONCORRENZA
        .map(s => `<span style="color:${s.colore};">&#9679;</span> ${s.nome.toLowerCase()}`).join(' &nbsp; ');
      if (inCorso) {
        coda += ` &middot; <span style="color:#38bdf8;"><i class="fa-solid fa-spinner fa-spin"></i> geolocalizzo... (${inCorso})</span>`;
      } else if (mancanti > 0) {
        coda += ` &middot; <button onclick="continuaGeotagConcorrenza(${Math.min(mancanti, LOTTO_GEOCODING_CONCORRENZA)})" style="background:#0086d6; border:none; color:#fff; padding:4px 12px; border-radius:12px; font-size:11.5px; cursor:pointer;">Geolocalizza altri ${Math.min(mancanti, LOTTO_GEOCODING_CONCORRENZA)}</button>`;
        if (mancanti > LOTTO_GEOCODING_CONCORRENZA) {
          coda += ` <button onclick="continuaGeotagConcorrenza(${mancanti})" style="background:#292c33; border:1px solid #3e4147; color:#cbd5e1; padding:4px 12px; border-radius:12px; font-size:11.5px; cursor:pointer;">Geolocalizza tutti (${mancanti})</button>`;
        }
      }

      let avviso = '';
      const codici = Object.keys(statiIncontrati);
      const esempio = primoIndirizzoFallito
        ? `<div style="margin-top:6px; font-size:11.5px; opacity:.85;">Primo caso: <code>${primoIndirizzoFallito}</code></div>` : '';

      if (statiIncontrati['REQUEST_DENIED']) {
        avviso = `<div style="margin-top:8px; background:rgba(244,63,94,0.12); border-left:3px solid #f43f5e; padding:10px 12px; border-radius:4px; color:#f43f5e; font-size:12.5px; line-height:1.6;">
          <strong>Geocoding API non attiva su questa chiave.</strong> La mappa si vede perch&eacute; Maps JavaScript API funziona,
          ma convertire gli indirizzi in coordinate &egrave; un servizio separato: abilita <strong>Geocoding API</strong> nella
          Libreria della Google Cloud Console e, se hai limitato la chiave a certe API, aggiungila anche l&igrave;.${esempio}</div>`;
      } else if (statiIncontrati['OVER_QUERY_LIMIT']) {
        avviso = `<div style="margin-top:8px; background:rgba(226,177,60,0.12); border-left:3px solid #e2b13c; padding:10px 12px; border-radius:4px; color:#e2b13c; font-size:12.5px;">
          <strong>Google ha frenato le richieste.</strong> Riprova tra qualche minuto con il pulsante qui sopra:
          gli indirizzi gi&agrave; risolti restano salvati e non vengono richiesti di nuovo.${esempio}</div>`;
      } else if (statiIncontrati['COMUNE_DIVERSO']) {
        avviso = `<div style="margin-top:8px; background:rgba(226,177,60,0.12); border-left:3px solid #e2b13c; padding:10px 12px; border-radius:4px; color:#e2b13c; font-size:12.5px;">
          <strong>${statiIncontrati['COMUNE_DIVERSO']} indirizzi trovati in un altro comune.</strong> Google ha proposto una via con lo stesso nome
          altrove: non li ho messi sulla mappa per non darti una posizione sbagliata. Controlla che Comune, Via e Civico siano scritti giusti.${esempio}</div>`;
      } else if (statiIncontrati['ZERO_RESULTS']) {
        avviso = `<div style="margin-top:8px; background:rgba(226,177,60,0.12); border-left:3px solid #e2b13c; padding:10px 12px; border-radius:4px; color:#e2b13c; font-size:12.5px;">
          <strong>${statiIncontrati['ZERO_RESULTS']} indirizzi non riconosciuti da Google.</strong> Di solito manca il comune:
          controlla nella vista tabella che Comune, Via e Civico siano compilati (oppure il campo Paese/Via per intero).${esempio}</div>`;
      } else if (codici.length) {
        avviso = `<div style="margin-top:8px; background:rgba(244,63,94,0.12); border-left:3px solid #f43f5e; padding:10px 12px; border-radius:4px; color:#f43f5e; font-size:12.5px;">
          <strong>Geocoding non riuscito (${codici.join(', ')}).</strong> Con TIMEOUT la risposta di Google non &egrave; mai arrivata;
          negli altri casi il codice qui sopra &egrave; quello restituito da Google.${esempio}</div>`;
      }

      riepilogo.innerHTML = pezzi.join(' &middot; ') + coda + avviso;
    };

    scriviRiepilogo(daGeocodificare.length, 0);
    if (daGeocodificare.length === 0) return;

    // 2) Solo i nuovi vengono chiesti a Google, a piccoli lotti
    const quanti = (quantiGeocodificare === undefined) ? LOTTO_GEOCODING_CONCORRENZA : quantiGeocodificare;
    const lotto = daGeocodificare.slice(0, quanti);
    const attendi = (ms) => new Promise(r => setTimeout(r, ms));
    const geocoder = new google.maps.Geocoder();

    /* Chiedo a Google restando dentro il comune indicato: senza questo vincolo
       "Via Quadrio 28, Legnano" puo' finire sulla via omonima di un altro paese. */
    async function chiediAGoogle(richiesta) {
      const scadenza = new Promise((_, rifiuta) => setTimeout(() => rifiuta({ code: 'TIMEOUT' }), 10000));
      const risposta = await Promise.race([geocoder.geocode(richiesta), scadenza]);
      if (!risposta || !risposta.results || !risposta.results[0]) throw { code: 'ZERO_RESULTS' };
      return risposta.results[0];
    }

    const semplifica = (s) => String(s || '').toLowerCase()
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z ]/g, ' ').replace(/\s+/g, ' ').trim();

    async function geocodifica(record, indirizzo) {
      const comune = (record && record.comune || '').trim();
      const componenti = { country: 'IT' };
      if (comune) componenti.locality = comune;

      let esito;
      try {
        // primo tentativo: vincolato al comune
        esito = await chiediAGoogle({ address: indirizzo, region: 'it', componentRestrictions: componenti });
      } catch (e) {
        if (!comune || (e && e.code !== 'ZERO_RESULTS')) throw e;
        // il vincolo era troppo stretto (frazioni, comuni scritti diversamente): riprovo libero
        esito = await chiediAGoogle({ address: indirizzo + ', Italia', region: 'it' });
      }

      // controllo di sicurezza: il risultato deve stare nel comune giusto,
      // altrimenti preferisco nessun pallino a un pallino sbagliato
      if (comune) {
        const dentro = (esito.address_components || []).some(c => semplifica(c.long_name) === semplifica(comune))
          || semplifica(esito.formatted_address).indexOf(semplifica(comune)) !== -1;
        if (!dentro) throw { code: 'COMUNE_DIVERSO', trovato: esito.formatted_address };
      }
      return esito.geometry.location;
    }

    for (let i = 0; i < lotto.length; i++) {
      const { record, indirizzo } = lotto[i];
      let posizione = null, codice = '';

      for (let tentativo = 0; tentativo < 2; tentativo++) {
        try { posizione = await geocodifica(record, indirizzo); break; }
        catch (e) {
          codice = (e && (e.code || e.message)) ? String(e.code || e.message) : 'ERRORE';
          if (codice !== 'OVER_QUERY_LIMIT') break;
          await attendi(1500); // Google ci sta frenando: respiro e riprovo una volta
        }
      }

      if (posizione) {
        const lat = typeof posizione.lat === 'function' ? posizione.lat() : posizione.lat;
        const lng = typeof posizione.lng === 'function' ? posizione.lng() : posizione.lng;
        record.lat = lat; record.lng = lng;               // aggiorno subito la copia in memoria
        aggiungiMarkerConcorrenza(map, bounds, record, { lat, lng });
        trovati++;
        try {   // salvo sul database: e' l'ultima volta che chiedo questo indirizzo a Google
          await fetch(`${API_CONCORRENZA}/${record._id}`, {
            method: 'PUT', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ lat, lng })
          });
        } catch (e) { console.warn('Coordinate non salvate per', record.titolo, e); }
      } else {
        falliti++;
        statiIncontrati[codice] = (statiIncontrati[codice] || 0) + 1;
        if (!primoIndirizzoFallito) primoIndirizzoFallito = `${indirizzo} \u2192 ${codice}`;
        console.warn('Geocoding non riuscito per', indirizzo, '->', codice);
        if (codice === 'REQUEST_DENIED') {   // inutile insistere: manca l'API sulla chiave
          scriviRiepilogo(daGeocodificare.length - i - 1, 0);
          if (trovati > 0) map.fitBounds(bounds);
          return;
        }
      }

      scriviRiepilogo(daGeocodificare.length - i - 1, lotto.length - i - 1);
      if (i < lotto.length - 1) await attendi(PAUSA_TRA_GEOCODING_MS);
    }

    if (trovati > 0) map.fitBounds(bounds);
    scriviRiepilogo(daGeocodificare.length - lotto.length, 0);
  }

  function continuaGeotagConcorrenza(quanti) {
    caricaGeotagConcorrenza(quanti);
  }

  /* A quale delle tre schede appartiene un annuncio.
     Non mi fido del valore esatto: gli import da Excel scrivono "Privato", "VDP", "vdp no numero"...
     Quindi riconosco anche le varianti, e leggo pure il nome dell'agenzia. */
  /* Quanto e' stata sviluppata l'informazione su un annuncio */
  /* ==== Ponte stato sviluppo <-> sub collegati, e legame civico <-> concorrenza ====
     Stesso modo di normalizzare comune/via/civico usato dal ponte
     Concorrenza->Censimento, cosi' i due lati combaciano. */
  function _normLoc(s){ return (s||'').normalize('NFKD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim(); }
  function _keyViaLoc(s){ const stop=new Set(['via','viale','piazza','piazzale','corso','vicolo','largo','strada','san','sant','della','delle','dei','del','di','da','de','la','lo']); return _normLoc(s).split(' ').filter(w=>w.length>1 && !stop.has(w) && !/^\d+$/.test(w)).sort().join(' '); }
  function _chiaveCivico(comune, via, civico){ return _normLoc(comune)+'|'+_keyViaLoc(via)+'|'+_normLoc(civico); }

  /* Opportunity collegate a un civico (match su comune+via+civico normalizzati) */
  let INDICE_OPP_CIVICO = null, INDICE_OPP_REF = null;
  function indiceOpportunityPerCivico(){
    if (INDICE_OPP_CIVICO && INDICE_OPP_REF === REGISTRO_OPPORTUNITY_CLOUD) return INDICE_OPP_CIVICO;
    const m = {};
    (REGISTRO_OPPORTUNITY_CLOUD || []).forEach(o => {
      if (!o.via || !o.civico) return;
      const k = _chiaveCivico(o.comune, o.via, o.civico);
      (m[k] = m[k] || []).push(o);
    });
    INDICE_OPP_CIVICO = m; INDICE_OPP_REF = REGISTRO_OPPORTUNITY_CLOUD; return m;
  }
  function opportunityDelCivico(comune, via, civico){ return indiceOpportunityPerCivico()[_chiaveCivico(comune, via, civico)] || []; }
  /* Vero se quel comune+via+civico esiste già nel censimento strutturato */
  function civicoNelCensimento(comune, via, civ){
    if (!via || !civ) return false;
    const k = _chiaveCivico(comune, via, civ);
    return (STRADARIO_LIVE_CLOUD || []).some(c => (c.vie || []).some(v => (v.civici || []).some(x => _chiaveCivico(c.comune, v.nome, x.numero) === k)));
  }

  /* Tondino con la foto del consulente (o iniziali). Il nome completo va messo
     come title sul contenitore, per vederlo al passaggio del mouse. */
  function tondinoConsulente(c, size){
    size = size || 30;
    const nome = c ? (c.nomeCognome || c.utente || '') : '';
    const iniz = nome ? nome.trim().split(/\s+/).slice(0, 2).map(w => w[0] || '').join('').toUpperCase() : '?';
    const base = `width:${size}px; height:${size}px; border-radius:50%; flex-shrink:0; box-sizing:border-box;`;
    const foto = (c && c.fotoProfilo) ? immagineDaDrive(c.fotoProfilo) : '';
    if (foto) return `<span style="${base} display:inline-block; overflow:hidden; border:1px solid rgba(255,255,255,.15);"><img src="${foto}" referrerpolicy="no-referrer" style="width:100%; height:100%; object-fit:cover; display:block;"></span>`;
    const sfondo = nome ? '#2a3f4a' : '#26292e';
    return `<span style="${base} display:flex; align-items:center; justify-content:center; background:${sfondo}; color:#C6A777; font-weight:700; font-size:${Math.round(size * 0.4)}px;">${iniz}</span>`;
  }

  /* ==========================================================================
     RICERCA POSIZIONE OPPORTUNITY ← CENSIMENTO STRUTTURATO
     Il campo "Posizione" apre una ricerca sui via/civico già censiti (filtrabile
     per comune). Scegliendone uno riempie comune/via/civico e li collega; se non
     esiste, dopo conferma crea il civico nel censimento.
  ========================================================================== */
  let RICERCA_POS_OPP = null, RICERCA_POS_RISULTATI = [];

  function apriRicercaPosizione(oppId) {
    const o = REGISTRO_OPPORTUNITY_CLOUD.find(x => x._id === oppId);
    if (!o) return;
    RICERCA_POS_OPP = oppId;
    let ov = document.getElementById('popup-ricerca-pos-overlay');
    if (!ov) {
      ov = document.createElement('div');
      ov.id = 'popup-ricerca-pos-overlay';
      ov.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,.6); z-index:100090; align-items:flex-start; justify-content:center; padding:40px 14px;';
      ov.innerHTML = `<div onclick="event.stopPropagation()" style="background:#202226; border:1px solid #3e4147; border-radius:12px; width:520px; max-width:96vw; max-height:82vh; display:flex; flex-direction:column; font-family:'Plus Jakarta Sans',sans-serif;">
        <div style="padding:18px 18px 10px;">
          <h3 style="margin:0 0 4px; color:#fff;">Posizione &middot; censimento strutturato</h3>
          <p style="margin:0 0 12px; color:#868b98; font-size:12px;">Scegli un via/civico gi&agrave; censito, oppure creane uno nuovo.</p>
          <div style="display:flex; gap:8px;">
            <select id="ricerca-pos-comune" onchange="filtraRicercaPosizione()" style="width:170px; padding:10px; background:#18191c; border:1px solid #3e4147; color:#fff; border-radius:6px;"></select>
            <input id="ricerca-pos-q" type="text" placeholder="Cerca via e civico&hellip; (es. Roma 12)" oninput="filtraRicercaPosizione()" style="flex:1; padding:10px; background:#18191c; border:1px solid #3e4147; color:#fff; border-radius:6px; box-sizing:border-box;">
          </div>
        </div>
        <div id="ricerca-pos-lista" style="overflow-y:auto; padding:0 18px 8px; flex:1;"></div>
        <div id="ricerca-pos-crea" style="padding:10px 18px;"></div>
        <div style="padding:8px 18px 16px; text-align:right; border-top:1px solid #2f3136;"><button onclick="chiudiRicercaPosizione()" style="background:#292b2f; border:1px solid #3e4147; color:#cbd5e1; padding:8px 16px; border-radius:6px; cursor:pointer;">Chiudi</button></div>
      </div>`;
      ov.addEventListener('click', chiudiRicercaPosizione);
      document.body.appendChild(ov);
    }
    if (ov.parentNode !== document.body) document.body.appendChild(ov);
    const comuneIniziale = (o.comune && (STRADARIO_LIVE_CLOUD || []).some(c => c.comune === o.comune)) ? o.comune : 'tutti';
    ov.querySelector('#ricerca-pos-comune').innerHTML = `<option value="tutti">Tutti i comuni</option>` +
      (STRADARIO_LIVE_CLOUD || []).map(c => `<option value="${propEsc(c.comune)}" ${c.comune === comuneIniziale ? 'selected' : ''}>${propEsc(c.comune)}</option>`).join('');
    ov.querySelector('#ricerca-pos-q').value = [o.via, o.civico].filter(Boolean).join(' ');
    ov.style.display = 'flex';
    filtraRicercaPosizione();
    setTimeout(() => { const q = ov.querySelector('#ricerca-pos-q'); if (q) q.focus(); }, 60);
  }

  function chiudiRicercaPosizione() { const ov = document.getElementById('popup-ricerca-pos-overlay'); if (ov) ov.style.display = 'none'; RICERCA_POS_OPP = null; }

  /* "Via Roma 12/A" -> {via:'Via Roma', civico:'12/A'} */
  function parsePosizione(raw) {
    const s = String(raw || '').trim();
    const m = s.match(/^(.*?)[,\s]+(\d+\s*[\/\-]?\s*[a-zA-Z]?)\s*$/);
    if (m) return { via: m[1].trim(), civico: m[2].replace(/\s+/g, '').trim() };
    return { via: s, civico: '' };
  }

  function filtraRicercaPosizione() {
    const ov = document.getElementById('popup-ricerca-pos-overlay'); if (!ov) return;
    const comune = ov.querySelector('#ricerca-pos-comune').value;
    const raw = ov.querySelector('#ricerca-pos-q').value;
    const tokens = _normLoc(raw).split(' ').filter(Boolean);
    const comuni = (STRADARIO_LIVE_CLOUD || []).filter(c => comune === 'tutti' || c.comune === comune);
    const risultati = [];
    comuni.forEach(c => (c.vie || []).forEach(v => (v.civici || []).forEach(x => {
      const testo = _normLoc(c.comune + ' ' + v.nome + ' ' + x.numero);
      if (!tokens.length || tokens.every(t => testo.indexOf(t) !== -1)) risultati.push({ comune: c.comune, via: v.nome, civico: String(x.numero) });
    })));
    risultati.sort((a, b) => (a.via + ' ' + a.civico).localeCompare(b.via + ' ' + b.civico));
    RICERCA_POS_RISULTATI = risultati;
    const lista = ov.querySelector('#ricerca-pos-lista');
    lista.innerHTML = risultati.length ? risultati.slice(0, 250).map((r, i) => {
      const nOpp = opportunityDelCivico(r.comune, r.via, r.civico).length;
      return `<div onclick="scegliPosizioneOpp(${i})" style="display:flex; align-items:center; gap:9px; padding:9px 10px; border-radius:7px; cursor:pointer; border-bottom:1px solid #2a2c31;">
        <i class="fa-solid fa-location-dot" style="color:#0086d6;"></i>
        <div style="flex:1; min-width:0;"><div style="color:#fff; font-size:13.5px;">${propEsc(r.via)} <strong>${propEsc(r.civico)}</strong></div>
          <div style="color:#5f6672; font-size:11px;">${propEsc(r.comune)}</div></div>
        ${nOpp ? `<span style="background:#10b98122; color:#10b981; font-size:10px; font-weight:700; padding:2px 7px; border-radius:9px;">${nOpp} opp.</span>` : ''}
      </div>`;
    }).join('') : `<div style="color:#5f6672; text-align:center; padding:24px 0; font-size:13px;">Nessun civico trovato.</div>`;

    const crea = ov.querySelector('#ricerca-pos-crea');
    const parsed = parsePosizione(raw);
    if (raw.trim() && parsed.via && parsed.civico && comune !== 'tutti' && !civicoNelCensimento(comune, parsed.via, parsed.civico)) {
      crea.innerHTML = `<button onclick="creaPosizioneNuova()" style="width:100%; background:#0d3b2e; border:1px solid #1c6b4f; color:#6EE7A8; padding:11px; border-radius:8px; cursor:pointer; font-weight:700; font-size:13px;"><i class="fa-solid fa-plus"></i> Crea &laquo;${propEsc(parsed.via)} ${propEsc(parsed.civico)}&raquo; in ${propEsc(comune)}</button>`;
    } else if (raw.trim() && parsed.via && parsed.civico && comune === 'tutti') {
      crea.innerHTML = `<div style="color:#868b98; font-size:11.5px; text-align:center;">Scegli un comune preciso per poter creare un nuovo civico.</div>`;
    } else { crea.innerHTML = ''; }
  }

  function scegliPosizioneOpp(i) {
    const r = RICERCA_POS_RISULTATI[i]; if (!r || !RICERCA_POS_OPP) return;
    applicaPosizioneOpportunity(RICERCA_POS_OPP, r.comune, r.via, r.civico);
    chiudiRicercaPosizione();
  }

  async function applicaPosizioneOpportunity(id, comune, via, civico) {
    const o = REGISTRO_OPPORTUNITY_CLOUD.find(x => x._id === id); if (!o) return;
    o.comune = comune; o.via = via; o.civico = civico; o.unitaCensId = '';   // cambiato civico: azzero l'unità scelta
    o.posizione = [via, civico].filter(Boolean).join(' ') + (comune ? (' — ' + comune) : '');
    INDICE_OPP_CIVICO = null;
    disegnaTabellaOpportunity();
    try {
      await fetch(`${API_OPPORTUNITY}/${id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ comune, via, civico, posizione: o.posizione, unitaCensId: '' }) });
    } catch (e) { alert('Posizione non salvata sul server, riprova.'); }
    // contesto e note a specchio col censimento
    await sincronizzaContestoConCensimento(o);
    disegnaTabellaOpportunity();
  }

  async function creaPosizioneNuova() {
    const ov = document.getElementById('popup-ricerca-pos-overlay'); if (!ov) return;
    const comune = ov.querySelector('#ricerca-pos-comune').value;
    const parsed = parsePosizione(ov.querySelector('#ricerca-pos-q').value);
    if (comune === 'tutti' || !parsed.via || !parsed.civico) { alert('Scegli un comune e scrivi via e numero (es. "Roma 12").'); return; }
    if (!confirm(`«${parsed.via} ${parsed.civico}» non è nel censimento di ${comune}.\n\nLo creo ora nel censimento strutturato?`)) return;
    const c = (STRADARIO_LIVE_CLOUD || []).find(x => x.comune === comune);
    if (!c) { alert('Comune non presente nel censimento.'); return; }
    let via = (c.vie || []).find(v => _keyViaLoc(v.nome) === _keyViaLoc(parsed.via));
    if (!via) { via = { nome: parsed.via, zone: 'CENTRO', civici: [] }; (c.vie = c.vie || []).push(via); }
    if (!(via.civici || []).some(x => _normLoc(x.numero) === _normLoc(parsed.civico))) {
      via.civici = via.civici || [];
      via.civici.push({ numero: parsed.civico, citofoni: [], proprietariNonResidenti: [] });
    }
    try {
      const res = await fetch(`${API_STRADARIO}/${c._id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ vie: c.vie }) });
      if (!res.ok) throw new Error('server');
    } catch (e) { alert('Non riuscito a salvare nel censimento, riprova.'); return; }
    await applicaPosizioneOpportunity(RICERCA_POS_OPP, comune, via.nome, parsed.civico);
    chiudiRicercaPosizione();
    alert('Creato nel censimento e collegato ✓');
  }

  /* I nomi dei proprietari censiti a un civico (unità non residenti + citofoni), senza doppioni */
  function proprietariDelCivico(civ) {
    const nomi = new Set();
    (civ.proprietariNonResidenti || []).forEach(u => (u.proprietari || []).forEach(p => { const n = (p.nomeCognome || '').trim(); if (n) nomi.add(n); }));
    (civ.citofoni || []).forEach(c => { const n = (c.nomeCognomeCf || c.nome || '').trim(); if (n && n.toUpperCase() !== 'N.D.') nomi.add(n); });
    return Array.from(nomi);
  }

  /* Tutte le unità di un civico (unità non residenti + citofoni), normalizzate */
  function unitaCensimentoDi(civ) {
    if (!civ) return [];
    const all = [];
    (civ.proprietariNonResidenti || []).forEach(u => all.push({
      id: String(u._id || ''), tipo: 'pnr', piano: u.piano || '', mq: u.mq || '', sub: u.sub || '', vani: u.vani || '',
      proprietari: (u.proprietari || []).map(p => (p.nomeCognome || '').trim()).filter(Boolean)
    }));
    (civ.citofoni || []).forEach(c => { const n = (c.nomeCognomeCf || c.nome || '').trim();
      all.push({ id: String(c._id || ''), tipo: 'cit', piano: c.piano || '', mq: c.mq || '', sub: c.sub || '', vani: c.vani || '',
        proprietari: (n && n.toUpperCase() !== 'N.D.') ? [n] : [] });
    });
    return all;
  }
  /* L'unità scelta per un'opportunity (o null se non scelta / non trovata) */
  function unitaSceltaOpp(o) {
    if (!o || !o.unitaCensId) return null;
    const link = civicoCollegatoOpp(o); if (!link) return null;
    return unitaCensimentoDi(link.civ).find(u => u.id && u.id === String(o.unitaCensId)) || null;
  }

  /* Un'unità rappresentativa del civico per leggere Piano/Mq (la prima con dati) */
  function unitaRappCivico(civ) {
    return unitaCensimentoDi(civ).find(u => u.piano || u.mq) || unitaCensimentoDi(civ)[0] || null;
  }

  /* Il civico del censimento collegato a un'opportunity (o null) */
  function civicoCollegatoOpp(o) {
    if (!o || !o.via || !o.civico) return null;
    const k = _chiaveCivico(o.comune, o.via, o.civico);
    for (const c of (STRADARIO_LIVE_CLOUD || []))
      for (const v of (c.vie || []))
        for (const x of (v.civici || []))
          if (_chiaveCivico(c.comune, v.nome, x.numero) === k) return { comDoc: c, civ: x };
    return null;
  }

  /* Scrive un campo sul civico del censimento collegato e salva */
  async function scriviCampoCivicoCollegato(o, campoCensus, valore) {
    const link = civicoCollegatoOpp(o);
    if (!link) return false;
    link.civ[campoCensus] = valore;
    try { await fetch(`${API_STRADARIO}/${link.comDoc._id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ vie: link.comDoc.vie }) }); }
    catch (e) { return false; }
    return true;
  }

  /* Allinea contesto e note tra opportunity e censimento quando si collega:
     il censimento è la fonte; se lì è vuoto, si porta su il valore dell'opportunity. */
  async function sincronizzaContestoConCensimento(o) {
    const link = civicoCollegatoOpp(o); if (!link) return;
    const civ = link.civ;
    let salvaCensus = false, salvaOpp = {};
    if (civ.contestoCivico) { if (o.tipologiaContesto !== civ.contestoCivico) { o.tipologiaContesto = civ.contestoCivico; salvaOpp.tipologiaContesto = civ.contestoCivico; } }
    else if (o.tipologiaContesto) { civ.contestoCivico = o.tipologiaContesto; salvaCensus = true; }
    if (civ.note) { if (o.noteContesto !== civ.note) { o.noteContesto = civ.note; salvaOpp.noteContesto = civ.note; } }
    else if (o.noteContesto) { civ.note = o.noteContesto; salvaCensus = true; }
    if (salvaCensus) { try { await fetch(`${API_STRADARIO}/${link.comDoc._id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ vie: link.comDoc.vie }) }); } catch (e) {} }
    if (Object.keys(salvaOpp).length) { try { await fetch(`${API_OPPORTUNITY}/${o._id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(salvaOpp) }); } catch (e) {} }
  }

  /* Modifica di Tipologia Contesto dall'opportunity: aggiorna l'opportunity e,
     se collegata, scrive anche sul censimento (specchio). */
  async function aggiornaContestoOpp(id, valore) {
    const o = REGISTRO_OPPORTUNITY_CLOUD.find(x => x._id === id); if (!o) return;
    o.tipologiaContesto = valore;
    disegnaTabellaOpportunity();
    try { await fetch(`${API_OPPORTUNITY}/${id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ campo: 'tipologiaContesto', valore }) }); } catch (e) {}
    await scriviCampoCivicoCollegato(o, 'contestoCivico', valore);
  }
  async function aggiornaNoteContestoOpp(id, valore) {
    const o = REGISTRO_OPPORTUNITY_CLOUD.find(x => x._id === id); if (!o) return;
    o.noteContesto = valore;
    try { await fetch(`${API_OPPORTUNITY}/${id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ campo: 'noteContesto', valore }) }); } catch (e) {}
    await scriviCampoCivicoCollegato(o, 'note', valore);
  }

  /* Selettore dell'unità del civico (proprietario) per l'opportunity: da lì Piano/Mq
     e il nome tra parentesi seguono l'unità scelta. */
  function apriPickerUnitaOpp(oppId) {
    const o = REGISTRO_OPPORTUNITY_CLOUD.find(x => x._id === oppId); if (!o) return;
    const link = civicoCollegatoOpp(o);
    if (!link) { alert('Prima collega la posizione (via e civico) a un civico del censimento.'); return; }
    const unita = unitaCensimentoDi(link.civ);
    let ov = document.getElementById('popup-unita-opp-overlay');
    if (!ov) {
      ov = document.createElement('div'); ov.id = 'popup-unita-opp-overlay';
      ov.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,.6); z-index:100092; align-items:flex-start; justify-content:center; padding:50px 14px;';
      ov.addEventListener('click', chiudiPickerUnita);
      document.body.appendChild(ov);
    }
    if (ov.parentNode !== document.body) document.body.appendChild(ov);
    const righe = unita.length ? unita.map(u => {
      const nomi = u.proprietari.length ? propEsc(u.proprietari.join(', ')) : '<span style="color:#5f6672">(senza nominativo)</span>';
      const meta = [u.piano ? ('Piano ' + u.piano) : '', u.sub ? ('sub ' + u.sub) : '', u.mq ? (u.mq + ' mq') : '', u.vani ? (u.vani + ' vani') : ''].filter(Boolean).join(' · ');
      const sel = o.unitaCensId === u.id;
      return `<div onclick="scegliUnitaOpp('${o._id}','${u.id}')" style="padding:11px 12px; border:1px solid ${sel ? '#C6A777' : '#2f3136'}; background:${sel ? '#2a2419' : '#18191c'}; border-radius:8px; margin-bottom:7px; cursor:pointer;">
        <div style="color:#fff; font-size:13.5px; font-weight:600;">${nomi}</div>
        <div style="color:#868b98; font-size:11.5px; margin-top:2px;">${meta || 'nessun dettaglio'}</div></div>`;
    }).join('') : `<div style="color:#5f6672; text-align:center; padding:22px 0; font-size:13px;">Nessuna unità censita a questo civico.<br>Aggiungile dal Censimento Strutturato.</div>`;
    ov.innerHTML = `<div onclick="event.stopPropagation()" style="background:#202226; border:1px solid #3e4147; border-radius:12px; width:480px; max-width:96vw; max-height:80vh; overflow-y:auto; padding:20px; font-family:'Plus Jakarta Sans',sans-serif;">
      <h3 style="margin:0 0 4px; color:#fff;">Unità del civico</h3>
      <p style="margin:0 0 14px; color:#868b98; font-size:12px;">${propEsc(link.comDoc.comune)} &middot; ${propEsc(o.via)} ${propEsc(o.civico)} — scegli l'unità/proprietario di questa opportunity.</p>
      ${righe}
      <div style="display:flex; gap:10px; justify-content:space-between; margin-top:14px;">
        <button onclick="scegliUnitaOpp('${o._id}','')" style="background:#292b2f; border:1px solid #3e4147; color:#cbd5e1; padding:8px 14px; border-radius:6px; cursor:pointer;">Nessuna (tutte)</button>
        <button onclick="chiudiPickerUnita()" style="background:#292b2f; border:1px solid #3e4147; color:#cbd5e1; padding:8px 16px; border-radius:6px; cursor:pointer;">Chiudi</button>
      </div>
    </div>`;
    ov.style.display = 'flex';
  }
  function chiudiPickerUnita() { const ov = document.getElementById('popup-unita-opp-overlay'); if (ov) ov.style.display = 'none'; }
  async function scegliUnitaOpp(oppId, unitaId) {
    const o = REGISTRO_OPPORTUNITY_CLOUD.find(x => x._id === oppId); if (!o) return;
    o.unitaCensId = unitaId || '';
    disegnaTabellaOpportunity();
    try { await fetch(`${API_OPPORTUNITY}/${oppId}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ campo: 'unitaCensId', valore: o.unitaCensId }) }); } catch (e) {}
    chiudiPickerUnita();
  }

  /* Il nome del proprietario "principale" di un'opportunity (unità scelta, o primo del civico) */
  function proprietarioPrincipaleOpp(o) {
    const scelta = unitaSceltaOpp(o);
    if (scelta && scelta.proprietari.length) return scelta.proprietari[0];
    const link = civicoCollegatoOpp(o);
    if (link) { const pr = proprietariDelCivico(link.civ); if (pr.length) return pr[0]; }
    return '';
  }
  /* Chiave nome robusta: minuscolo, senza punteggiatura, parole ordinate
     (così "Mario Rossi" combacia con "Rossi Mario") */
  function _nomeKey(nome) {
    return _normLoc(nome).split(' ').filter(w => w.length > 1).sort().join(' ');
  }
  /* Tutti i nominativi dei proprietari legati all'opportunity (unità scelta, o tutto il civico) */
  function nomiProprietarioOpp(o) {
    const scelta = unitaSceltaOpp(o);
    if (scelta && scelta.proprietari.length) return scelta.proprietari;
    const link = civicoCollegatoOpp(o);
    if (link) return proprietariDelCivico(link.civ);
    return [];
  }
  /* Il contatto in Anagrafica Proprietari (capitale-sociale) legato all'opportunity:
     cerca fra TUTTI i proprietari dell'unità/civico, non solo il primo */
  function contattoAnagraficaDiOpp(o) {
    const chiavi = nomiProprietarioOpp(o).map(_nomeKey).filter(Boolean);
    if (!chiavi.length) return null;
    return (DATA_CAPITALE_SOCIALE || []).find(c => chiavi.indexOf(_nomeKey(c.nome)) !== -1) || null;
  }
  /* Le opportunity legate a un proprietario (per nome), per mostrarle in Anagrafica */
  function opportunityPerProprietario(nome) {
    const k = _nomeKey(nome); if (!k) return [];
    return (REGISTRO_OPPORTUNITY_CLOUD || []).filter(o => {
      const link = civicoCollegatoOpp(o); if (!link) return false;
      const scelta = unitaSceltaOpp(o);
      const nomi = (scelta && scelta.proprietari.length) ? scelta.proprietari : proprietariDelCivico(link.civ);
      return nomi.some(x => _nomeKey(x) === k);
    });
  }
  /* Scrive il telefono sull'opportunity e, se c'è un contatto Anagrafica legato, anche lì (specchio) */
  async function aggiornaTelefonoOpp(id, valore) {
    const o = REGISTRO_OPPORTUNITY_CLOUD.find(x => x._id === id); if (!o) return;
    o.telefono = valore;
    try { await fetch(`${API_OPPORTUNITY}/${id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ campo: 'telefono', valore }) }); } catch (e) {}
    let contatto = contattoAnagraficaDiOpp(o);
    if (contatto) {
      // esiste già in Anagrafica: aggiorno il telefono (specchio)
      contatto.tel = valore;
      try { await fetch(`${API_CAPITALE_SOCIALE}/${contatto._id}/dettagli`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ tel: valore }) }); } catch (e) {}
    } else {
      // non esiste ancora: se c'è un proprietario (dall'unità collegata) lo CREO in Anagrafica col telefono
      const nome = proprietarioPrincipaleOpp(o);
      if (nome && String(valore).trim()) {
        try {
          const res = await fetch(API_CAPITALE_SOCIALE, {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ nome: nome, tel: valore, inseritoDa: (UTENTE_CONNESSO ? UTENTE_CONNESSO.utente : '') })
          });
          if (res.ok) { const j = await res.json(); const nuovo = (j && j.data) ? j.data : j; if (nuovo && nuovo._id) DATA_CAPITALE_SOCIALE.push(nuovo); }
        } catch (e) {}
      }
    }
    disegnaTabellaOpportunity();
  }

  /* Combina prefisso (tendina) + numero locale e salva */
  function componiTelefonoOpp(id) {
    const selP = document.querySelector(`[data-tel-prefix="telopp-${id}"]`);
    const inpL = document.querySelector(`[data-tel-local="telopp-${id}"]`);
    if (!selP || !inpL) return;
    const pref = selP.value;
    const loc = inpL.value.trim();
    let numero = '';
    if (loc) numero = loc.startsWith('+') ? loc : (pref + ' ' + loc);
    aggiornaTelefonoOpp(id, numero);
  }

  /* Il citofono del censimento collegato all'opportunity (per lo storico attività), o null */
  function citofonoCollegatoOpp(o) {
    const link = civicoCollegatoOpp(o); if (!link) return null;
    if (o.unitaCensId) { const cit = (link.civ.citofoni || []).find(c => String(c._id || '') === String(o.unitaCensId)); if (cit) return cit; }
    return null;
  }

  /* Report attività: tutto quello che è stato fatto con questo contatto */
  function apriReportOpportunity(id) {
    const o = REGISTRO_OPPORTUNITY_CLOUD.find(x => x._id === id); if (!o) return;
    const link = civicoCollegatoOpp(o);
    const scelta = unitaSceltaOpp(o);
    let contatto = '';
    if (scelta && scelta.proprietari.length) contatto = scelta.proprietari.join(', ');
    else if (link) { const pr = proprietariDelCivico(link.civ); contatto = pr.join(', '); }
    const cit = citofonoCollegatoOpp(o);
    /* la cronologia mette insieme le attività fatte sul citofono del censimento
       e quelle registrate direttamente qui (quando non c'è un citofono collegato) */
    const storico = (cit ? (cit.attivita || []) : []).concat(o.attivita || [])
      .slice().sort((a, b) => String(b.quando || '').localeCompare(String(a.quando || '')));

    // countdown prossima
    let cd = '';
    if (o.dataProssimaAttivita) { const g = giorniDaOggi(o.dataProssimaAttivita);
      cd = g === null ? '' : g > 0 ? `<span style="color:#00c875; font-weight:700;">tra ${g} gg</span>` : g < 0 ? `<span style="color:#f43f5e; font-weight:700;">in ritardo di ${-g} gg</span>` : `<span style="color:#e2b13c; font-weight:700;">oggi</span>`; }

    const rigaRiepilogo = (etichetta, valore) => `<div style="display:flex; justify-content:space-between; padding:8px 0; border-bottom:1px solid #2a2c31;"><span style="color:#868b98; font-size:12.5px;">${etichetta}</span><span style="color:#e8ecf1; font-size:12.5px; font-weight:600;">${valore || '—'}</span></div>`;

    const storicoHtml = storico.length ? storico.map(a => {
      const v = vistaAttivita(a.tipo);
      return `<div style="padding:10px 0; border-bottom:1px solid #2a2c31;">
        <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap;">
          <span style="background:${v.colore}22; color:${v.colore}; border:1px solid ${v.colore}55; font-size:11px; font-weight:700; padding:3px 9px; border-radius:8px;">${v.testo}</span>
          <span style="color:#7d8b93; font-size:11.5px;">${propEsc(dataBreveAttivita(a.quando))}</span>
          <button onclick="eliminaAttivitaReportOpp('${id}', '${a.quando}')" title="Elimina attività"
            style="margin-left:auto; background:none; border:none; color:#5b6167; font-size:17px; cursor:pointer; line-height:1; padding:0 2px;">&times;</button>
        </div>
        ${a.nota
          ? `<div onclick="aggiungiNotaReportOpp('${id}', '${a.quando}')" title="Modifica il feedback"
              style="color:#cbd5e1; font-size:12px; margin-top:6px; background:#18191c; border-radius:8px; padding:8px 10px; cursor:pointer; line-height:1.5;">« ${propEsc(a.nota)} »</div>`
          : `<div onclick="aggiungiNotaReportOpp('${id}', '${a.quando}')"
              style="color:#5f6672; font-size:11.5px; margin-top:5px; cursor:pointer;">+ aggiungi feedback</div>`}
      </div>`;
    }).join('') : `<div style="color:#5f6672; text-align:center; padding:16px 0; font-size:12.5px;">${cit ? 'Nessuna attività registrata su questo contatto.' : 'Nessuno storico: collega una unità/citofono del censimento per vedere tutte le attività fatte con il contatto.'}</div>`;

    let ov = document.getElementById('popup-report-opp-overlay');
    if (!ov) {
      ov = document.createElement('div'); ov.id = 'popup-report-opp-overlay';
      ov.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,.6); z-index:100093; align-items:flex-start; justify-content:center; padding:44px 14px;';
      ov.addEventListener('click', chiudiReportOpp);
      document.body.appendChild(ov);
    }
    if (ov.parentNode !== document.body) document.body.appendChild(ov);
    ov.innerHTML = `<div onclick="event.stopPropagation()" style="background:#202226; border:1px solid #3e4147; border-radius:12px; width:520px; max-width:96vw; max-height:84vh; overflow-y:auto; padding:20px; font-family:'Plus Jakarta Sans',sans-serif;">
      <h3 style="margin:0 0 2px; color:#fff;">📋 Report attività</h3>
      <p style="margin:0 0 14px; color:#868b98; font-size:12.5px;">${propEsc(o.nome || 'Opportunity')}${contatto ? ' · <span style="color:#C6A777;">' + propEsc(contatto) + '</span>' : ''}${link ? ' · ' + propEsc([o.via, o.civico, o.comune].filter(Boolean).join(' ')) : ''}</p>
      <div style="background:#18191c; border:1px solid #2f3136; border-radius:9px; padding:12px 14px; margin-bottom:16px;">
        ${rigaRiepilogo('Giri attività', (o.giriAttivita || 0) + ' / 5')}
        ${rigaRiepilogo('Ultima attività', [o.dataUltimaAttivita ? propData(o.dataUltimaAttivita) : '', o.esitoUltimaAttivita || ''].filter(Boolean).join(' · '))}
        ${rigaRiepilogo('Prossima attività', [o.dataProssimaAttivita ? propData(o.dataProssimaAttivita) : '', cd].filter(Boolean).join(' · '))}
      </div>
      <div style="color:#C6A777; font-size:11px; text-transform:uppercase; letter-spacing:.8px; font-weight:700; margin-bottom:8px;">Registra un'attività</div>
      <div style="display:flex; gap:8px; flex-wrap:wrap; margin-bottom:18px;">
        ${AZIONI_REPORT_OPP.map(az =>
          `<button onclick="aggiungiAttivitaReportOpp('${o._id}', '${az.tipo}')"
            style="background:#18191c; border:1px solid ${az.colore}66; color:${az.colore}; padding:9px 13px;
                   border-radius:9px; font-size:12.5px; font-weight:700; cursor:pointer; font-family:inherit;
                   display:inline-flex; align-items:center; gap:6px;">
            <span style="font-size:14px;">${az.emoji}</span>${az.etichetta}<span style="font-size:13px;">${az.esito}</span></button>`).join('')}
      </div>
      <div style="color:#C6A777; font-size:11px; text-transform:uppercase; letter-spacing:.8px; font-weight:700; margin-bottom:6px;">Cronologia con il contatto${storico.length ? ' (' + storico.length + ')' : ''}</div>
      ${storicoHtml}
      <div style="text-align:right; margin-top:16px;"><button onclick="chiudiReportOpp()" style="background:#292b2f; border:1px solid #3e4147; color:#cbd5e1; padding:8px 16px; border-radius:6px; cursor:pointer;">Chiudi</button></div>
    </div>`;
    ov.style.display = 'flex';
  }
  function chiudiReportOpp() { const ov = document.getElementById('popup-report-opp-overlay'); if (ov) ov.style.display = 'none'; }

  /* Registra una nuova attività dal Report dell'Opportunity. Se c'è un citofono
     del censimento collegato la scrive lì (così si vede anche nel censimento);
     altrimenti la salva sull'Opportunity stessa. Poi ridisegna il report. */
  async function aggiungiAttivitaReportOpp(id, tipo) {
    const o = REGISTRO_OPPORTUNITY_CLOUD.find(x => x._id === id); if (!o) return;
    const nuova = { tipo: tipo, quando: new Date().toISOString(), nota: '',
                    consulente: (typeof UTENTE_CONNESSO !== 'undefined' && UTENTE_CONNESSO) ? UTENTE_CONNESSO.utente : '' };
    const cit = citofonoCollegatoOpp(o);
    try {
      if (cit) {
        if (!cit.attivita) cit.attivita = [];
        cit.attivita.push(nuova);
        const link = civicoCollegatoOpp(o);
        if (link) await fetch(`${API_STRADARIO}/${link.comDoc._id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ vie: link.comDoc.vie }) });
      } else {
        if (!o.attivita) o.attivita = [];
        o.attivita.push(nuova);
        await fetch(`${API_OPPORTUNITY}/${id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ attivita: o.attivita }) });
      }
      /* tengo aggiornato anche il riepilogo "ultima attività" dell'Opportunity */
      o.dataUltimaAttivita = nuova.quando; o.esitoUltimaAttivita = tipo;
      try { await fetch(`${API_OPPORTUNITY}/${id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ dataUltimaAttivita: o.dataUltimaAttivita, esitoUltimaAttivita: o.esitoUltimaAttivita }) }); } catch (e) {}
    } catch (e) { console.error('Attività non salvata:', e); alert('Non sono riuscito a salvare l\'attività. Riprova.'); return; }
    apriReportOpportunity(id);   // ridisegna con la nuova attività in cima
  }

  /* Salva dove sta davvero l'attività: sul citofono del censimento o sull'Opportunity */
  async function _salvaContenitoreAttivita(o, suCitofono) {
    if (suCitofono) { const link = civicoCollegatoOpp(o); if (link) await fetch(`${API_STRADARIO}/${link.comDoc._id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ vie: link.comDoc.vie }) }); }
    else await fetch(`${API_OPPORTUNITY}/${o._id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ attivita: o.attivita || [] }) });
  }

  /* Feedback (nota) di un'attività del report */
  async function aggiungiNotaReportOpp(id, quando) {
    const o = REGISTRO_OPPORTUNITY_CLOUD.find(x => x._id === id); if (!o) return;
    const cit = citofonoCollegatoOpp(o);
    let att = cit && (cit.attivita || []).find(x => String(x.quando) === String(quando));
    const suCitofono = !!att;
    if (!att) att = (o.attivita || []).find(x => String(x.quando) === String(quando));
    if (!att) return;
    const nota = prompt('Feedback dell\'attività — cosa è successo?\n\n(lascia vuoto per togliere il feedback)', att.nota || '');
    if (nota === null) return;
    att.nota = nota.trim();
    try { await _salvaContenitoreAttivita(o, suCitofono); } catch (e) { console.error('Feedback non salvato:', e); }
    apriReportOpportunity(id);
  }

  /* Elimina un'attività del report */
  async function eliminaAttivitaReportOpp(id, quando) {
    const o = REGISTRO_OPPORTUNITY_CLOUD.find(x => x._id === id); if (!o) return;
    if (!confirm('Eliminare questa attività?')) return;
    const cit = citofonoCollegatoOpp(o);
    let suCitofono = false;
    if (cit && (cit.attivita || []).some(x => String(x.quando) === String(quando))) {
      cit.attivita = cit.attivita.filter(x => String(x.quando) !== String(quando));
      suCitofono = true;
    } else if (o.attivita) {
      o.attivita = o.attivita.filter(x => String(x.quando) !== String(quando));
    }
    try { await _salvaContenitoreAttivita(o, suCitofono); } catch (e) { console.error('Attività non eliminata:', e); }
    apriReportOpportunity(id);
  }

  /* Per ogni civico censito conto due cose, che fanno salire lo stato sviluppo:
       - unita  = quante unita' da visura ha (proprietariNonResidenti): sono i
                  proprietari trovati -> "+ Proprietari"
       - collegati = quante di quelle unita' sono collegate a un citofono
                  (gruppiCollegatiIds): sai chi e' davvero -> "Proprietario 100%"
     Indicizzato una volta e rifatto quando il registro cambia o dopo un
     collegamento (cache azzerata in chiudiPopupCivico). */
  let INDICE_SUB_COLLEGATI = null, INDICE_SUB_REF = null;
  function indiceSubCollegati(){
    if (INDICE_SUB_COLLEGATI && INDICE_SUB_REF === STRADARIO_LIVE_CLOUD) return INDICE_SUB_COLLEGATI;
    const m = {};
    (STRADARIO_LIVE_CLOUD || []).forEach(c => {
      const nc = _normLoc(c.comune);
      (c.vie || []).forEach(v => {
        const kv = _keyViaLoc(v.nome);
        (v.civici || []).forEach(civ => {
          const ids = new Set();
          (civ.citofoni || []).forEach(cit => (cit.gruppiCollegatiIds || []).forEach(g => { if (g) ids.add(String(g)); }));
          const unita = (civ.proprietariNonResidenti || []).length;
          const k = nc + '|' + kv + '|' + _normLoc(civ.numero);
          const pre = m[k] || { unita: 0, collegati: 0 };
          m[k] = { unita: Math.max(pre.unita, unita), collegati: Math.max(pre.collegati, ids.size) };
        });
      });
    });
    INDICE_SUB_COLLEGATI = m; INDICE_SUB_REF = STRADARIO_LIVE_CLOUD;
    return m;
  }
  function datiSviluppoDelLead(r){
    if (!r || !r.comune || !r.via || !r.civico) return { unita: 0, collegati: 0 };
    return indiceSubCollegati()[_chiaveCivico(r.comune, r.via, r.civico)] || { unita: 0, collegati: 0 };
  }

  /* I lead di concorrenza che stanno sullo stesso civico (comune+via+civico).
     Serve al tondino nell'Esplora Territorio. */
  let INDICE_CONC_CIVICO = null, INDICE_CONC_REF = null;
  function indiceConcorrenzaPerCivico(){
    if (INDICE_CONC_CIVICO && INDICE_CONC_REF === REGISTRO_CONCORRENZA_CLOUD) return INDICE_CONC_CIVICO;
    const m = {};
    (REGISTRO_CONCORRENZA_CLOUD || []).forEach(r => {
      const civ = String(r.civico || '').trim();
      if (!r.comune || !r.via || !civ || civ.toUpperCase() === 'N.D.') return;
      const k = _chiaveCivico(r.comune, r.via, r.civico);
      (m[k] = m[k] || []).push(r);
    });
    INDICE_CONC_CIVICO = m; INDICE_CONC_REF = REGISTRO_CONCORRENZA_CLOUD;
    return m;
  }
  function concorrenzaDelCivico(comune, via, civico){
    return indiceConcorrenzaPerCivico()[_chiaveCivico(comune, via, civico)] || [];
  }

  /* Popup che mostra i lead di concorrenza collegati a un civico. Si apre
     dal tondino nell'Esplora Territorio. Sta sul body come gli altri popup. */
  function apriPopupConcorrenzaCivico(idxComune, idxVia, idxCivico){
    const c = (STRADARIO_LIVE_CLOUD || [])[idxComune];
    const v = c && c.vie && c.vie[idxVia];
    const civ = v && v.civici && v.civici[idxCivico];
    if (!civ) return;
    const leads = concorrenzaDelCivico(c.comune, v.nome, civ.numero);
    if (!leads.length) return;
    let ov = document.getElementById('popup-conc-civico-overlay');
    if (!ov) {
      ov = document.createElement('div');
      ov.id = 'popup-conc-civico-overlay';
      ov.style.cssText = 'position:fixed; inset:0; z-index:100050; background:rgba(0,0,0,.6); display:flex; align-items:flex-start; justify-content:center; padding:32px 16px; overflow:auto;';
      ov.onclick = (e) => { if (e.target === ov) ov.style.display = 'none'; };
      ov.innerHTML = '<div style="background:#141619; border:1px solid #2e3238; border-radius:12px; width:min(680px,96vw); box-shadow:0 20px 70px rgba(0,0,0,.6);"><div id="popup-conc-civico-body"></div></div>';
      document.body.appendChild(ov);
    }
    const euroMq = (r) => { const p = parseFloat(String(r.prezzo||'').replace(/[^0-9]/g,'')); return (p && r.mq) ? Math.round(p / r.mq).toLocaleString('it-IT') + ' &euro;/mq' : ''; };
    const statoColore = { 'Attivo':'#2f5a3f', 'Venduto':'#5a2f3a', 'Ritirato':'#4a4a2a' };
    const cards = leads.map(r => {
      const sv = statoSviluppoDi(r);
      const cons = (typeof REGISTRO_CONSULENTI !== 'undefined' ? REGISTRO_CONSULENTI : []).find(x => x.utente === r.consulente);
      return `<div style="background:#1a1d21; border:1px solid #2e3238; border-radius:9px; padding:13px 15px; margin-bottom:10px;">
        <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:10px; flex-wrap:wrap;">
          <div style="color:#fff; font-size:15px; font-weight:800;">${propEsc(r.agenzia || 'Concorrente')}</div>
          <span style="background:${statoColore[r.statoAnnuncio]||'#3a3f47'}; color:#fff; font-size:10.5px; font-weight:700; padding:2px 9px; border-radius:10px; text-transform:uppercase;">${propEsc(r.statoAnnuncio||'—')}</span>
        </div>
        <div style="color:#c9ced8; font-size:13px; margin-top:6px;">
          <strong style="color:#C6A777; font-size:15px;">${propEsc(r.prezzo || '—')}</strong>
          ${r.mq ? ` &middot; ${r.mq} mq${euroMq(r) ? ' &middot; '+euroMq(r) : ''}` : ''}
          ${r.unita ? ` &middot; ${propEsc(r.unita)}` : ''}${r.piano ? ` &middot; ${propEsc(r.piano)}` : ''}
        </div>
        ${r.titolo ? `<div style="color:#8b98a5; font-size:12px; margin-top:5px;">${propEsc(r.titolo)}</div>` : ''}
        <div style="display:flex; gap:8px; align-items:center; flex-wrap:wrap; margin-top:10px;">
          <span style="background:${sv.colore}; color:${testoStatoSviluppo(sv.nome)}; font-size:10.5px; font-weight:700; padding:2px 9px; border-radius:10px;">${sv.nome}</span>
          ${cons ? `<span style="color:#868b98; font-size:11.5px;"><i class="fa-solid fa-user"></i> ${propEsc(cons.nomeCognome || r.consulente)}</span>` : (r.consulente ? `<span style="color:#868b98; font-size:11.5px;"><i class="fa-solid fa-user"></i> ${propEsc(r.consulente)}</span>` : '')}
          ${r.dataAnnuncio ? `<span style="color:#5f6672; font-size:11px;">annuncio ${propEsc(r.dataAnnuncio)}</span>` : ''}
          ${r.link ? `<a href="${propEsc(r.link)}" target="_blank" rel="noopener" style="margin-left:auto; background:#2a2419; color:#C6A777; border:1px solid #4a3f2a; font-size:11.5px; font-weight:700; padding:5px 11px; border-radius:7px; text-decoration:none;"><i class="fa-solid fa-arrow-up-right-from-square"></i> Apri annuncio</a>` : ''}
        </div>
      </div>`;
    }).join('');
    ov.querySelector('#popup-conc-civico-body').innerHTML = `
      <div style="display:flex; justify-content:space-between; align-items:center; padding:16px 18px; border-bottom:1px solid #2e3238;">
        <div><div style="color:#e08fa0; font-size:12px; text-transform:uppercase; letter-spacing:.5px;"><i class="fa-solid fa-building"></i> Concorrenza collegata</div>
          <div style="color:#fff; font-size:16px; font-weight:800;">${propEsc(v.nome)} <span style="color:#C6A777;">${propEsc(civ.numero)}</span> &middot; ${propEsc(c.comune)}</div></div>
        <button onclick="document.getElementById('popup-conc-civico-overlay').style.display='none'" style="background:#2e3238; border:1px solid #3e4147; color:#e6e9ef; width:34px; height:34px; border-radius:8px; cursor:pointer; font-size:16px;">&times;</button>
      </div>
      <div style="padding:15px 18px;">${cards}</div>`;
    ov.style.display = 'flex';
  }
  window.apriPopupConcorrenzaCivico = apriPopupConcorrenzaCivico;

  /* I quattro stati in ordine di avanzamento, con il punteggio che vale ogni
     lead in quello stato (usato nell'Analisi Consulenti). */
  const STATI_SVILUPPO_CONCORRENZA = [
    { nome: 'Informazione',      colore: '#f0919c', punti: 0 },  // rosso chiaro: solo che e' in vendita, non hai fatto nulla
    { nome: '+ Proprietari',     colore: '#e8c07a', punti: 1 },  // oro chiaro: primo passo, hai i proprietari da visura
    { nome: 'Proprietario 100%', colore: '#c6a777', punti: 2 },  // oro: hai scoperto chi e' il proprietario (citofono collegato)
    { nome: 'Opportunity',       colore: '#0b3b4a', punti: 3 }   // blu agenzia: ci hai parlato, e' un lead da lavorare
  ];
  function puntiStatoSviluppo(nome) {
    const s = STATI_SVILUPPO_CONCORRENZA.find(x => x.nome === nome);
    return s ? s.punti : 0;
  }

  /* Lo stato sviluppo si muove da solo con il censimento del civico:
       niente unita' da visura        -> Informazione   (non hai fatto nulla)
       unita' da visura ma 0 collegate -> + Proprietari  (primo passo, hai i proprietari)
       almeno un citofono collegato    -> Proprietario 100% (sai chi e')
     'Opportunity' resta una scelta manuale che vince su tutto. Un valore
     manuale piu' avanti del calcolo non viene declassato (l'automatismo puo'
     solo far salire, non scendere). */
  const _RANGHI_SVILUPPO = ['Informazione', '+ Proprietari', 'Proprietario 100%'];
  function statoSviluppoDi(r) {
    const salvato = (r && r.statoSviluppo) || '';
    if (salvato === 'Opportunity') return STATI_SVILUPPO_CONCORRENZA.find(s => s.nome === 'Opportunity');
    const d = datiSviluppoDelLead(r);
    const rangoAuto = d.collegati >= 1 ? 2 : (d.unita >= 1 ? 1 : 0);
    const rangoSalvato = _RANGHI_SVILUPPO.indexOf(salvato);   // -1 se vuoto o sconosciuto
    const nome = _RANGHI_SVILUPPO[Math.max(rangoAuto, rangoSalvato)];
    return STATI_SVILUPPO_CONCORRENZA.find(s => s.nome === nome) || STATI_SVILUPPO_CONCORRENZA[0];
  }

  /* Testo scuro sui fondi oro, chiaro sugli altri */
  function testoStatoSviluppo(nome) {
    return (nome === 'Proprietario 100%' || nome === '+ Proprietari') ? '#2b2200' : '#fff';
  }

  function cellaStatoSviluppo(r) {
    const attuale = statoSviluppoDi(r);
    const opzioni = STATI_SVILUPPO_CONCORRENZA.map(s =>
      `<option value="${s.nome}" ${s.nome === attuale.nome ? 'selected' : ''}>${s.nome}</option>`).join('');
    return `<td><select class="select-cella-stradario"
      style="background:${attuale.colore}; color:${testoStatoSviluppo(attuale.nome)}; font-weight:700; border:none;"
      onchange="cambiaStatoSviluppoConcorrenza('${r._id}', this.value, this)">${opzioni}</select></td>`;
  }

  /* Ricoloro subito la cella e poi salvo: senza questo il colore restava quello di partenza
     fino al successivo ridisegno della tabella. */
  async function cambiaStatoSviluppoConcorrenza(id, valore, elemento) {
    const stato = STATI_SVILUPPO_CONCORRENZA.find(s => s.nome === valore) || STATI_SVILUPPO_CONCORRENZA[0];
    if (elemento && elemento.style) {
      elemento.style.background = stato.colore;
      elemento.style.color = testoStatoSviluppo(stato.nome);
    }
    await aggiornaCampoConcorrenza(id, 'statoSviluppo', valore);
  }

  function tipoAnnuncioConcorrenza(r) {
    const marcatore = String((r && r.privato) || '').toUpperCase().replace(/[^A-Z ]/g, ' ');
    const agenzia = String((r && r.agenzia) || '').toUpperCase();
    if (marcatore.indexOf('NO NUMERO') !== -1 || marcatore.indexOf('SENZA NUMERO') !== -1) return 'vdp-no-numero';
    if (marcatore.indexOf('VDP') !== -1 || marcatore.indexOf('PRIVAT') !== -1) return 'vdp';
    if (!marcatore && agenzia.indexOf('PRIVAT') !== -1) return 'vdp';   // annuncio senza marcatore ma intestato a un privato
    return 'agenzia';
  }

  function filtraRegistroConcorrenzaPerVista() {
    const dellaScheda = REGISTRO_CONCORRENZA_CLOUD.filter(r => tipoAnnuncioConcorrenza(r) === TIPO_CONCORRENZA);
    return filtraPerRaggio(dellaScheda);   // se non c'e' un centro impostato, li restituisce tutti
  }

  // Comune selezionato nella classifica agenzie: 'tutti' = complessiva di tutta la zona,
  // altrimenti il ranking di quel solo comune.
  let COMUNE_RANKING_CONCORRENZA = 'tutti';
  let PAGINA_RANKING = 1;
  function cambiaComuneRankingConcorrenza(v) {
    COMUNE_RANKING_CONCORRENZA = v || 'tutti';
    PAGINA_RANKING = 1;
    disegnaClassificaAgenzieConcorrenza();
  }
  window.cambiaComuneRankingConcorrenza = cambiaComuneRankingConcorrenza;
  function vaiPaginaRanking(n) {
    PAGINA_RANKING = Math.max(1, n);
    disegnaClassificaAgenzieConcorrenza();
  }
  window.vaiPaginaRanking = vaiPaginaRanking;
  function controlliPaginazioneRanking(totale, totalePagine, inizio, mostrate) {
    if (totale <= 50) return '';
    const pag = PAGINA_RANKING;
    const btn = (n, testo, attivo, off) =>
      `<button ${off ? 'disabled' : `onclick="vaiPaginaRanking(${n})"`} style="background:${attivo ? '#0086d6' : '#292c33'}; border:1px solid #3e4147; color:${off ? '#4b5563' : '#e6e9ef'}; padding:5px 11px; border-radius:6px; font-size:12.5px; font-weight:${attivo ? '700' : '500'}; cursor:${off ? 'default' : 'pointer'}; min-width:36px;">${testo}</button>`;
    let numeri = '';
    const da = Math.max(1, pag - 2), a = Math.min(totalePagine, pag + 2);
    if (da > 1) { numeri += btn(1, '1', pag === 1, false); if (da > 2) numeri += `<span style="color:#5f6672; padding:0 4px;">…</span>`; }
    for (let n = da; n <= a; n++) numeri += btn(n, String(n), n === pag, false);
    if (a < totalePagine) { if (a < totalePagine - 1) numeri += `<span style="color:#5f6672; padding:0 4px;">…</span>`; numeri += btn(totalePagine, String(totalePagine), pag === totalePagine, false); }
    return `<div style="display:flex; align-items:center; gap:6px; flex-wrap:wrap; margin-top:12px; padding-top:10px; border-top:1px solid #2a2d33;">
        <span style="color:#868b98; font-size:12px; margin-right:8px;">${inizio + 1}–${inizio + mostrate} di <strong style="color:#c9ced8;">${totale}</strong> agenzie</span>
        ${btn(pag - 1, '‹ Prec', false, pag <= 1)} ${numeri} ${btn(pag + 1, 'Succ ›', false, pag >= totalePagine)}
      </div>`;
  }

  function disegnaClassificaAgenzieConcorrenza() {
    const container = document.getElementById("monday-tables-container");

    // Solo gli annunci di agenzia della scheda aperta: i privati non entrano in classifica
    const soloAgenzie = filtraRegistroConcorrenzaPerVista().filter(r => !r.privato);

    // Elenco comuni presenti, per il menu a tendina
    const comuni = [...new Set(soloAgenzie.map(r => (r.comune || '').trim()).filter(Boolean))]
      .sort((a, b) => a.localeCompare(b, 'it'));

    // Se il comune scelto non c'è più (dati cambiati), torno a 'tutti'
    if (COMUNE_RANKING_CONCORRENZA !== 'tutti' && !comuni.some(c => c.toLowerCase() === COMUNE_RANKING_CONCORRENZA.toLowerCase())) {
      COMUNE_RANKING_CONCORRENZA = 'tutti';
    }

    const registro = (COMUNE_RANKING_CONCORRENZA === 'tutti')
      ? soloAgenzie
      : soloAgenzie.filter(r => (r.comune || '').trim().toLowerCase() === COMUNE_RANKING_CONCORRENZA.toLowerCase());

    const conteggi = {}; // nomeAgenzia -> { attivi, venduti, ritirati, totale }
    registro.forEach(r => {
      const nomeAgenzia = (r.agenzia || '').trim() || 'N.D.';
      if (!conteggi[nomeAgenzia]) conteggi[nomeAgenzia] = { attivi: 0, venduti: 0, ritirati: 0, totale: 0 };
      const stato = r.statoAnnuncio || 'Attivo';
      if (stato === 'Venduto') conteggi[nomeAgenzia].venduti++;
      else if (stato === 'Ritirato') conteggi[nomeAgenzia].ritirati++;
      else conteggi[nomeAgenzia].attivi++;
      conteggi[nomeAgenzia].totale++;
    });

    const classifica = Object.entries(conteggi)
      .map(([nomeAgenzia, dati]) => ({ nomeAgenzia, ...dati }))
      .sort((a, b) => b.totale - a.totale);
    // Con centinaia di agenzie la pagina si allunga e si impalla: 50 per pagina, poi pag. 2...
    const MAX_RANKING = 50;
    const totalePagineRk = Math.max(1, Math.ceil(classifica.length / MAX_RANKING));
    if (PAGINA_RANKING > totalePagineRk) PAGINA_RANKING = totalePagineRk;
    if (PAGINA_RANKING < 1) PAGINA_RANKING = 1;
    const inizioRk = (PAGINA_RANKING - 1) * MAX_RANKING;
    const classificaMostrata = classifica.slice(inizioRk, inizioRk + MAX_RANKING);

    const etichettaAmbito = COMUNE_RANKING_CONCORRENZA === 'tutti' ? 'tutta la zona' : COMUNE_RANKING_CONCORRENZA;
    const opzioniComuni = ['tutti', ...comuni].map(c =>
      `<option value="${c}" ${c === COMUNE_RANKING_CONCORRENZA ? 'selected' : ''}>${c === 'tutti' ? 'Tutta la zona (complessiva)' : c}</option>`
    ).join('');

    let html = renderizzaBarraViste('concorrenza', COLONNE_META_CONCORRENZA, COLONNE_RAGGRUPPABILI_CONCORRENZA, REGISTRO_CONCORRENZA_CLOUD) + `
      <div style="display:flex; align-items:center; gap:10px; flex-wrap:wrap; margin-bottom:10px;">
        <label style="color:#c9ced8; font-size:13px; font-weight:600;">Classifica per:</label>
        <select onchange="cambiaComuneRankingConcorrenza(this.value)" style="background:#18191c; border:1px solid #3e4147; color:#0086d6; font-weight:700; border-radius:6px; padding:6px 10px; font-size:13px;">
          ${opzioniComuni}
        </select>
        <span style="color:#868b98; font-size:12px;"><strong style="color:#c9ced8;">${classifica.length}</strong> agenzie${classifica.length > MAX_RANKING ? ` (mostrate le prime ${MAX_RANKING})` : ''} &middot; <strong style="color:#c9ced8;">${registro.length}</strong> annunci in ${etichettaAmbito}</span>
      </div>
      <div style="color:#868b98; font-size:12px; margin-bottom:12px;">Classifica basata sugli annunci di agenzia censiti (esclusi i privati).</div>
      <table class="monday-table-centralino">
      <thead><tr><th>#</th><th>Agenzia</th><th>Incarichi Attivi</th><th>Venduti</th><th>Ritirati</th><th>Totale Censiti</th></tr></thead><tbody>`;

    if (classifica.length === 0) {
      html += `<tr><td colspan="6" style="text-align:center; padding:30px; color:#868b98;">Nessun dato presente${COMUNE_RANKING_CONCORRENZA === 'tutti' ? '' : ' per ' + etichettaAmbito}.</td></tr>`;
    } else {
      classificaMostrata.forEach((riga, indice) => {
        html += `<tr>
          <td style="color:#868b98; font-weight:700;">${inizioRk + indice + 1}</td>
          <td><strong>${riga.nomeAgenzia}</strong></td>
          <td style="color:#00c875; font-weight:700;">${riga.attivi}</td>
          <td style="color:#f43f5e; font-weight:700;">${riga.venduti}</td>
          <td style="color:#868b98; font-weight:700;">${riga.ritirati}</td>
          <td style="font-weight:700;">${riga.totale}</td>
        </tr>`;
      });
    }
    container.innerHTML = html + `</tbody></table>` + controlliPaginazioneRanking(classifica.length, totalePagineRk, inizioRk, classificaMostrata.length);
  }

  const COLONNE_META_CONCORRENZA = [
    { chiave: 'titolo', etichetta: 'Titolo' }, { chiave: 'comune', etichetta: 'Comune' }, { chiave: 'via', etichetta: 'Via' },
    { chiave: 'civico', etichetta: 'Civico' }, { chiave: 'contesto', etichetta: 'Contesto' }, { chiave: 'unita', etichetta: 'Unità' },
    { chiave: 'piano', etichetta: 'Piano' }, { chiave: 'bagni', etichetta: 'Bagni' }, { chiave: 'mq', etichetta: 'Mq' }, { chiave: 'prezzo', etichetta: 'Prezzo' },
    { chiave: 'agenzia', etichetta: 'Agenzia' }, { chiave: 'privato', etichetta: 'Privato' }, { chiave: 'dataAnnuncio', etichetta: 'Data' },
    { chiave: 'statoAnnuncio', etichetta: 'Stato' }, { chiave: 'statoSviluppo', etichetta: 'Stato Sviluppo' },
    { chiave: 'consulente', etichetta: 'Consulente' }
  ];
  const COLONNE_RAGGRUPPABILI_CONCORRENZA = ['comune', 'via', 'contesto', 'unita', 'agenzia', 'privato', 'statoAnnuncio', 'statoSviluppo', 'consulente'];

  // Paginazione della tabella Concorrenza: max 50 righe per pagina, così la scheda regge
  // migliaia di annunci senza impastarsi (il freno era il browser che disegnava tutte le
  // righe in un colpo, non il database).
  let PAGINA_CONCORRENZA = 1;
  const RIGHE_PER_PAGINA_CONCORRENZA = 50;
  function vaiPaginaConcorrenza(n) {
    PAGINA_CONCORRENZA = Math.max(1, n);
    disegnaTabellaConcorrenzaCloud();
    const c = document.getElementById("monday-tables-container");
    if (c && c.scrollIntoView) c.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }
  window.vaiPaginaConcorrenza = vaiPaginaConcorrenza;

  function controlliPaginazioneConcorrenza(totale, totalePagine, inizio, mostrate) {
    if (totale <= RIGHE_PER_PAGINA_CONCORRENZA) {
      return `<div style="color:#868b98; font-size:12px; margin-top:10px;">${totale} annunci.</div>`;
    }
    const pag = PAGINA_CONCORRENZA;
    const btn = (n, testo, attivo, off) =>
      `<button ${off ? 'disabled' : `onclick="vaiPaginaConcorrenza(${n})"`} style="background:${attivo ? '#0086d6' : '#292c33'}; border:1px solid #3e4147; color:${off ? '#4b5563' : '#e6e9ef'}; padding:5px 11px; border-radius:6px; font-size:12.5px; font-weight:${attivo ? '700' : '500'}; cursor:${off ? 'default' : 'pointer'}; min-width:36px;">${testo}</button>`;
    let numeri = '';
    const finestra = 2;
    const da = Math.max(1, pag - finestra), a = Math.min(totalePagine, pag + finestra);
    if (da > 1) { numeri += btn(1, '1', pag === 1, false); if (da > 2) numeri += `<span style="color:#5f6672; padding:0 4px;">…</span>`; }
    for (let n = da; n <= a; n++) numeri += btn(n, String(n), n === pag, false);
    if (a < totalePagine) { if (a < totalePagine - 1) numeri += `<span style="color:#5f6672; padding:0 4px;">…</span>`; numeri += btn(totalePagine, String(totalePagine), pag === totalePagine, false); }
    return `
      <div style="display:flex; align-items:center; gap:6px; flex-wrap:wrap; margin-top:12px; padding-top:10px; border-top:1px solid #2a2d33;">
        <span style="color:#868b98; font-size:12px; margin-right:8px;">${inizio + 1}–${inizio + mostrate} di <strong style="color:#c9ced8;">${totale}</strong></span>
        ${btn(pag - 1, '‹ Prec', false, pag <= 1)}
        ${numeri}
        ${btn(pag + 1, 'Succ ›', false, pag >= totalePagine)}
      </div>`;
  }

  // PONTE Concorrenza -> Censimento: dal civico di un lead apre quel civico nell'Esplora
  // Territorio (creandolo se non è censito), espanso coi pannelli, e ci scrolla sopra.
  async function apriCivicoDaConcorrenza(rigaId) {
    const r = (REGISTRO_CONCORRENZA_CLOUD || []).find(x => x._id === rigaId);
    if (!r) return;
    const comuneNome = (r.comune || '').trim(), viaNome = (r.via || '').trim(), civicoNum = (r.civico || '').trim();
    if (!comuneNome || !viaNome || !civicoNum || civicoNum.toUpperCase() === 'N.D.') {
      alert('Questo lead non ha comune, via e civico completi: non posso aprirlo nel censimento.'); return;
    }
    const norm = (s) => (s||'').normalize('NFKD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
    const keyOrd = (s) => { const stop=new Set(['via','viale','piazza','piazzale','corso','vicolo','largo','strada','san','sant','della','delle','dei','del','di','da','de','la','lo']); return norm(s).split(' ').filter(w=>w.length>1 && !stop.has(w) && !/^\d+$/.test(w)).sort().join(' '); };
    const idxComune = (STRADARIO_LIVE_CLOUD || []).findIndex(c => norm(c.comune) === norm(comuneNome));
    if (idxComune === -1) { alert(`Il comune "${comuneNome}" non è nel Censimento. Aggiungilo prima in Esplora Territorio.`); return; }
    const comuneObj = STRADARIO_LIVE_CLOUD[idxComune];
    if (!Array.isArray(comuneObj.vie)) comuneObj.vie = [];
    let daSalvare = false;
    let idxVia = comuneObj.vie.findIndex(v => keyOrd(v.nome) === keyOrd(viaNome));
    if (idxVia === -1) idxVia = comuneObj.vie.findIndex(v => norm(v.nome) === norm(viaNome));
    if (idxVia === -1) {
      comuneObj.vie.push({ nome: viaNome, zone: (norm(comuneObj.comune)==='legnano' ? 'DA DEFINIRE' : 'CENTRO'), civici: [] });
      idxVia = comuneObj.vie.length - 1; daSalvare = true;
    }
    const viaObj = comuneObj.vie[idxVia];
    if (!Array.isArray(viaObj.civici)) viaObj.civici = [];
    let idxCivico = viaObj.civici.findIndex(cv => norm(cv.numero) === norm(civicoNum));
    if (idxCivico === -1) {
      viaObj.civici.push({ numero: civicoNum, contestoCivico: 'Palazzina', annoCostruzione:'', statoStabile:0, amministratore:'', foglio:'', particella:'', citofoni: [], proprietariNonResidenti: [] });
      idxCivico = viaObj.civici.length - 1; daSalvare = true;
    }
    if (daSalvare) {
      try { await fetch(`${API_STRADARIO}/${comuneObj._id}`, { method:'PUT', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ vie: comuneObj.vie }) }); }
      catch (e) { console.error('Civico non salvato:', e); }
    }
    POPUP_PIANO_FILTRO = '';
    apriPopupCivico(comuneObj._id, idxComune, idxVia, idxCivico);
  }
  window.apriCivicoDaConcorrenza = apriCivicoDaConcorrenza;

  // ===== POPUP CIVICO — lavora sugli STESSI dati del Censimento (a specchio) =====
  let POPUP_CIVICO_CORRENTE = null;
  let POPUP_PIANO_FILTRO = '';
  function apriPopupCivico(comuneId, idxComune, idxVia, idxCivico) {
    POPUP_CIVICO_CORRENTE = { comuneId, idxComune, idxVia, idxCivico };
    let ov = document.getElementById('popup-civico-overlay');
    if (!ov) {
      ov = document.createElement('div');
      ov.id = 'popup-civico-overlay';
      ov.style.cssText = 'position:fixed; inset:0; z-index:9000; background:rgba(0,0,0,.6); display:flex; align-items:flex-start; justify-content:center; padding:32px 16px; overflow:auto;';
      ov.onclick = (e) => { if (e.target === ov) chiudiPopupCivico(); };
      ov.innerHTML = '<div style="background:#141619; border:1px solid #2e3238; border-radius:12px; width:min(1050px,96vw); box-shadow:0 20px 70px rgba(0,0,0,.6);"><div id="popup-civico-body"></div></div>';
      document.body.appendChild(ov);
    }
    /* I popup annidati del censimento (Incolla visure, Collega proprietari,
       Incroci) vivono dentro il contenitore del blocco Squarespace, che ha
       un proprio contesto di impilamento: da li' il loro z-index alto resta
       "intrappolato" sotto a questo overlay (che sta sul body) e si aprivano
       dietro, sembrando non funzionare. Li porto sul body, accanto a questo
       overlay: sono overlay fissi a tutto schermo, spostarli non cambia il
       loro comportamento nel censimento, e ora il loro z-index vince. */
    ['popup-foto-citofoni', 'popup-collega-proprietari-overlay'].forEach(id => {
      const el = document.getElementById(id);
      if (el && el.parentNode !== document.body) document.body.appendChild(el);
    });
    ov.style.display = 'flex';
    ridisegnaPopupCivico();
  }
  function chiudiPopupCivico() {
    POPUP_CIVICO_CORRENTE = null;
    const ov = document.getElementById('popup-civico-overlay');
    if (ov) ov.style.display = 'none';
    /* collegando dei sub nel popup puo' essere cambiato lo stato sviluppo dei
       lead: azzero la cache e ridisegno la Concorrenza se e' la scheda attiva. */
    INDICE_SUB_COLLEGATI = null;
    if (typeof AREA_LAVORO_ATTIVA !== 'undefined'
        && ['info-concorrenza', 'info-vdp', 'info-vdpnonum'].indexOf(AREA_LAVORO_ATTIVA) !== -1
        && typeof ridisegnaVistaConcorrenzaCorrente === 'function') {
      ridisegnaVistaConcorrenzaCorrente();
    }
  }
  function cambiaPianoPopup(v) { POPUP_PIANO_FILTRO = v || ''; ridisegnaPopupCivico(); }
  function ridisegnaPopupCivico() {
    const body = document.getElementById('popup-civico-body');
    if (body && POPUP_CIVICO_CORRENTE) body.innerHTML = htmlPannelliCivicoPopup();
  }
  window.apriPopupCivico = apriPopupCivico;
  window.chiudiPopupCivico = chiudiPopupCivico;
  window.cambiaPianoPopup = cambiaPianoPopup;

  function htmlPannelliCivicoPopup() {
    const p = POPUP_CIVICO_CORRENTE; if (!p) return '';
    const c = (STRADARIO_LIVE_CLOUD||[])[p.idxComune];
    const v = c && c.vie && c.vie[p.idxVia];
    const civ = v && v.civici && v.civici[p.idxCivico];
    if (!c || !v || !civ) return '<div style="padding:26px; color:#868b98;">Civico non più disponibile. <button onclick="chiudiPopupCivico()" style="margin-left:8px;">Chiudi</button></div>';
    const idxComune=p.idxComune, idxVia=p.idxVia, idxCivico=p.idxCivico;
    const propNonRes = civ.proprietariNonResidenti || [];
    const pianoDi = (cit) => { if ((cit.piano||'').trim()) return cit.piano.trim(); const g=(cit.gruppiCollegatiIds||[]).map(String)[0]; const u=g?propNonRes.find(x=>String(x._id)===g):null; return (u&&u.piano||'').trim(); };
    const filtro = (POPUP_PIANO_FILTRO||'').trim();
    const pianiPresenti = [...new Set((civ.citofoni||[]).map(pianoDi).filter(Boolean))].sort();
    const idV=`vie-${idxComune}`, idCiv=`civici-${idxComune}-${idxVia}`, idCit=`citofoni-${idxComune}-${idxVia}-${idxCivico}`;
    let h = `
      <div style="display:flex; justify-content:space-between; align-items:center; padding:16px 20px; border-bottom:1px solid #2e3238; position:sticky; top:0; background:#141619; border-radius:12px 12px 0 0; z-index:2;">
        <div><div style="color:#8fb3c0; font-size:12px; text-transform:uppercase; letter-spacing:.5px;">${c.comune} &middot; dal lead Concorrenza</div>
          <div style="color:#fff; font-size:17px; font-weight:800;">${v.nome} <span style="color:#C6A777;">${civ.numero}</span></div></div>
        <button onclick="chiudiPopupCivico()" style="background:#2e3238; border:1px solid #3e4147; color:#e6e9ef; width:34px; height:34px; border-radius:8px; cursor:pointer; font-size:16px;">&times;</button>
      </div>
      <div style="padding:18px 20px;">`;
    h += datiContestoCivico(c._id, idxComune, idxVia, idxCivico, civ);
    h += `<div style="height:14px;"></div>` + visureCivico(c._id, idxComune, idxVia, idxCivico, civ);
    h += `<div style="margin-top:18px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px;">
        <h5 style="color:#8b98a5; margin:0; font-size:12px; text-transform:uppercase;"><i class="fa-solid fa-list"></i> Citofoni</h5>
        <div style="display:flex; gap:8px; align-items:center;">
          <span style="color:#868b98; font-size:11.5px;">Filtra piano:</span>
          <select onchange="cambiaPianoPopup(this.value)" style="background:#18191c; border:1px solid #3e4147; color:#fff; border-radius:5px; padding:4px 8px; font-size:12px;">
            <option value="">Tutti</option>${pianiPresenti.map(pp=>`<option value="${pp}" ${filtro===pp?'selected':''}>${pp}</option>`).join('')}
          </select>
          <button class="btn-add-inline-layer" style="background:#2a2419; color:#C6A777; border:1px solid #4a3f2a;" onclick="aggiungiCitofonoNuovo('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico}, '${idV}', '${idCiv}', '${idCit}')"><i class="fa-solid fa-plus"></i> Citofono</button>
        </div>
      </div>
      <table class="monday-sub-table" style="margin-top:8px;"><thead><tr><th>Nome</th><th>Stato</th><th>Piano</th><th>Vani</th><th>Sub</th><th>Mq</th><th>Proprietario Collegato</th><th></th></tr></thead><tbody>`;
    const citVis = (civ.citofoni||[]).map((cit,i)=>({cit,i})).filter(o=> !filtro || pianoDi(o.cit)===filtro);
    if (citVis.length) {
      citVis.forEach(o => {
        const cit=o.cit, idxCitofono=o.i;
        const disp = righeProprietariCollegati(cit, propNonRes, `popprop-${idxComune}-${idxVia}-${idxCivico}-${idxCitofono}`);
        h += `<tr>
          <td><input type="text" class="input-cella-stradario" value="${(cit.nome||'').replace(/"/g,'&quot;')}" onchange="aggiornaCellaCloud('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico}, ${idxCitofono}, 'nome', this.value, false)"></td>
          <td><select class="select-cella-stradario" onchange="aggiornaCellaCloud('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico}, ${idxCitofono}, 'statoProprietario', this.value, false)">
            <option value="" ${!cit.statoProprietario?'selected':''}>--</option>
            <option value="Proprietario Residente" ${cit.statoProprietario==='Proprietario Residente'?'selected':''}>Propr. Residente</option>
            <option value="Inquilino" ${cit.statoProprietario==='Inquilino'?'selected':''}>Inquilino</option>
            <option value="Proprietario non Residente" ${cit.statoProprietario==='Proprietario non Residente'?'selected':''}>Propr. non Residente</option>
          </select></td>
          ${cellaSpecchio(cit, propNonRes, 'piano', 45, `aggiornaCellaCloud('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico}, ${idxCitofono}, 'piano', this.value, false)`)}
          ${cellaSpecchio(cit, propNonRes, 'vani', 40, `aggiornaCellaCloud('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico}, ${idxCitofono}, 'vani', this.value, false)`)}
          ${cellaSpecchio(cit, propNonRes, 'sub', 45, `aggiornaCellaCloud('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico}, ${idxCitofono}, 'sub', this.value, false)`)}
          ${cellaSpecchio(cit, propNonRes, 'mq', 45, `aggiornaCellaCloud('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico}, ${idxCitofono}, 'mq', this.value, false)`)}
          <td><div style="display:flex; align-items:flex-start; gap:8px;"><div style="flex:1; min-width:0;">${disp}</div>
            <button onclick="apriPopupCollegaProprietari('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico}, ${idxCitofono})" title="Collega un'unità da visura" style="background:#2a2419; border:1px solid #4a3f2a; color:#C6A777; width:26px; height:26px; border-radius:6px; cursor:pointer; font-size:11px; flex-shrink:0;">&#9998;</button></div></td>
          <td><button class="btn-cestino-riga" onclick="eliminaCitofonoRiga('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico}, ${idxCitofono})"><i class="fa-solid fa-trash-can"></i></button></td>
        </tr>`;
      });
    } else {
      h += `<tr><td colspan="8" style="text-align:center; color:#868b98; padding:14px;">${filtro?'Nessun citofono a questo piano.':'Nessun citofono censito.'}</td></tr>`;
    }
    h += `</tbody></table>`;
    h += `<div style="margin-top:22px; display:flex; justify-content:space-between; align-items:center;">
        <h5 style="color:#C6A777; margin:0; font-size:12px; text-transform:uppercase;"><i class="fa-solid fa-house-user"></i> Unità da visura</h5>
        <div style="display:flex; gap:7px;">
          <button class="btn-add-inline-layer" style="background:#2a2419; color:#C6A777; border:1px solid #4a3f2a;" onclick="apriIncollaVisure('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico})"><i class="fa-solid fa-paste"></i> Incolla visure</button>
          <button class="btn-add-inline-layer" style="background:#2a2419; color:#C6A777; border:1px solid #4a3f2a;" onclick="aggiungiGruppoProprietari('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico})"><i class="fa-solid fa-plus"></i> Nuova Unità</button>
        </div>
      </div>`;
    if (propNonRes.length) {
      propNonRes.forEach((g, idxGruppo) => {
        h += `<div style="background:#1a1d21; border-left:3px solid #C6A777; border-radius:7px; margin-top:12px; padding:12px 14px;">
          <div style="display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-bottom:10px;">
            <span style="background:#2a2419; color:#C6A777; border:1px solid #4a3f2a; font-size:12px; font-weight:800; padding:4px 11px; border-radius:6px;">${g.sub?'SUB '+g.sub:'sub —'}</span>
            <span style="color:#868b98; font-size:11px;">Piano</span><input type="text" class="input-cella-stradario" style="width:46px;" value="${(g.piano||'').replace(/"/g,'&quot;')}" onchange="aggiornaCellaCloud('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico}, ${idxGruppo}, 'piano', this.value, true)">
            <span style="color:#868b98; font-size:11px;">Vani</span><input type="text" class="input-cella-stradario" style="width:46px;" value="${(g.vani||'').replace(/"/g,'&quot;')}" onchange="aggiornaCellaCloud('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico}, ${idxGruppo}, 'vani', this.value, true)">
            <span style="color:#868b98; font-size:11px;">Sub</span><input type="text" class="input-cella-stradario" style="width:46px;" value="${(g.sub||'').replace(/"/g,'&quot;')}" onchange="aggiornaCellaCloud('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico}, ${idxGruppo}, 'sub', this.value, true)">
            <span style="color:#868b98; font-size:11px;">Mq</span><input type="text" class="input-cella-stradario" style="width:46px;" value="${(g.mq||'').replace(/"/g,'&quot;')}" onchange="aggiornaCellaCloud('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico}, ${idxGruppo}, 'mq', this.value, true)">
            <button class="btn-add-inline-layer" style="background:#2a2419; color:#C6A777; border:1px solid #4a3f2a;" onclick="aggiungiProprietarioAlGruppo('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico}, ${idxGruppo})"><i class="fa-solid fa-plus"></i> Proprietario</button>
            <button class="btn-del-inline cestino-civico" onclick="eliminaGruppoProprietari('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico}, ${idxGruppo})"><i class="fa-solid fa-trash-can"></i></button>
          </div>
          <table class="monday-sub-table" style="background:#14161a; margin:0;">${(g.proprietari||[]).length?'<thead><tr><th>Nome e Cognome</th><th>Codice Fiscale</th><th>Data Nascita</th><th>Luogo</th><th></th></tr></thead>':''}<tbody>`;
        (g.proprietari||[]).forEach((pr, idxP) => {
          h += `<tr>
            <td><input type="text" class="input-cella-stradario" value="${(pr.nomeCognome||'').replace(/"/g,'&quot;')}" onchange="aggiornaProprietarioGruppo('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico}, ${idxGruppo}, ${idxP}, 'nomeCognome', this.value)"></td>
            <td><input type="text" class="input-cella-stradario" value="${(pr.cf||'').replace(/"/g,'&quot;')}" onchange="aggiornaProprietarioGruppo('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico}, ${idxGruppo}, ${idxP}, 'cf', this.value)"></td>
            <td><input type="date" class="input-cella-stradario" style="width:135px;" value="${dataPerCalendario(pr.dataNascita||pr.annoNascita)}" onchange="aggiornaProprietarioGruppo('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico}, ${idxGruppo}, ${idxP}, 'dataNascita', dataDaCalendario(this.value))"></td>
            <td><input type="text" class="input-cella-stradario" placeholder="Comune" value="${(pr.luogoNascita||'').replace(/"/g,'&quot;')}" onchange="aggiornaProprietarioGruppo('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico}, ${idxGruppo}, ${idxP}, 'luogoNascita', this.value)"></td>
            <td><button class="btn-cestino-riga" onclick="eliminaProprietarioDalGruppo('${c._id}', ${idxComune}, ${idxVia}, ${idxCivico}, ${idxGruppo}, ${idxP})"><i class="fa-solid fa-trash-can"></i></button></td>
          </tr>`;
        });
        h += `</tbody></table></div>`;
      });
    } else {
      h += `<div style="color:#5f6672; font-size:12px; padding:12px 0;">Nessuna unità da visura. Usa "Incolla visure" o "Nuova Unità".</div>`;
    }
    h += `</div>`;
    return h;
  }

  /* ===== VISTA KANBAN: gli stessi lead della tabella, in colonne per stato
     sviluppo. Rispetta gli stessi filtri (comune, persona, periodo, scheda).
     Trascinando una card la si porta in un altro stato: "Opportunity" resta
     dove la metti; per gli altri tre comanda comunque il numero di sub
     collegati (l'automatismo puo' solo far salire, non scendere). ===== */
  function cardKanbanConcorrenza(r) {
    const nonAttivo = r.statoAnnuncio === 'Ritirato' || r.statoAnnuncio === 'Venduto';
    const indirizzo = [r.via, r.civico].filter(x => x && String(x).toUpperCase() !== 'N.D.').join(' ');
    const cons = (typeof REGISTRO_CONSULENTI !== 'undefined' ? REGISTRO_CONSULENTI : []).find(x => x.utente === r.consulente);
    const nConc = concorrenzaDelCivico(r.comune, r.via, r.civico).length;
    return `<div draggable="true" ondragstart="event.dataTransfer.setData('text/plain','${r._id}'); this.style.opacity='.4';" ondragend="this.style.opacity='';"
        style="background:#1a1d21; border:1px solid #2e3238; border-radius:9px; padding:10px 11px; margin-bottom:9px; cursor:grab; ${nonAttivo ? 'opacity:.6;' : ''}">
      <div style="display:flex; justify-content:space-between; gap:8px; align-items:flex-start;">
        <div style="color:#fff; font-weight:700; font-size:13px; line-height:1.25;">${propEsc(r.agenzia || 'Concorrente')}</div>
        <strong style="color:#C6A777; font-size:13px; white-space:nowrap;">${propEsc(r.prezzo || '')}</strong>
      </div>
      <div style="color:#9aa3af; font-size:11.5px; margin-top:4px;">${propEsc(r.comune || '')}${indirizzo ? ' &middot; ' + propEsc(indirizzo) : ''}</div>
      <div style="color:#7d848f; font-size:11px; margin-top:3px;">${r.mq ? r.mq + ' mq &middot; ' : ''}${propEsc(r.unita || '')}${cons ? ' &middot; ' + propEsc(cons.nomeCognome || r.consulente) : (r.consulente ? ' &middot; ' + propEsc(r.consulente) : '')}</div>
      <div style="display:flex; gap:6px; align-items:center; margin-top:8px;">
        <button onclick="apriCivicoDaConcorrenza('${r._id}')" title="Apri questo civico nel censimento" style="background:#2a2419; border:1px solid #4a3f2a; color:#C6A777; font-size:11px; font-weight:700; padding:4px 9px; border-radius:6px; cursor:pointer;"><i class="fa-solid fa-diagram-project"></i></button>
        ${r.link ? `<a href="${propEsc(normalizzaLink(r.link))}" target="_blank" rel="noopener" title="Apri l'annuncio" style="background:#20242b; border:1px solid #3a3f47; color:#8fb3c0; font-size:11px; padding:4px 9px; border-radius:6px; text-decoration:none;"><i class="fa-solid fa-arrow-up-right-from-square"></i></a>` : ''}
        ${nConc > 1 ? `<span title="${nConc} annunci su questo civico" style="margin-left:auto; background:#2a1a1f; border:1px solid #5a2f3a; color:#e08fa0; font-size:10px; font-weight:700; padding:2px 7px; border-radius:9px;"><i class="fa-solid fa-building"></i> ${nConc}</span>` : ''}
      </div>
    </div>`;
  }

  async function droppaKanbanSviluppo(event, nomeStato) {
    event.preventDefault();
    const col = event.currentTarget; if (col) col.style.background = '#141619';
    const id = event.dataTransfer.getData('text/plain');
    if (!id) return;
    await aggiornaCampoConcorrenza(id, 'statoSviluppo', nomeStato);
    disegnaKanbanConcorrenza();
  }

  function disegnaKanbanConcorrenza() {
    const container = document.getElementById("monday-tables-container");
    const configConcorrenza = ottieniConfigVista('concorrenza');
    let registroFiltrato = filtraRegistroConcorrenzaPerVista();
    registroFiltrato = applicaFiltriAvanzati(registroFiltrato, configConcorrenza.filtriAvanzati);
    registroFiltrato = filtraScheda('concorrenza', registroFiltrato);
    if (configConcorrenza.filtroPersona) registroFiltrato = registroFiltrato.filter(r => (r.consulente || '') === configConcorrenza.filtroPersona);

    let html = renderizzaFiltriPeriodo('concorrenza', registroFiltrato.length, REGISTRO_CONCORRENZA_CLOUD.length, REGISTRO_CONCORRENZA_CLOUD);
    html += renderizzaBarraViste('concorrenza', COLONNE_META_CONCORRENZA, COLONNE_RAGGRUPPABILI_CONCORRENZA, registroFiltrato);
    html += barraRaggioConcorrenza();

    const gruppi = {};
    STATI_SVILUPPO_CONCORRENZA.forEach(s => gruppi[s.nome] = []);
    registroFiltrato.forEach(r => { const nome = statoSviluppoDi(r).nome; (gruppi[nome] = gruppi[nome] || []).push(r); });

    html += `<div style="display:flex; gap:14px; overflow-x:auto; padding:10px 4px 24px; align-items:flex-start;">`;
    STATI_SVILUPPO_CONCORRENZA.forEach(s => {
      const cards = gruppi[s.nome] || [];
      html += `<div ondragover="event.preventDefault(); this.style.background='#1c2026';" ondragleave="this.style.background='#141619';" ondrop="droppaKanbanSviluppo(event, '${s.nome.replace(/'/g, "\\'")}')"
          style="flex:0 0 300px; background:#141619; border:1px solid #2e3238; border-radius:12px; padding:10px; min-height:140px; transition:background .15s;">
        <div style="display:flex; align-items:center; gap:8px; padding:6px 6px 12px; border-bottom:1px solid #23272e; margin-bottom:10px;">
          <span style="width:11px; height:11px; border-radius:50%; background:${s.colore}; display:inline-block; flex-shrink:0;"></span>
          <span style="color:#fff; font-weight:800; font-size:12.5px;">${s.nome}</span>
          <span style="margin-left:auto; background:#2a2d33; color:#9aa3af; font-size:11px; font-weight:700; padding:2px 8px; border-radius:9px;">${cards.length}</span>
        </div>`;
      if (!cards.length) html += `<div style="color:#5f6672; font-size:12px; text-align:center; padding:14px 6px;">— trascina qui —</div>`;
      cards.forEach(r => { html += cardKanbanConcorrenza(r); });
      html += `</div>`;
    });
    html += `</div>`;
    container.innerHTML = html;
  }

  /* ===== VISTA ANALISI CONSULENTI: per ogni consulente quanti lead ha e a che
     punto sono (per stato sviluppo). Serve a tenerli monitorati. Rispetta gli
     stessi filtri (comune, periodo, scheda) ma NON il filtro persona, perche'
     qui la scomposizione e' proprio per persona. Cliccando una riga si apre la
     tabella filtrata su quel consulente. ===== */
  function _coloreStatoVisibile(colore) {
    return colore === '#0b3b4a' ? '#4a90b8' : colore;   // il blu scuro non si legge sui fondi scuri
  }
  function avatarConsulenteMini(cons, nomeFallback) {
    const nome = (cons && cons.nomeCognome) || nomeFallback || '—';
    if (cons && cons.fotoProfilo) return `<img src="${propEsc(cons.fotoProfilo)}" alt="" referrerpolicy="no-referrer" style="width:26px; height:26px; border-radius:50%; object-fit:cover; flex-shrink:0;">`;
    const ini = nome.split(' ').filter(Boolean).slice(0, 2).map(p => p[0]).join('').toUpperCase() || '?';
    return `<span style="width:26px; height:26px; border-radius:50%; background:#0B3B4A; color:#fff; display:inline-flex; align-items:center; justify-content:center; font-size:10.5px; font-weight:800; flex-shrink:0;">${ini}</span>`;
  }
  function apriLeadConsulente(utente) {
    const config = ottieniConfigVista('concorrenza');
    config.filtroPersona = utente || '';
    PAGINA_CONCORRENZA = 1;
    MODO_CONCORRENZA = 'tabella';
    ridisegnaVistaConcorrenzaCorrente();
  }

  function disegnaAnalisiConsulentiConcorrenza() {
    const container = document.getElementById("monday-tables-container");
    const config = ottieniConfigVista('concorrenza');
    let reg = filtraRegistroConcorrenzaPerVista();
    reg = applicaFiltriAvanzati(reg, config.filtriAvanzati);
    reg = filtraScheda('concorrenza', reg);

    let html = renderizzaFiltriPeriodo('concorrenza', reg.length, REGISTRO_CONCORRENZA_CLOUD.length, REGISTRO_CONCORRENZA_CLOUD);
    html += renderizzaBarraViste('concorrenza', COLONNE_META_CONCORRENZA, COLONNE_RAGGRUPPABILI_CONCORRENZA, reg);
    html += barraRaggioConcorrenza();

    const nomiStati = STATI_SVILUPPO_CONCORRENZA.map(s => s.nome);
    const perCons = {};
    reg.forEach(r => {
      const k = r.consulente || '';
      if (!perCons[k]) { perCons[k] = { totale: 0, stati: {}, attivi: 0, punteggio: 0 }; nomiStati.forEach(n => perCons[k].stati[n] = 0); }
      const g = perCons[k];
      g.totale++;
      const nomeStato = statoSviluppoDi(r).nome;
      g.stati[nomeStato] = (g.stati[nomeStato] || 0) + 1;
      g.punteggio += puntiStatoSviluppo(nomeStato);
      if (r.statoAnnuncio !== 'Venduto' && r.statoAnnuncio !== 'Ritirato') g.attivi++;
    });

    let righe = Object.keys(perCons).map(k => {
      const cons = REGISTRO_CONSULENTI.find(c => c.utente === k);
      const g = perCons[k];
      return { k, cons, nome: cons ? cons.nomeCognome : (k || 'Non assegnato'), g, lavorati: g.totale - (g.stati['Informazione'] || 0) };
    });
    /* Ranking per PUNTEGGIO (a parita', chi ha piu' lead): premia chi ha
       sviluppato di piu', non solo chi ne ha tanti fermi a "Informazione". */
    righe.sort((a, b) => (b.g.punteggio - a.g.punteggio) || (b.g.totale - a.g.totale));

    const totStati = {}; nomiStati.forEach(n => totStati[n] = righe.reduce((s, r) => s + r.g.stati[n], 0));
    const totLavorati = reg.length - (totStati['Informazione'] || 0);
    const totPunteggio = righe.reduce((s, r) => s + r.g.punteggio, 0);

    const badge = (n, colore) => `<span style="display:inline-block; min-width:28px; text-align:center; background:${colore}22; color:${colore}; border:1px solid ${colore}55; font-weight:800; font-size:12px; padding:2px 7px; border-radius:7px;">${n}</span>`;
    const nCol = 5 + STATI_SVILUPPO_CONCORRENZA.length;

    html += `<div style="overflow-x:auto; padding:6px 2px 24px;"><table class="monday-table-centralino" style="min-width:940px;">
      <thead><tr>
        <th style="width:40px;">#</th><th>Consulente</th><th style="width:110px;">Punteggio</th><th style="width:90px;">Lead</th>
        ${STATI_SVILUPPO_CONCORRENZA.map(s => `<th style="text-align:center;"><span style="color:${_coloreStatoVisibile(s.colore)};">&#9679;</span> ${s.nome}</th>`).join('')}
        <th style="width:150px;">Lavorati</th>
      </tr></thead><tbody>`;
    if (!righe.length) {
      html += `<tr><td colspan="${nCol}" style="text-align:center; padding:30px; color:#868b98;">Nessun dato in questa vista.</td></tr>`;
    } else {
      righe.forEach((row, i) => {
        const perc = row.g.totale ? Math.round(row.lavorati / row.g.totale * 100) : 0;
        const cliccabile = row.k ? `onclick="apriLeadConsulente('${row.k}')" style="cursor:pointer;" title="Vedi i lead di ${propEsc(row.nome)}"` : '';
        const media = row.g.totale ? (row.g.punteggio / row.g.totale).toFixed(1) : '0';
        html += `<tr ${cliccabile}>
          <td style="color:#C6A777; font-weight:800; font-size:14px;">${i + 1}</td>
          <td><div style="display:flex; align-items:center; gap:9px;">${avatarConsulenteMini(row.cons, row.nome)}<span style="font-weight:700; color:#fff;">${propEsc(row.nome)}</span></div></td>
          <td><strong style="font-size:18px; color:#C6A777;">${row.g.punteggio}</strong> <span style="color:#5f6672; font-size:11px;">(${media}/lead)</span></td>
          <td><strong style="font-size:16px; color:#fff;">${row.g.totale}</strong> <span style="color:#5f6672; font-size:11px;">(${row.g.attivi} attivi)</span></td>
          ${STATI_SVILUPPO_CONCORRENZA.map(s => `<td style="text-align:center;">${badge(row.g.stati[s.nome] || 0, _coloreStatoVisibile(s.colore))}</td>`).join('')}
          <td><div style="display:flex; align-items:center; gap:7px;"><div style="flex:1; height:7px; background:#23272e; border-radius:4px; overflow:hidden;"><div style="width:${perc}%; height:100%; background:#00c875;"></div></div><span style="color:#9aa3af; font-size:11.5px; white-space:nowrap;">${row.lavorati} &middot; ${perc}%</span></div></td>
        </tr>`;
      });
      html += `<tr style="border-top:2px solid #3e4147; background:#16181c;">
        <td></td><td style="font-weight:800; color:#9aa3af;">TOTALE</td>
        <td><strong style="color:#C6A777;">${totPunteggio}</strong></td>
        <td><strong style="color:#fff;">${reg.length}</strong></td>
        ${STATI_SVILUPPO_CONCORRENZA.map(s => `<td style="text-align:center; color:#9aa3af; font-weight:700;">${totStati[s.nome] || 0}</td>`).join('')}
        <td style="color:#9aa3af; font-weight:700;">${totLavorati}</td>
      </tr>`;
    }
    html += `</tbody></table></div>`;
    container.innerHTML = html;
  }

  function disegnaTabellaConcorrenzaCloud() {
    const container = document.getElementById("monday-tables-container");
    const configConcorrenza = ottieniConfigVista('concorrenza');
    let registroFiltrato = filtraRegistroConcorrenzaPerVista();
    registroFiltrato = applicaFiltriAvanzati(registroFiltrato, configConcorrenza.filtriAvanzati);
    registroFiltrato = filtraScheda('concorrenza', registroFiltrato);
    if (configConcorrenza.filtroPersona) registroFiltrato = registroFiltrato.filter(r => (r.consulente || '') === configConcorrenza.filtroPersona);

    // Paginazione: mostro solo 50 righe per pagina, clampando la pagina corrente al valido
    const totaleConc = registroFiltrato.length;
    const totalePagineConc = Math.max(1, Math.ceil(totaleConc / RIGHE_PER_PAGINA_CONCORRENZA));
    if (PAGINA_CONCORRENZA > totalePagineConc) PAGINA_CONCORRENZA = totalePagineConc;
    if (PAGINA_CONCORRENZA < 1) PAGINA_CONCORRENZA = 1;
    const inizioConc = (PAGINA_CONCORRENZA - 1) * RIGHE_PER_PAGINA_CONCORRENZA;
    const righeDaMostrare = registroFiltrato.slice(inizioConc, inizioConc + RIGHE_PER_PAGINA_CONCORRENZA);

    let html = renderizzaFiltriPeriodo('concorrenza', registroFiltrato.length, REGISTRO_CONCORRENZA_CLOUD.length, REGISTRO_CONCORRENZA_CLOUD);
    html += renderizzaBarraViste('concorrenza', COLONNE_META_CONCORRENZA, COLONNE_RAGGRUPPABILI_CONCORRENZA, registroFiltrato);
    html += `<datalist id="lista-comuni-concorrenza">` + STRADARIO_LIVE_CLOUD.map(c => `<option value="${c.comune}">`).join('') + `</datalist>`;
    html += barraRaggioConcorrenza();
    html += `<table class="monday-table-centralino">
      <thead><tr><th>Titolo</th><th style="width:190px;">Stato Sviluppo</th>${INTESTAZIONE_CONSULENTE}<th>Comune</th><th>Via</th><th>Civico</th><th style="width:70px;">Mappa</th><th>Contesto</th><th>Unità</th><th>Piano</th><th>Bagni</th><th>Mq</th><th>Prezzo</th><th>Agenzia</th><th>Privato</th><th>Data</th><th style="width:90px;">Ultimo monit.</th><th style="width:80px;">ID</th><th>Link</th><th>Stato</th><th></th></tr></thead><tbody>`;
    if(registroFiltrato.length === 0) {
      html += `<tr><td colspan="21" style="text-align:center; padding:30px; color:#868b98;">Nessun dato presente in questa vista.</td></tr>`;
    } else {
      righeDaMostrare.forEach(r => {
        const nonAttivo = r.statoAnnuncio === 'Ritirato' || r.statoAnnuncio === 'Venduto';
        const stileRiga = nonAttivo ? ' style="background:rgba(244,63,94,0.15);"' : '';
        const linkSicuro = normalizzaLink(r.link).replace(/'/g, "\\'");
        const camposEditabile = (campo, valore, stile) => `<span contenteditable="true" spellcheck="false" style="outline:none; display:inline-block; min-width:20px; ${stile||''}" onblur="aggiornaCampoConcorrenza('${r._id}','${campo}', this.innerText)" onkeydown="if(event.key==='Enter'){event.preventDefault(); this.blur();}">${valore}</span>`;
        const coloreStato = r.statoAnnuncio === 'Venduto' ? '#f43f5e' : (r.statoAnnuncio === 'Ritirato' ? '#868b98' : '#00c875');
        const cSel = STRADARIO_LIVE_CLOUD.find(c => (c.comune||'').trim().toLowerCase() === (r.comune||'').trim().toLowerCase());
        const vieDelComune = (cSel && cSel.vie) || [];
        const viaSel = vieDelComune.find(v => (v.nome||'').trim().toLowerCase() === (r.via||'').trim().toLowerCase());
        const civiciDellaVia = (viaSel && viaSel.civici) || [];
        html += `<tr${stileRiga}>
          <td><strong>${camposEditabile('titolo', r.titolo)}</strong>
            ${(() => { const d = distanzaDalCentro(r); return d === null ? '' :
               `<div style="color:#00c875; font-size:11px; margin-top:2px;"><i class="fa-solid fa-location-dot"></i> ${d >= 1000 ? (d/1000).toFixed(1) + ' km' : d + ' m'}</div>`; })()}
            ${CENTRO_RAGGIO.lat ? '' : `<button onclick="centraRaggioSuAnnuncio('${r._id}')" title="Cerca gli annunci vicini a questo"
               style="background:none; border:none; color:#5f6672; cursor:pointer; font-size:11px; padding:2px 0;"><i class="fa-solid fa-bullseye"></i> vicini</button>`}
          </td>
          ${cellaStatoSviluppo(r)}
          ${cellaConsulente('concorrenza', r)}
          <td>
            <select onchange="cambiaComuneConcorrenza('${r._id}', this.value)" style="background:#18191c; border:1px solid #3e4147; color:#0086d6; font-size:12.5px; font-weight:600; border-radius:4px; padding:4px; width:100%;">
              <option value="">-- Comune --</option>
              ${STRADARIO_LIVE_CLOUD.map(c => `<option value="${c.comune}" ${(r.comune||'').trim().toLowerCase() === (c.comune||'').trim().toLowerCase() ? 'selected' : ''}>${c.comune}</option>`).join('')}
              ${r.comune && !STRADARIO_LIVE_CLOUD.some(c => (c.comune||'').trim().toLowerCase() === (r.comune||'').trim().toLowerCase())
                ? `<option value="${r.comune}" selected>${r.comune} (fuori censimento)</option>` : ''}
            </select>
          </td>
          <td>
            <input type="text" id="input-via-concorrenza-${r._id}" list="lista-vie-concorrenza-${r._id}" value="${(r.via||'').replace(/"/g,'&quot;')}" onblur="aggiornaCampoConcorrenza('${r._id}','via', this.value)" oninput="aggiornaListaCiviciRigaConcorrenza('${r._id}', '${r.comune||''}', this.value)" onkeydown="if(event.key==='Enter'){event.preventDefault(); this.blur();}" style="background:transparent; border:none; color:white; font-size:13px; width:120px; outline:none;">
            <datalist id="lista-vie-concorrenza-${r._id}">${vieDelComune.map(v => `<option value="${v.nome}">`).join('')}</datalist>
          </td>
          <td>
            <input type="text" id="input-civico-concorrenza-${r._id}" list="lista-civici-concorrenza-${r._id}" value="${(r.civico||'').replace(/"/g,'&quot;')}" onblur="aggiornaCampoConcorrenza('${r._id}','civico', this.value)" onkeydown="if(event.key==='Enter'){event.preventDefault(); this.blur();}" style="background:transparent; border:none; color:white; font-size:13px; width:52px; outline:none;">
            <button onclick="apriCivicoDaConcorrenza('${r._id}')" title="Apri questo civico nel Censimento (citofoni e visure)" style="background:#062733; border:1px solid #0B3B4A; color:#8fb3c0; width:24px; height:24px; border-radius:5px; cursor:pointer; font-size:11px; vertical-align:middle;"><i class="fa-solid fa-diagram-project"></i></button>
            <datalist id="lista-civici-concorrenza-${r._id}">${civiciDellaVia.map(c => `<option value="${c.numero}">`).join('')}</datalist>
          </td>
          ${cellaMappaConcorrenza(r)}
          <td>${camposEditabile('contesto', r.contesto)}</td>
          <td><span class="tag-ruolo-azzurro">${camposEditabile('unita', r.unita)}</span></td>
          <td>${camposEditabile('piano', r.piano)}</td>
          <td>${camposEditabile('bagni', r.bagni)}</td>
          <td>${camposEditabile('mq', (r.mq !== null && r.mq !== undefined) ? r.mq : '')}</td>
          <td>${camposEditabile('prezzo', r.prezzo, 'color:#00c875; font-weight:700;')}</td>
          <td>
            <select onchange="aggiornaAgenziaConcorrenza('${r._id}', this.value)" style="background:#18191c; border:1px solid #3e4147; color:#e2b13c; font-weight:700; border-radius:4px; padding:4px 6px; max-width:140px;">
              <option value="">-- Nessuna agenzia --</option>
              ${REGISTRO_AGENZIE_CLOUD.map(a => {
                const selezionata = r.agenziaId ? (r.agenziaId === a._id) : ((r.agenzia||'').trim().toLowerCase() === a.nomeAgenzia.trim().toLowerCase());
                return `<option value="${a._id}" ${selezionata ? 'selected':''}>${a.nomeAgenzia}</option>`;
              }).join('')}
            </select>
          </td>
          <td>
            <select onchange="aggiornaCampoConcorrenza('${r._id}','privato', this.value)" style="background:#18191c; border:1px solid #3e4147; color:white; border-radius:4px; padding:4px 6px;">
              <option value="" ${!r.privato ? 'selected':''}>No (è agenzia)</option>
              <option value="VDP" ${r.privato === 'VDP' ? 'selected':''}>VDP</option>
              <option value="VDP NO NUMERO" ${r.privato === 'VDP NO NUMERO' ? 'selected':''}>VDP NO NUMERO</option>
            </select>
          </td>
          <td><input type="date" value="${convertiDataInputHtml(r.dataAnnuncio)}" onchange="aggiornaCampoConcorrenza('${r._id}','dataAnnuncio', convertiDataItaliana(this.value))" style="background:#18191c; border:1px solid #3e4147; color:white; border-radius:4px; padding:4px 6px; font-size:12px;"></td>
          <td style="color:#868b98; font-size:12px; white-space:nowrap;">${r.dataUltimoMonitoraggio || '—'}</td>
          <td style="color:#5f6672; font-size:11px;">${r.idImmobiliare ? `<a href="https://www.immobiliare.it/annunci/${r.idImmobiliare}/" target="_blank" rel="noopener noreferrer" style="color:#5f6672; text-decoration:none;" title="Apri su immobiliare">${r.idImmobiliare}</a>` : ''}</td>
          <td style="max-width:160px;">
            <div id="vista-link-${r._id}">
              <a href="${linkSicuro}" target="_blank" rel="noopener noreferrer" onclick="return apriLinkAnnuncioForzato(event, '${linkSicuro}')" style="color:#0086d6; text-decoration:underline; cursor:pointer; display:block; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:130px; font-size:12px;" title="${linkSicuro}">${linkSicuro}</a>
              <span onclick="attivaModificaLinkConcorrenza('${r._id}')" style="color:#868b98; cursor:pointer; font-size:11px;"><i class="fa-solid fa-pen"></i> modifica</span>
            </div>
            <div id="modifica-link-${r._id}" style="display:none;">
              <input type="text" id="input-link-${r._id}" value="${linkSicuro}" style="width:120px; background:#18191c; border:1px solid #3e4147; color:white; border-radius:4px; padding:4px 6px; font-size:11px;">
              <button onclick="salvaModificaLinkConcorrenza('${r._id}')" style="background:#00c875; border:none; color:#18191c; padding:3px 6px; border-radius:4px; cursor:pointer; font-size:11px; margin-top:3px;">Salva</button>
            </div>
          </td>
          <td>
            <select onchange="aggiornaCampoConcorrenza('${r._id}','statoAnnuncio', this.value)" style="background:${coloreStato}; color:white; font-weight:700; border:none; border-radius:4px; padding:4px 6px;">
              <option value="Attivo" ${r.statoAnnuncio === 'Attivo' || !r.statoAnnuncio ? 'selected':''}>Attivo</option>
              <option value="Ritirato" ${r.statoAnnuncio === 'Ritirato' ? 'selected':''}>Ritirato</option>
              <option value="Venduto" ${r.statoAnnuncio === 'Venduto' ? 'selected':''}>Venduto</option>
            </select>
          </td>
          <td><button class="btn-cestino-riga" onclick="eliminaAnnuncioConcorrenza('${r._id}', '')"><i class="fa-solid fa-trash-can"></i></button></td>
        </tr>`;
      });
    }
    container.innerHTML = html + `</tbody></table>` + controlliPaginazioneConcorrenza(totaleConc, totalePagineConc, inizioConc, righeDaMostrare.length);
    applicaColonneNascoste('concorrenza');
  }

  // Blocca la propagazione del click: Squarespace ha un suo script globale che intercetta i click sui
  // link per gestire le transizioni fluide tra pagine, e probabilmente "ruba" il click prima che arrivi
  // qui sotto. Fermandolo qui (stopPropagation + stopImmediatePropagation), lo script di Squarespace non
  // lo vede nemmeno, e il link si apre in una scheda vera e propria.
  // Converte una data italiana "GG/MM/AAAA" nel formato che vuole l'input calendario HTML "AAAA-MM-GG"
  // Se il link non ha "http://" o "https://" davanti, il browser lo interpreta come un indirizzo
  // DENTRO il proprio sito (es. immobiliareforte.com/www.google.it) invece che un sito esterno.
  // Questa funzione lo completa sempre nel modo giusto prima di usarlo in un link cliccabile.
  function normalizzaLink(url) {
    url = (url || '').trim();
    if (!url) return '';
    if (!/^https?:\/\//i.test(url)) url = 'https://' + url;
    return url;
  }

  // Converte un numero seriale Excel (es. 46174, rimasto da un vecchio import non convertito)
  // nel formato AAAA-MM-GG richiesto dai campi calendario. Restituisce '' se non sembra un seriale valido.
  function serialeExcelInDataIso(seriale) {
    const numero = parseFloat(seriale);
    if (isNaN(numero) || numero < 20000 || numero > 60000) return ''; // fuori dal range plausibile (~1954-2064)
    const dataBase = Date.UTC(1899, 11, 30); // epoca Excel, con la correzione del bug dell'anno bisestile 1900
    const dataReale = new Date(dataBase + numero * 86400000);
    const aaaa = dataReale.getUTCFullYear();
    const mm = String(dataReale.getUTCMonth() + 1).padStart(2, '0');
    const gg = String(dataReale.getUTCDate()).padStart(2, '0');
    return `${aaaa}-${mm}-${gg}`;
  }

  // Prende un valore data grezzo (già AAAA-MM-GG, oppure GG/MM/AAAA, oppure un numero seriale Excel
  // rimasto da un vecchio import) e lo riporta sempre al formato AAAA-MM-GG richiesto dai campi calendario.
  function normalizzaValoreDataInput(valoreGrezzo) {
    if (!valoreGrezzo) return '';
    const valore = String(valoreGrezzo).trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(valore)) return valore; // già nel formato giusto
    if (/^\d+(\.\d+)?$/.test(valore)) return serialeExcelInDataIso(valore); // numero seriale Excel
    if (valore.includes('/')) return convertiDataInputHtml(valore); // formato italiano GG/MM/AAAA
    return '';
  }

  function convertiDataInputHtml(dataItaliana) {
    if (!dataItaliana || !dataItaliana.includes('/')) return '';
    const parti = dataItaliana.split('/');
    if (parti.length !== 3) return '';
    return `${parti[2]}-${parti[1].padStart(2,'0')}-${parti[0].padStart(2,'0')}`;
  }

  // Converte il valore dell'input calendario HTML "AAAA-MM-GG" nel formato italiano "GG/MM/AAAA"
  function convertiDataItaliana(dataInputHtml) {
    if (!dataInputHtml || !dataInputHtml.includes('-')) return '';
    const parti = dataInputHtml.split('-');
    if (parti.length !== 3) return '';
    return `${parti[2]}/${parti[1]}/${parti[0]}`;
  }

  function attivaModificaLinkConcorrenza(id) {
    document.getElementById(`vista-link-${id}`).style.display = 'none';
    document.getElementById(`modifica-link-${id}`).style.display = 'block';
    document.getElementById(`input-link-${id}`).focus();
  }

  async function salvaModificaLinkConcorrenza(id) {
    const nuovoLink = normalizzaLink(document.getElementById(`input-link-${id}`).value);
    await aggiornaCampoConcorrenza(id, 'link', nuovoLink);
    disegnaTabellaConcorrenzaCloud();
  }

  function apriLinkAnnuncioForzato(event, url) {
    if (event) {
      event.preventDefault();
      event.stopPropagation();
      if (event.stopImmediatePropagation) event.stopImmediatePropagation();
    }
    try {
      const link = document.createElement('a');
      link.href = url;
      link.target = '_blank';
      link.rel = 'noopener noreferrer';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch (e) {
      console.error('Errore apertura link annuncio:', e);
      window.open(url, '_blank', 'noopener,noreferrer');
    }
    return false;
  }

  async function aggiornaCampoConcorrenza(id, campo, valore) {
    try {
      await fetch(`${API_CONCORRENZA}/${id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ [campo]: valore }) });
      const record = REGISTRO_CONCORRENZA_CLOUD.find(r => r._id === id);
      if (record) record[campo] = valore;

      // toccando via o civico l'immobile e' un altro punto sulla mappa:
      // ricompongo l'indirizzo e butto via le coordinate, cosi' verranno ricalcolate
      if (record && (campo === 'via' || campo === 'civico')) {
        record.paeseVia = componiIndirizzoConcorrenza(record);
        record.lat = null; record.lng = null;
        fetch(`${API_CONCORRENZA}/${id}`, {
          method: 'PUT', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ paeseVia: record.paeseVia, lat: null, lng: null })
        }).catch(e => console.error('Indirizzo non aggiornato:', e));
      }

      // cambiando lo stato, o spostando la riga fra agenzia e privato, la vista va ridisegnata:
      // con il nuovo valore la riga appartiene a un'altra scheda
      if (campo === 'statoAnnuncio' || campo === 'privato' || campo === 'via' || campo === 'civico') ridisegnaVistaConcorrenzaCorrente();
    } catch (e) {
      console.error('Errore aggiornamento campo concorrenza:', e);
    }
  }

  /* Cambiando comune: aggiorno l'indirizzo completo, azzero le coordinate
     (l'immobile e' altrove) e ricarico l'elenco delle vie di quel comune. */
  async function cambiaComuneConcorrenza(id, comune) {
    const record = REGISTRO_CONCORRENZA_CLOUD.find(r => r._id === id);
    if (record) { record.comune = comune; record.lat = null; record.lng = null; record.paeseVia = componiIndirizzoConcorrenza(record); }
    try {
      await fetch(`${API_CONCORRENZA}/${id}`, {
        method: 'PUT', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ comune: comune, lat: null, lng: null, paeseVia: record ? record.paeseVia : '' })
      });
    } catch (e) { console.error('Comune non salvato:', e); }
    ridisegnaVistaConcorrenzaCorrente();
  }

  function aggiornaListaVieRigaConcorrenza(rowId, nuovoComune) {
    const cSel = STRADARIO_LIVE_CLOUD.find(c => (c.comune||'').trim().toLowerCase() === (nuovoComune||'').trim().toLowerCase());
    const vie = (cSel && cSel.vie) || [];
    const datalist = document.getElementById(`lista-vie-concorrenza-${rowId}`);
    if (datalist) datalist.innerHTML = vie.map(v => `<option value="${v.nome}">`).join('');
    // Cambiando comune, la vecchia lista civici non è più valida finché non si sceglie una via nuova
    const inputVia = document.getElementById(`input-via-concorrenza-${rowId}`);
    aggiornaListaCiviciRigaConcorrenza(rowId, nuovoComune, inputVia ? inputVia.value : '');
  }

  function aggiornaListaCiviciRigaConcorrenza(rowId, comune, nuovaVia) {
    const cSel = STRADARIO_LIVE_CLOUD.find(c => (c.comune||'').trim().toLowerCase() === (comune||'').trim().toLowerCase());
    const vieDelComune = (cSel && cSel.vie) || [];
    const viaSel = vieDelComune.find(v => (v.nome||'').trim().toLowerCase() === (nuovaVia||'').trim().toLowerCase());
    const civici = (viaSel && viaSel.civici) || [];
    const datalist = document.getElementById(`lista-civici-concorrenza-${rowId}`);
    if (datalist) datalist.innerHTML = civici.map(c => `<option value="${c.numero}">`).join('');
  }

  async function aggiornaAgenziaConcorrenza(id, agenziaId) {
    const agenziaSelezionata = REGISTRO_AGENZIE_CLOUD.find(a => a._id === agenziaId);
    const nomeAgenzia = agenziaSelezionata ? agenziaSelezionata.nomeAgenzia : '';
    try {
      await fetch(`${API_CONCORRENZA}/${id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ agenziaId, agenzia: nomeAgenzia }) });
      const record = REGISTRO_CONCORRENZA_CLOUD.find(r => r._id === id);
      if (record) { record.agenziaId = agenziaId; record.agenzia = nomeAgenzia; }
    } catch (e) {
      console.error('Errore aggiornamento agenzia concorrenza:', e);
    }
  }

  // Import Excel Centralino: legge un export tipo Monday "CONTATTI CENTRALINO" (intestazioni sulla 3ª riga
  // del foglio: Nome, Smistato Completo, MAIL/CALL, Whats CL Inviato, Telefono cliente X, EMAIL, Note Varie,
  // Riferimento IMMOBILE, Incarichi[Ufficio], Immobile per cui..., Consulente Rif, Cell Consulente, Link
  // Calendar/Imm/Whatsapp, PORTALE, Registro di creazione, Dup. of Cons) e la mappa sul nostro Registro Chiamate.
  function importaFileExcelCentralino(input) {
    const file = input.files[0]; if (!file) return;
    const reader = new FileReader();
    reader.onload = async function(e) {
      const data = new Uint8Array(e.target.result);
      const workbook = XLSX.read(data, { type: 'array' });
      const sheetName = workbook.SheetNames[0];
      // L'export Monday ha una riga di titolo e una vuota prima delle vere intestazioni: proviamo range diversi
      let rows = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName], { range: 2, defval: '' });
      if (rows.length === 0 || !('Nome' in rows[0])) {
        rows = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName], { defval: '' });
      }
      const mapped = rows.filter(r => (r["Nome"] || r["nome"] || '').toString().trim() !== '').map(r => ({
        nome: r["Nome"] || r["nome"] || "N.D.",
        tipoRichiesta: r["MAIL / CALL"] || r["tipoRichiesta"] || '',
        stato: r["Smistato Completo"] || r["stato"] || 'Da Fare',
        telefonoCliente: String(r["Telefono cliente X"] || r["telefonoCliente"] || ''),
        emailCliente: r["EMAIL"] || r["emailCliente"] || '',
        whatsappInviato: r["Whats CL Inviato"] || r["whatsappInviato"] || '',
        messaggioCliente: r["Note Varie"] || r["messaggioCliente"] || '',
        riferimentoImmobile: r["Riferimento IMMOBILE"] || r["Dup. of Cons"] || r["riferimentoImmobile"] || '',
        indirizzoImmobile: r["Incarichi  [ Ufficio ]"] || r["Incarichi [ Ufficio ]"] || r["indirizzoImmobile"] || '',
        descrizioneImmobile: r["Immobile per cui ha chiamato mail"] || r["descrizioneImmobile"] || '',
        consulenteRiferimento: r["Consulente Rif"] || r["consulenteRiferimento"] || '',
        cellConsulente: String(r["Cell Consulente"] || r["cellConsulente"] || ''),
        linkCalendar: r["Link Calendar"] || r["linkCalendar"] || '',
        linkImmobile: r["Link Imm"] || r["linkImmobile"] || '',
        linkWhatsapp: r["Link Whatsapp"] || r["linkWhatsapp"] || '',
        portale: r["PORTALE"] || r["portale"] || '',
        dataRichiesta: r["Registro di creazione"] || r["dataRichiesta"] || ''
      }));
      if (mapped.length === 0) { alert("Nessuna riga valida trovata nel file (manca la colonna 'Nome'?)."); return; }
      const res = await fetch(`${API_CENTRALINO}/massivo`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(mapped) });
      if(res.ok) { alert(`Importazione completata! ${mapped.length} chiamate importate.`); cambiaVistaCrmLocale('centralino'); }
      else { alert("Errore durante l'importazione."); }
    };
    reader.readAsArrayBuffer(file);
  }

  async function svuotaInteroCentralino() {
    if(!confirm("Svuotare tutto il Registro Chiamate?")) return;
    await fetch(`${API_CENTRALINO}/svuota`, { method: 'DELETE' });
    cambiaVistaCrmLocale('centralino');
  }

  async function eliminaChiamataCentralino(id, nome) {
    if(!confirm(`Eliminare la chiamata di "${nome}"?`)) return;
    const res = await fetch(`${API_CENTRALINO}/${id}`, { method: 'DELETE' });
    if(res.ok) { await sincronizzaCentralinoDaRender(); disegnaTabellaCentralinoCloud(); }
  }

  async function collegaIncaricoACentralino(id, incaricoId) {
    const record = REGISTRO_CENTRALINO_CLOUD.find(r => r._id === id);
    if (record) record.incaricoCollegatoId = incaricoId;
    try {
      await fetch(`${API_CENTRALINO}/${id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ incaricoCollegatoId: incaricoId }) });
    } catch (e) { console.error('Errore collegamento incarico:', e); }
    disegnaTabellaCentralinoCloud();
  }

  async function aggiornaCampoCentralino(id, campo, valore) {
    const record = REGISTRO_CENTRALINO_CLOUD.find(r => r._id === id);
    if (record) record[campo] = valore;
    try {
      const risposta = await fetch(`${API_CENTRALINO}/${id}`, {
        method: 'PUT', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ [campo]: valore })
      });
      const esito = await risposta.json();

      /* Mettendo la colonna su Inviato il server prova a mandare davvero: se
         fallisce lo dice qui. Prima l'errore finiva solo nella console e a
         schermo sembrava che non succedesse nulla. */
      if (esito && esito.invio) {
        if (esito.data && record) Object.assign(record, esito.data);
        if (!esito.invio.fatto) {
          alert('Il messaggio non è partito.\n\n' + (esito.invio.motivo || 'motivo sconosciuto') +
            (esito.invio.passi && esito.invio.passi.length
              ? '\n\nCosa ho guardato:\n' + esito.invio.passi.map(p => '· ' + p).join('\n')
              : ''));
        }
      }
    } catch (e) {
      console.error('Errore aggiornamento centralino:', e);
      alert('Non sono riuscito a salvare: ' + e.message);
    }
    if (['stato', 'tgConsInviato', 'mexClienteInviato'].includes(campo)) disegnaTabellaCentralinoCloud();
    // Se cambia tg o mex, ricalcoliamo e salviamo anche il campo "stato" reale (serve per il raggruppamento vista)
    if ((campo === 'tgConsInviato' || campo === 'mexClienteInviato') && record) {
      const nuovoStato = calcolaStatoSmistamento(record.tgConsInviato, record.mexClienteInviato);
      if (record.stato !== nuovoStato) {
        record.stato = nuovoStato;
        try {
          await fetch(`${API_CENTRALINO}/${id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ stato: nuovoStato }) });
        } catch (e) { console.error('Errore aggiornamento stato centralino:', e); }
      }
      // Se con questo cambiamento l'item diventa "Completo", creiamo in automatico la voce in Banca Dati
      // (il backend evita i doppioni se già creata in precedenza).
      if (nuovoStato === 'Completo') await creaBancaDatiDaCentralino(record);
    }
  }

  function trovaCampoConsulente(nomeConsulente, campo) {
    if (!nomeConsulente) return '';
    const c = REGISTRO_CONSULENTI.find(x => x.nomeCognome === nomeConsulente);
    return c ? (c[campo] || '') : '';
  }
  function trovaCellulareConsulente(nomeConsulente) { return trovaCampoConsulente(nomeConsulente, 'telefono'); }

  const COLONNE_CENTRALINO = [
    { chiave: 'nome', etichetta: 'Nome' },
    { chiave: 'consulente', etichetta: 'Consulente' },
    { chiave: 'tipoRichiesta', etichetta: 'Tipo Richiesta' },
    { chiave: 'fonteRichiesta', etichetta: 'Fonte Richiesta' },
    { chiave: 'stato', etichetta: 'Smistamento Completato' },
    { chiave: 'telefonoCliente', etichetta: 'Telefono' },
    { chiave: 'emailCliente', etichetta: 'Email' },
    { chiave: 'messaggioCliente', etichetta: 'Messaggio' },
    { chiave: 'portale', etichetta: 'Fonte' },
    { chiave: 'incaricoCollegato', etichetta: 'Incarico Collegato' },
    { chiave: 'rifImmobile', etichetta: 'Rif. Immobile' },
    { chiave: 'indirizzo', etichetta: 'Indirizzo' },
    { chiave: 'statoIncarico', etichetta: 'Stato Incarico' },
    { chiave: 'tipologiaContrattoIncarico', etichetta: 'Tipologia Contratto' },
    { chiave: 'linkAnnuncio', etichetta: 'Link Annuncio' },
    { chiave: 'consulenteRif', etichetta: 'Consulente Rif.' },
    { chiave: 'cellConsulente', etichetta: 'Cell. Consulente' },
    { chiave: 'idTelegramConsulente', etichetta: 'ID Telegram' },
    { chiave: 'idWhatsappConsulente', etichetta: 'ID WhatsApp' },
    { chiave: 'dataRichiesta', etichetta: 'Data' },
    { chiave: 'tgConsInviato', etichetta: 'Tg Cons Inviato' },
    { chiave: 'mexClienteInviato', etichetta: 'Mex Cliente Inviato' }
  ];
  const LARGHEZZE_DEFAULT_CENTRALINO = {
    nome: 170, tipoRichiesta: 150, fonteRichiesta: 150, stato: 160, telefonoCliente: 140, emailCliente: 190,
    messaggioCliente: 240, portale: 130, incaricoCollegato: 190, rifImmobile: 100,
    indirizzo: 220, statoIncarico: 130, tipologiaContrattoIncarico: 140, linkAnnuncio: 130, consulenteRif: 170, cellConsulente: 140,
    idTelegramConsulente: 150, idWhatsappConsulente: 150, dataRichiesta: 150,
    tgConsInviato: 150, mexClienteInviato: 150
  };

  function calcolaStatoSmistamento(tg, mex) {
    if (tg === '✅ Inviato' && mex === '✅ Inviato') return 'Completo';
    if (tg === '✅ Inviato' && mex === '❌ Fallito') return 'Solo Consulente';
    if (tg === '❌ Fallito' && mex === '✅ Inviato') return 'Solo Cliente';
    return 'Da Fare';
  }

  function costruisciCellaCentralino(r, chiave) {
    const incaricoCollegato = REGISTRO_INCARICHI_CLOUD.find(i => i._id === r.incaricoCollegatoId);
    switch(chiave) {
      case 'consulente': return cellaConsulente('centralino', r);
      case 'nome': return `<td><input type="text" class="input-cella-stradario" value="${r.nome || ''}" onchange="aggiornaCampoCentralino('${r._id}', 'nome', this.value)"></td>`;
      case 'tipoRichiesta': return `<td>
          <select class="select-cella-stradario" onchange="aggiornaCampoCentralino('${r._id}', 'tipoRichiesta', this.value)">
            <option value="">--</option>
            <option value="Chiamata Richiesta Specifica" ${r.tipoRichiesta === 'Chiamata Richiesta Specifica' ? 'selected':''}>Chiamata Richiesta Specifica</option>
            <option value="Mail Richiesta Specifica" ${r.tipoRichiesta === 'Mail Richiesta Specifica' ? 'selected':''}>Mail Richiesta Specifica</option>
            <option value="Richiesta Generica" ${r.tipoRichiesta === 'Richiesta Generica' ? 'selected':''}>Richiesta Generica</option>
          </select>
        </td>`;
      case 'fonteRichiesta': {
        const fonti = ['', 'Volantino', 'Sito Forte', 'Immobiliare', 'Idealista', 'Wikicasa', 'Facebook', 'Instagram', 'Tik Tok', 'Linkedin', 'X', 'Threads', 'Stato Whatsapp', 'Telegram'];
        return `<td><select class="select-cella-stradario" onchange="aggiornaCampoCentralino('${r._id}', 'fonteRichiesta', this.value)">${fonti.map(f => `<option value="${f}" ${(r.fonteRichiesta || '') === f ? 'selected' : ''}>${f || '—'}</option>`).join('')}</select></td>`;
      }
      case 'stato': {
        const st = r.stato || 'Da Fare';
        const stile = st === 'Fatto' ? 'background:rgba(0,200,117,0.18); color:#00c875;' : 'background:rgba(226,177,60,0.18); color:#e2b13c;';
        return `<td><select class="select-cella-stradario" style="${stile}" onchange="aggiornaCampoCentralino('${r._id}', 'stato', this.value)">
            <option value="Da Fare" ${st === 'Da Fare' ? 'selected' : ''}>Da Fare</option>
            <option value="Fatto" ${st === 'Fatto' ? 'selected' : ''}>Fatto</option>
          </select></td>`;
      }
            case 'telefonoCliente':
        return cellaTelefono(r.telefonoCliente, `aggiornaCampoCentralino('${r._id}', 'telefonoCliente', this.value)`);
      case 'emailCliente': return `<td><input type="email" class="input-cella-stradario" value="${r.emailCliente || ''}" onchange="aggiornaCampoCentralino('${r._id}', 'emailCliente', this.value)"></td>`;
      case 'messaggioCliente': return `<td><input type="text" class="input-cella-stradario" value="${(r.messaggioCliente || '').replace(/"/g, '&quot;')}" onchange="aggiornaCampoCentralino('${r._id}', 'messaggioCliente', this.value)"></td>`;
      case 'incaricoCollegato': {
        const opzioniIncarichi = `<option value="">-- Nessuno --</option>` + REGISTRO_INCARICHI_CLOUD.map(i => `<option value="${i._id}" ${r.incaricoCollegatoId === i._id ? 'selected':''}>${i.nome}</option>`).join('');
        return `<td><select class="select-cella-stradario" style="border-color:#a855f7;" onchange="collegaIncaricoACentralino('${r._id}', this.value)">${opzioniIncarichi}</select></td>`;
      }
      case 'rifImmobile':
        return `<td>${incaricoCollegato ? `<input type="text" class="input-cella-stradario" value="${incaricoCollegato.idElemento || ''}" onchange="aggiornaCampoIncarico('${incaricoCollegato._id}', 'idElemento', this.value)">` : `<span style="color:#64748b;">-</span>`}</td>`;
      case 'indirizzo':
        return `<td>${incaricoCollegato ? `<input type="text" class="input-cella-stradario" value="${incaricoCollegato.posizione || ''}" onchange="aggiornaCampoIncarico('${incaricoCollegato._id}', 'posizione', this.value)">` : `<span style="color:#64748b;">-</span>`}</td>`;
      case 'statoIncarico': {
        if (!incaricoCollegato) return `<td><span style="color:#64748b;">-</span></td>`;
        const coloreStatoM = COLORI_STATO_INCARICO[incaricoCollegato.statoImmobile] || '#868b98';
        const opzioniStatoM = Object.keys(COLORI_STATO_INCARICO).map(s => `<option value="${s}" ${incaricoCollegato.statoImmobile === s ? 'selected':''}>${s}</option>`).join('');
        return `<td><select class="select-cella-stradario" style="background:${coloreStatoM}22; color:${coloreStatoM};" onchange="aggiornaCampoIncarico('${incaricoCollegato._id}', 'statoImmobile', this.value)">${opzioniStatoM}</select></td>`;
      }
      case 'tipologiaContrattoIncarico': {
        if (!incaricoCollegato) return `<td><span style="color:#64748b;">-</span></td>`;
        const stileTCM = incaricoCollegato.tipologiaContratto === 'Vendita' ? 'background:rgba(0,200,117,0.15); color:#00c875;' : (incaricoCollegato.tipologiaContratto === 'Affitto' ? 'background:rgba(226,177,60,0.15); color:#e2b13c;' : '');
        return `<td><select class="select-cella-stradario" style="${stileTCM}" onchange="aggiornaCampoIncarico('${incaricoCollegato._id}', 'tipologiaContratto', this.value)">
            <option value="">--</option>
            <option value="Vendita" ${incaricoCollegato.tipologiaContratto === 'Vendita' ? 'selected':''}>Vendita</option>
            <option value="Affitto" ${incaricoCollegato.tipologiaContratto === 'Affitto' ? 'selected':''}>Affitto</option>
          </select></td>`;
      }
      case 'consulenteRif': {
        const opzioniConsulenti = `<option value="">-- Nessuno --</option>` + REGISTRO_CONSULENTI.map(c => `<option value="${c.nomeCognome}" ${incaricoCollegato && incaricoCollegato.listing === c.nomeCognome ? 'selected':''}>${c.nomeCognome}</option>`).join('');
        return `<td>${incaricoCollegato ? `<select class="select-cella-stradario" onchange="aggiornaCampoIncarico('${incaricoCollegato._id}', 'listing', this.value)">${opzioniConsulenti}</select>` : `<span style="color:#64748b;">-</span>`}</td>`;
      }
      case 'cellConsulente': {
        const cellConsulenteSpecchio = incaricoCollegato ? trovaCellulareConsulente(incaricoCollegato.listing) : '';
        return `<td style="color:#a1a8b3;" title="Si modifica dalla scheda Consulenti">${cellConsulenteSpecchio || '-'}</td>`;
      }
            /* Un trattino non dice se manca l'incarico, il listing o la casella:
         sono tre problemi diversi con tre rimedi diversi. */
      case 'idTelegramConsulente': {
        if (!incaricoCollegato) {
          return `<td style="color:#5f6672; font-size:11.5px;" title="Collega un immobile per vedere il consulente">nessun immobile</td>`;
        }
        if (!incaricoCollegato.listing) {
          return `<td style="color:#e8a0ad; font-size:11.5px;" title="L'incarico non ha un listing">immobile senza listing</td>`;
        }
        const idTg = trovaCampoConsulente(incaricoCollegato.listing, 'idTelegram');
        return `<td title="Si mette dalla scheda del consulente">${
          idTg
            ? `<span style="color:#7fc99a; font-size:11.5px;">${propEsc(idTg)}</span>`
            : `<span style="color:#e8a0ad; font-size:11.5px;">${propEsc(incaricoCollegato.listing)} non ce l'ha</span>`
        }</td>`;
      }
      case 'idWhatsappConsulente': {
        const idWa = incaricoCollegato ? trovaCampoConsulente(incaricoCollegato.listing, 'idWhatsapp') : '';
        return `<td style="color:#a1a8b3;" title="Si modifica dalla scheda Consulenti">${idWa || '-'}</td>`;
      }
      case 'linkAnnuncio': {
        const contenuto = incaricoCollegato ? CAMPI_LINK_INCARICO.map(c => {
          const valore = incaricoCollegato[c.chiave];
          return valore
            ? `<a href="${valore}" target="_blank" style="color:${c.colore}; margin-right:3px;" title="${c.titolo}"><i class="fa-solid ${c.icona}"></i></a><i class="fa-solid fa-pen" style="color:#64748b; font-size:9px; cursor:pointer; margin-right:9px;" title="Modifica ${c.titolo}" onclick="modificaLinkIncarico('${incaricoCollegato._id}', '${c.chiave}', '${c.titolo}')"></i>`
            : `<i class="fa-solid ${c.icona}" style="color:#3e4147; cursor:pointer; margin-right:11px;" title="Aggiungi ${c.titolo}" onclick="modificaLinkIncarico('${incaricoCollegato._id}', '${c.chiave}', '${c.titolo}')"></i>`;
        }).join('') : `<span style="color:#64748b; font-size:12px;">-</span>`;
        return `<td style="white-space:nowrap; padding-bottom:6px;">${contenuto}</td>`;
      }
      case 'portale': return `<td>
          <select class="select-cella-stradario" onchange="aggiornaCampoCentralino('${r._id}', 'portale', this.value)">
            <option value="">--</option>
            <option value="Wikicasa" ${r.portale === 'Wikicasa' ? 'selected':''}>Wikicasa</option>
            <option value="Immobiliare" ${r.portale === 'Immobiliare' ? 'selected':''}>Immobiliare</option>
            <option value="Idealista" ${r.portale === 'Idealista' ? 'selected':''}>Idealista</option>
            <option value="immForte" ${r.portale === 'immForte' ? 'selected':''}>immForte</option>
            <option value="Instagram" ${r.portale === 'Instagram' ? 'selected':''}>Instagram</option>
            <option value="Facebook" ${r.portale === 'Facebook' ? 'selected':''}>Facebook</option>
            <option value="TikTok" ${r.portale === 'TikTok' ? 'selected':''}>TikTok</option>
          </select>
        </td>`;
      case 'dataRichiesta': {
        const dataCreazione = r.createdAt ? new Date(r.createdAt).toLocaleString('it-IT', { day:'2-digit', month:'2-digit', year:'numeric', hour:'2-digit', minute:'2-digit' }) : '-';
        return `<td style="color:#a1a8b3;" title="Data di creazione, automatica">${dataCreazione}</td>`;
      }
      case 'tgConsInviato': return `<td>
          <select class="select-cella-stradario" onchange="aggiornaCampoCentralino('${r._id}', 'tgConsInviato', this.value)">
            <option value="" ${!r.tgConsInviato ? 'selected':''}>--</option>
            <option value="✅ Inviato" ${r.tgConsInviato === '✅ Inviato' ? 'selected':''}>✅ Inviato</option>
            <option value="❌ Fallito" ${r.tgConsInviato === '❌ Fallito' ? 'selected':''}>❌ Fallito</option>
          </select>
        </td>`;
      case 'mexClienteInviato': return `<td>
          <select class="select-cella-stradario" onchange="aggiornaCampoCentralino('${r._id}', 'mexClienteInviato', this.value)">
            <option value="" ${!r.mexClienteInviato ? 'selected':''}>--</option>
            <option value="✅ Inviato" ${r.mexClienteInviato === '✅ Inviato' ? 'selected':''}>✅ Inviato</option>
            <option value="❌ Fallito" ${r.mexClienteInviato === '❌ Fallito' ? 'selected':''}>❌ Fallito</option>
          </select>
        </td>`;
      default: return `<td>-</td>`;
    }
  }

  function disegnaTabellaCentralinoCloud() {
    const container = document.getElementById("monday-tables-container");
    const larghezzeCentralino = LARGHEZZE_COLONNE['centralino'] || {};
    const larghezzaColonnaCentralino = (chiave) => larghezzeCentralino[chiave] || LARGHEZZE_DEFAULT_CENTRALINO[chiave] || 130;
    const COLONNE_SPECCHIO_CENTRALINO = ['rifImmobile', 'indirizzo', 'statoIncarico', 'tipologiaContrattoIncarico', 'consulenteRif', 'cellConsulente', 'linkAnnuncio', 'idTelegramConsulente', 'idWhatsappConsulente'];
    const ORDINE_GRUPPI_CENTRALINO = ['Da Fare', 'Solo Consulente', 'Solo Cliente', 'Completo'];
    const COLORI_GRUPPO_CENTRALINO = { 'Da Fare': '#868b98', 'Solo Consulente': '#e2b13c', 'Solo Cliente': '#e2b13c', 'Completo': '#00c875' };

    const intestazioneTabella = () => {
      let t = `<tr>`;
      COLONNE_CENTRALINO.forEach(c => {
        const classeSpecchio = COLONNE_SPECCHIO_CENTRALINO.includes(c.chiave) ? ' class="valore-specchio"' : '';
        let th = `<th${classeSpecchio} style="position:relative; overflow:visible;"><span>${c.etichetta}</span><span class="resize-handle-colonna" onmousedown="iniziaRidimensionamento(event, 'centralino', '${c.chiave}')"></span></th>`;
        t += decorareCellaColonna(th, c.chiave, larghezzaColonnaCentralino(c.chiave));
      });
      return t + `<th></th></tr>`;
    };

    const costruisciRighe = (elenco) => {
      if (elenco.length === 0) {
        return `<tr><td colspan="${COLONNE_CENTRALINO.length + 1}" style="text-align:center; padding:20px; color:#868b98;">Nessuna chiamata in questo gruppo.</td></tr>`;
      }
      return elenco.map(r => {
        let riga = `<tr>`;
        COLONNE_CENTRALINO.forEach(c => {
          riga += decorareCellaColonna(costruisciCellaCentralino(r, c.chiave), c.chiave, larghezzaColonnaCentralino(c.chiave));
        });
        riga += `<td><button class="btn-cestino-riga" onclick="eliminaChiamataCentralino('${r._id}', '${(r.nome || '').replace(/'/g, "\\'")}')"><i class="fa-solid fa-trash-can"></i></button></td></tr>`;
        return riga;
      }).join('');
    };

    if (REGISTRO_CENTRALINO_CLOUD.length === 0) {
      container.innerHTML = `<table class="monday-table-centralino" style="table-layout:fixed; width:max-content; min-width:100%;"><thead>${intestazioneTabella()}</thead><tbody>
        <tr><td colspan="${COLONNE_CENTRALINO.length + 1}" style="text-align:center; padding:30px; color:#868b98;">Nessuna chiamata presente. Usa "Carica file XLSX" per importare un export, o "Inserisci a mano".</td></tr>
      </tbody></table>`;
      return;
    }

    // Raggruppiamo per stato (calcolato in automatico da Tg Cons Inviato + Mex Cliente Inviato), nell'ordine richiesto
    const datiFiltrati = filtraScheda('centralino', REGISTRO_CENTRALINO_CLOUD);
    const gruppi = {};
    ORDINE_GRUPPI_CENTRALINO.forEach(g => gruppi[g] = []);
    datiFiltrati.forEach(r => {
      const stato = calcolaStatoSmistamento(r.tgConsInviato, r.mexClienteInviato);
      if (!gruppi[stato]) gruppi[stato] = [];
      gruppi[stato].push(r);
    });

    let html = renderizzaFiltriPeriodo('centralino', datiFiltrati.length, REGISTRO_CENTRALINO_CLOUD.length, REGISTRO_CENTRALINO_CLOUD);
    ORDINE_GRUPPI_CENTRALINO.forEach(nomeGruppo => {
      const elenco = gruppi[nomeGruppo] || [];
      const gruppoId = `gruppo-centralino-${nomeGruppo.replace(/\s+/g, '-')}`;
      const chiusa = NODI_APERTI_MEMORIA.has(gruppoId) === false;
      html += `<div style="margin-bottom:14px;">
        <div style="display:flex; align-items:center; gap:8px; padding:8px 10px; background:#1f2126; border-left:4px solid ${COLORI_GRUPPO_CENTRALINO[nomeGruppo] || '#868b98'}; border-radius:4px; cursor:pointer;" onclick="toggleLivelloAlbero(event, '${gruppoId}')">
          <i class="fa-solid ${chiusa ? 'fa-chevron-right' : 'fa-chevron-down'}"></i>
          <strong style="color:${COLORI_GRUPPO_CENTRALINO[nomeGruppo] || '#cbd5e1'};">${nomeGruppo}</strong>
          <span style="color:#868b98; font-size:12px;">(${elenco.length})</span>
        </div>
        <div id="${gruppoId}" style="display:${chiusa ? 'none' : 'block'}; padding-top:8px; overflow-x:auto; max-width:100%;">
          <table class="monday-table-centralino" style="table-layout:fixed; width:max-content; min-width:100%;"><thead>${intestazioneTabella()}</thead><tbody>${costruisciRighe(elenco)}</tbody></table>
        </div>
      </div>`;
    });
    container.innerHTML = html;
  }

  // Import Excel Incarichi: legge un export tipo Monday "Incarichi Gestione" (intestazioni sulla 3ª riga).
  // Il foglio Monday include anche righe "Subitems" (sub-tabella Open House annidata) prive di 'ID elemento':
  // le scartiamo, teniamo solo le righe che rappresentano un vero incarico.
  function normalizzaStatoIncarico(valore) {
    const mappa = {
      'ACQUISITO': 'Acquisito', 'ON LINE': 'On Line', 'PROPOSTA': 'Proposta',
      'VINCOLATO': 'Vincolato', 'DA FARE PREL': 'Da Fare Prel',
      'PREL. OK': 'Prel Ok', 'PREL OK': 'Prel Ok', 'ROGITATO': 'Rogitato', 'SCADUTO': 'Scaduto'
    };
    const chiave = (valore || '').toString().trim().toUpperCase();
    return mappa[chiave] || valore || '';
  }

  function importaFileExcelIncarichi(input) {
    const file = input.files[0]; if (!file) return;
    const reader = new FileReader();
    reader.onload = async function(e) {
      const data = new Uint8Array(e.target.result);
      const workbook = XLSX.read(data, { type: 'array' });
      const sheetName = workbook.SheetNames[0];
      let rows = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName], { range: 2, defval: '' });
      if (rows.length === 0 || !('ID elemento' in rows[0])) {
        rows = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName], { defval: '' });
      }
      const mapped = rows.filter(r => (r["ID elemento"] || '').toString().trim() !== '').map(r => ({
        nome: r["Nome"] || "N.D.",
        idElemento: r["ID elemento"] || '',
        statoImmobile: normalizzaStatoIncarico(r["Imm. Attivo"]),
        statoSecondario: r["Stato"] || '',
        teamLeader: r["TL"] || '',
        listing: r["LISTING"] || '',
        buyer: r["BUYER"] || '',
        nomeVenditore: r["Nome Venditore"] || '',
        residenzaVenditore: r["Residenza"] || '',
        telefonoVenditore: String(r["Telefono Venditore"] || ''),
        posizione: r["Posizione"] || '',
        comune: r["Comune"] || '',
        via: r["Via"] || '',
        civico: String(r["Civico"] || ''),
        nextOpenHouse: String(r["NEXT Open House"] || ''),
        prezzoIncarico: String(r["€ Incarico"] || ''),
        tipologiaContratto: r["Tipologia Contratto"] || '',
        prezzoValutazione: String(r["€ Valutazione"] || ''),
        provvigioneVenditore: String(r["€ Provv Venditore"] || ''),
        dataIncarico: String(r["Data INCARICO"] || ''),
        dataScadenza: String(r["DATA SCADENZA"] || ''),
        contesto: r["Contesto"] || '',
        tipologiaUnita: r["Tipologia Unità"] || '',
        ascensore: r["Ascensore"] || '',
        locali: String(r["Locali"] || ''),
        piano: String(r["Piano"] || ''),
        mq: String(r["Mq"] || ''),
        bagni: String(r["n° Bagni"] || ''),
        box: r["Box"] || '',
        mqBox: String(r["mq Box"] || ''),
        classeApe: r["Classe Ape"] || '',
        ipeApe: String(r["Ipe Ape"] || ''),
        speseCondominiali: String(r["Spese Condominiali Annue"] || ''),
        testoAnnuncio: r["Testo Annuncio"] || '',
        linkVideo: r["Link Video"] || '',
        linkVirtualTour: r["Link Virtual Tour"] || '',
        linkDocumenti: r["Link Documenti"] || '',
        foto: r["FOTO"] || '',
        fotoAllegati: (r["FOTO"] || '').toString().split(/[,;\n]+/).map(x => x.trim()).filter(x => x)
      }));
      if (mapped.length === 0) { alert("Nessun incarico valido trovato nel file (manca la colonna 'ID elemento'?)."); return; }
      const res = await fetch(`${API_INCARICHI}/massivo`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(mapped) });
      if(res.ok) { alert(`Importazione completata! ${mapped.length} incarichi importati.`); cambiaVistaCrmLocale('inc-pure'); }
      else { alert("Errore durante l'importazione."); }
    };
    reader.readAsArrayBuffer(file);
  }

  async function correggiDateExcelIncarichi() {
    const sembraDataExcel = (v) => v && /^\d+(\.\d+)?$/.test(String(v).trim());
    const daCorreggere = REGISTRO_INCARICHI_CLOUD.filter(r =>
      sembraDataExcel(r.dataIncarico) || sembraDataExcel(r.dataScadenza) || sembraDataExcel(r.nextOpenHouse) ||
      (r.gestioneDocumenti && (sembraDataExcel(r.gestioneDocumenti.dataPrimoOH) || sembraDataExcel(r.gestioneDocumenti.dataPubblicazione)))
    );
    if (daCorreggere.length === 0) { alert("Nessuna data da correggere trovata."); return; }
    if (!confirm(`Trovati ${daCorreggere.length} incarichi con date rimaste come numero Excel (es. 46174). Convertirle in date vere?`)) return;

    let corrette = 0;
    for (const r of daCorreggere) {
      const payload = {};
      if (sembraDataExcel(r.dataIncarico)) payload.dataIncarico = serialeExcelInDataIso(r.dataIncarico);
      if (sembraDataExcel(r.dataScadenza)) payload.dataScadenza = serialeExcelInDataIso(r.dataScadenza);
      if (sembraDataExcel(r.nextOpenHouse)) payload.nextOpenHouse = serialeExcelInDataIso(r.nextOpenHouse);
      if (r.gestioneDocumenti && (sembraDataExcel(r.gestioneDocumenti.dataPrimoOH) || sembraDataExcel(r.gestioneDocumenti.dataPubblicazione))) {
        const gdCorretto = { ...r.gestioneDocumenti };
        if (sembraDataExcel(gdCorretto.dataPrimoOH)) gdCorretto.dataPrimoOH = serialeExcelInDataIso(gdCorretto.dataPrimoOH);
        if (sembraDataExcel(gdCorretto.dataPubblicazione)) gdCorretto.dataPubblicazione = serialeExcelInDataIso(gdCorretto.dataPubblicazione);
        payload.gestioneDocumenti = gdCorretto;
      }
      try {
        await fetch(`${API_INCARICHI}/${r._id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
        Object.assign(r, payload);
        corrette++;
      } catch (e) { console.error('Errore correzione data incarico', r._id, e); }
    }
    alert(`Corrette le date su ${corrette} incarichi.`);
    disegnaTabellaIncarichiCloud();
  }

  async function svuotaInteriIncarichi() {
    if(!confirm("Svuotare tutti gli Incarichi?")) return;
    await fetch(`${API_INCARICHI}/svuota`, { method: 'DELETE' });
    cambiaVistaCrmLocale('inc-pure');
  }

  async function eliminaIncaricoCloud(id, nome) {
    if(!confirm(`Eliminare l'incarico "${nome}"?`)) return;
    const res = await fetch(`${API_INCARICHI}/${id}`, { method: 'DELETE' });
    if(res.ok) { await sincronizzaIncarichiDaRender(); disegnaTabellaIncarichiCloud(); }
  }

