  function bandieraDaTelefono(numero) {
    if (!numero) return '';
    let pulito = numero.toString().replace(/[^0-9+]/g, '');
    if (pulito.startsWith('00')) pulito = '+' + pulito.slice(2);
    if (!pulito.startsWith('+')) {
      if (pulito.length >= 9) pulito = '+39' + pulito; // nessun prefisso indicato: assumiamo Italia
      else return '';
    }
    const prefissi = {
      '+39': '🇮🇹', '+49': '🇩🇪', '+33': '🇫🇷', '+34': '🇪🇸', '+41': '🇨🇭', '+43': '🇦🇹',
      '+44': '🇬🇧', '+351': '🇵🇹', '+31': '🇳🇱', '+32': '🇧🇪', '+30': '🇬🇷', '+1': '🇺🇸',
      '+7': '🇷🇺', '+90': '🇹🇷', '+40': '🇷🇴', '+48': '🇵🇱', '+380': '🇺🇦', '+352': '🇱🇺',
      '+377': '🇲🇨', '+378': '🇸🇲', '+385': '🇭🇷', '+386': '🇸🇮', '+420': '🇨🇿', '+421': '🇸🇰',
      '+36': '🇭🇺', '+45': '🇩🇰', '+46': '🇸🇪', '+47': '🇳🇴', '+358': '🇫🇮', '+353': '🇮🇪'
    };
    const prefissiOrdinati = Object.keys(prefissi).sort((a, b) => b.length - a.length);
    for (const p of prefissiOrdinati) {
      if (pulito.startsWith(p)) return prefissi[p];
    }
    return '';
  }

  /* Prefissi telefonici per il menù a tendina (Italia di default) */
  const PREFISSI_TELEFONO = [
    { code: '+39', flag: '🇮🇹' }, { code: '+41', flag: '🇨🇭' }, { code: '+33', flag: '🇫🇷' }, { code: '+49', flag: '🇩🇪' },
    { code: '+34', flag: '🇪🇸' }, { code: '+44', flag: '🇬🇧' }, { code: '+351', flag: '🇵🇹' }, { code: '+43', flag: '🇦🇹' },
    { code: '+31', flag: '🇳🇱' }, { code: '+32', flag: '🇧🇪' }, { code: '+40', flag: '🇷🇴' }, { code: '+48', flag: '🇵🇱' },
    { code: '+380', flag: '🇺🇦' }, { code: '+355', flag: '🇦🇱' }, { code: '+212', flag: '🇲🇦' }, { code: '+30', flag: '🇬🇷' },
    { code: '+385', flag: '🇭🇷' }, { code: '+90', flag: '🇹🇷' }, { code: '+1', flag: '🇺🇸' }, { code: '+7', flag: '🇷🇺' }
  ];
  /* Separa un numero in {prefisso, locale}; default Italia se non riconosciuto */
  function separaPrefisso(numero) {
    let cmp = String(numero || '').replace(/[^0-9+]/g, '');
    if (cmp.startsWith('00')) cmp = '+' + cmp.slice(2);
    const codes = PREFISSI_TELEFONO.map(p => p.code).sort((a, b) => b.length - a.length);
    for (const c of codes) { if (cmp.startsWith(c)) return { prefisso: c, locale: cmp.slice(c.length) }; }
    return { prefisso: '+39', locale: cmp.replace(/^\+/, '') };
  }

  function calcolaGiorniScadenza(dataScadenza) {
    if (!dataScadenza) return { testo: '-', colore: '#64748b' };
    // accetto sia AAAA-MM-GG sia GG/MM/AAAA (prima le date italiane non venivano lette)
    const s = String(dataScadenza).trim();
    let scad = null, m;
    if ((m = s.match(/^(\d{4})-(\d{2})-(\d{2})/))) scad = new Date(+m[1], +m[2] - 1, +m[3]);
    else if ((m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})/))) scad = new Date(+m[3], +m[2] - 1, +m[1]);
    else { const d = new Date(s); if (!isNaN(d.getTime())) scad = d; }
    if (!scad || isNaN(scad.getTime())) return { testo: '-', colore: '#64748b' };
    const oggi = new Date(); oggi.setHours(0, 0, 0, 0); scad.setHours(0, 0, 0, 0);
    const diffGiorni = Math.round((scad - oggi) / 86400000);
    if (diffGiorni < 0) return { testo: `Scaduto da ${Math.abs(diffGiorni)}g`, colore: '#f43f5e' };
    if (diffGiorni === 0) return { testo: 'Scade oggi', colore: '#f43f5e' };
    if (diffGiorni <= 30) return { testo: `${diffGiorni} giorni`, colore: '#e2b13c' };
    return { testo: `${diffGiorni} giorni`, colore: '#00c875' };
  }

  /* ==========================================
     MOTORE VISTE (RAGGRUPPAMENTO, FILTRI, COLONNE VISIBILI)
  ========================================== */
  const API_VISTE = "https://forte-crm-backend.onrender.com/api/viste";
  const API_IMPOSTAZIONI_COLONNE = "https://forte-crm-backend.onrender.com/api/impostazioni-colonne";
  let VISTE_CACHE = {};
  let CONFIG_VISTE = {};
  let GRUPPI_CHIUSI_MEMORIA = new Set();
  let GRUPPO_APERTO_INCARICHI = 'On Line';   // fisarmonica incarichi: un solo gruppo aperto, di default gli online
  let INCARICHI_SELEZIONATI = new Set();       // righe incarichi spuntate col quadratino
  let FILTRO_STATO_INC = 'On Line';            // filtro per stato nella scheda Incarichi (di default gli online)
  function filtraStatoIncarichi(s) { FILTRO_STATO_INC = s || ''; disegnaTabellaIncarichiCloud(); }

  // Colore di sfondo delle tendine (gruppi) degli incarichi, per stato.
  // Dove lo sfondo è chiaro il testo diventa scuro, così resta leggibile.
  const COLORI_TENDINA_INCARICO = {
    'Acquisito':    { bg: '#6b7280', t: '#ffffff' },  // grigio
    'On Line':      { bg: '#0f766e', t: '#ffffff' },  // verde petrolio
    'Proposta':     { bg: '#f2e08a', t: '#3a2f00' },  // giallo chiaro
    'Vincolato':    { bg: '#b8860b', t: '#ffffff' },  // giallo scuro
    'Da Fare Prel': { bg: '#8fd07a', t: '#123d10' },  // verde chiaro
    'Prel Ok':      { bg: '#1f7a34', t: '#ffffff' },  // verde scuro
    'Rogitato':     { bg: '#ffffff', t: '#0B3B4A' },  // bianco
    'Scaduto':      { bg: '#d64545', t: '#ffffff' }   // rosso
  };

  function toggleGruppoIncarichi(nome) {
    GRUPPO_APERTO_INCARICHI = (String(GRUPPO_APERTO_INCARICHI) === String(nome)) ? null : nome;
    disegnaTabellaIncarichiCloud();
  }
  function toggleSelezioneIncarico(id, el) {
    // niente ridisegno: evito il salto. Aggiorno solo lo stato e la riga.
    if (el.checked) INCARICHI_SELEZIONATI.add(id); else INCARICHI_SELEZIONATI.delete(id);
    const tr = el.closest ? el.closest('tr') : null;
    if (tr) tr.style.background = el.checked ? 'rgba(198,167,119,.14)' : '';
  }
  // ridisegna la tabella incarichi ma tiene lo scroll orizzontale/verticale dov'era
  function ridisegnaIncarichiMantieniScroll() {
    let sl = 0, st = 0;
    const cont = document.getElementById('monday-tables-container');
    if (cont) {
      const box = Array.prototype.find.call(cont.querySelectorAll('.scroll-incarichi'), d => d.offsetParent !== null);
      if (box) { sl = box.scrollLeft; st = box.scrollTop; } else { sl = cont.scrollLeft; }
    }
    disegnaTabellaIncarichiCloud();
    const cont2 = document.getElementById('monday-tables-container');
    if (cont2) {
      const box2 = Array.prototype.find.call(cont2.querySelectorAll('.scroll-incarichi'), d => d.offsetParent !== null);
      if (box2) { box2.scrollLeft = sl; box2.scrollTop = st; } else { cont2.scrollLeft = sl; }
    }
  }
  let TABELLA_TIPO_POPUP_COLONNE = null;
  let IMPOSTAZIONI_COLONNE_CACHE = {};
  let COLONNA_MENU_CORRENTE = null;
  let RIDIMENSIONAMENTO_ATTIVO = null;
  let LARGHEZZE_COLONNE = {};
  try { LARGHEZZE_COLONNE = JSON.parse(localStorage.getItem('forte_crm_larghezze_colonne') || '{}'); } catch(e) { LARGHEZZE_COLONNE = {}; }
  function salvaLarghezzeColonne() { try { localStorage.setItem('forte_crm_larghezze_colonne', JSON.stringify(LARGHEZZE_COLONNE)); } catch(e){} }

  async function sincronizzaImpostazioniColonne(tabellaTipo) {
    try {
      const res = await fetch(`${API_IMPOSTAZIONI_COLONNE}/${tabellaTipo}`);
      if (res.ok) IMPOSTAZIONI_COLONNE_CACHE[tabellaTipo] = await res.json();
    } catch(e) {}
  }

  function decorareCellaColonna(html, chiave, larghezza) {
    const stileExtra = larghezza ? `width:${larghezza}px; max-width:${larghezza}px; overflow:hidden; ` : '';
    const conStile = html.match(/^<(th|td)([^>]*)style="([^"]*)"([^>]*)>/);
    if (conStile) {
      return html.replace(/^<(th|td)([^>]*)style="([^"]*)"([^>]*)>/, `<$1$2style="${stileExtra}$3"$4 data-chiave-colonna="${chiave}">`);
    }
    return html.replace(/^<(th|td)([^>]*)>/, `<$1$2 style="${stileExtra}" data-chiave-colonna="${chiave}">`);
  }

  function iniziaRidimensionamento(event, tabellaTipo, chiave) {
    event.preventDefault();
    event.stopPropagation();
    const th = event.target.closest('th');
    RIDIMENSIONAMENTO_ATTIVO = { tabellaTipo, chiave, xIniziale: event.clientX, larghezzaIniziale: th.offsetWidth, larghezzaCorrente: null };
    document.addEventListener('mousemove', gestisciRidimensionamento);
    document.addEventListener('mouseup', terminaRidimensionamento);
  }

  function gestisciRidimensionamento(event) {
    if (!RIDIMENSIONAMENTO_ATTIVO) return;
    const delta = event.clientX - RIDIMENSIONAMENTO_ATTIVO.xIniziale;
    const nuovaLarghezza = Math.max(40, RIDIMENSIONAMENTO_ATTIVO.larghezzaIniziale + delta);
    RIDIMENSIONAMENTO_ATTIVO.larghezzaCorrente = nuovaLarghezza;
    document.querySelectorAll(`th[data-chiave-colonna="${RIDIMENSIONAMENTO_ATTIVO.chiave}"]`).forEach(el => {
      el.style.width = nuovaLarghezza + 'px';
      el.style.maxWidth = nuovaLarghezza + 'px';
    });
  }

  function terminaRidimensionamento() {
    document.removeEventListener('mousemove', gestisciRidimensionamento);
    document.removeEventListener('mouseup', terminaRidimensionamento);
    if (RIDIMENSIONAMENTO_ATTIVO && RIDIMENSIONAMENTO_ATTIVO.larghezzaCorrente) {
      const { tabellaTipo, chiave, larghezzaCorrente } = RIDIMENSIONAMENTO_ATTIVO;
      if (!LARGHEZZE_COLONNE[tabellaTipo]) LARGHEZZE_COLONNE[tabellaTipo] = {};
      LARGHEZZE_COLONNE[tabellaTipo][chiave] = larghezzaCorrente;
      salvaLarghezzeColonne();
      RIDIMENSIONAMENTO_ATTIVO = null;
      ridisegnaTabellaAttiva(tabellaTipo);
    } else {
      RIDIMENSIONAMENTO_ATTIVO = null;
    }
  }

  function apriMenuColonna(event, tabellaTipo, chiave, etichetta) {
    event.stopPropagation();
    COLONNA_MENU_CORRENTE = { tabellaTipo, chiave };
    document.getElementById("popup-menu-colonna-titolo").innerText = etichetta;
    const eAdmin = utenteEBroker();
    const btnConsulenti = document.getElementById("btn-toggle-colonna-consulenti");
    if (eAdmin) {
      btnConsulenti.style.display = "block";
      const impostazioni = IMPOSTAZIONI_COLONNE_CACHE[tabellaTipo] || { colonneNascosteConsulenti: [] };
      const nascosta = (impostazioni.colonneNascosteConsulenti || []).includes(chiave);
      btnConsulenti.innerHTML = nascosta
        ? `<i class="fa-solid fa-user-check" style="width:16px;"></i> Mostra ai consulenti`
        : `<i class="fa-solid fa-user-slash" style="width:16px;"></i> Nascondi ai consulenti`;
    } else {
      btnConsulenti.style.display = "none";
    }
    document.getElementById("popup-menu-colonna-overlay").style.display = "flex";
  }

  function chiudiMenuColonna() {
    document.getElementById("popup-menu-colonna-overlay").style.display = "none";
    COLONNA_MENU_CORRENTE = null;
  }

  function nascondiColonnaPerMe() {
    if (!COLONNA_MENU_CORRENTE) return;
    const { tabellaTipo, chiave } = COLONNA_MENU_CORRENTE;
    const config = ottieniConfigVista(tabellaTipo);
    config.colonneNascoste.add(chiave);
    salvaConfigVistaCorrente(tabellaTipo);
    chiudiMenuColonna();
    ridisegnaTabellaAttiva(tabellaTipo);
  }

  async function toggleColonnaPerConsulenti() {
    if (!COLONNA_MENU_CORRENTE) return;
    const { tabellaTipo, chiave } = COLONNA_MENU_CORRENTE;
    if (!IMPOSTAZIONI_COLONNE_CACHE[tabellaTipo]) IMPOSTAZIONI_COLONNE_CACHE[tabellaTipo] = { colonneNascosteConsulenti: [] };
    const impostazioni = IMPOSTAZIONI_COLONNE_CACHE[tabellaTipo];
    const lista = impostazioni.colonneNascosteConsulenti || [];
    const idx = lista.indexOf(chiave);
    if (idx === -1) lista.push(chiave); else lista.splice(idx, 1);
    impostazioni.colonneNascosteConsulenti = lista;
    try {
      await fetch(`${API_IMPOSTAZIONI_COLONNE}/${tabellaTipo}`, { method:'PUT', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ colonneNascosteConsulenti: lista }) });
    } catch(e) { console.error('Errore salvataggio impostazioni colonne:', e); }
    chiudiMenuColonna();
    ridisegnaTabellaAttiva(tabellaTipo);
  }

  /* Colonne nascoste della vista base di ogni tabella: salvate nel browser
     (localStorage) cosi' restano anche dopo aver ricaricato la pagina. Le viste
     salvate su Mongo hanno le loro; questo vale per la Scheda Principale. */
  function colonneNascosteLocali(tabellaTipo) {
    try { const t = JSON.parse(localStorage.getItem('forte_crm_colonne_nascoste') || '{}'); return Array.isArray(t[tabellaTipo]) ? t[tabellaTipo] : []; }
    catch (e) { return []; }
  }
  function salvaColonneNascosteLocale(tabellaTipo, set) {
    try {
      const t = JSON.parse(localStorage.getItem('forte_crm_colonne_nascoste') || '{}');
      t[tabellaTipo] = Array.from(set || []);
      localStorage.setItem('forte_crm_colonne_nascoste', JSON.stringify(t));
    } catch (e) {}
  }

  function configPredefinita(tabellaTipo) {
    if (tabellaTipo === 'incarichi') {
      return {
        vistaAttivaId: null, raggruppaPer: '', colonneNascoste: new Set(colonneNascosteLocali(tabellaTipo)),
        filtroPersona: '', filtroColonna: '', filtroValore: '', filtriAvanzati: [],
        ordineGruppi: ['Acquisito', 'On Line', 'Vincolato', 'Da Fare Prel', 'Prel Ok', 'Rogitato', 'Scaduto'],
        coloriGruppi: {}, ordinamento: null
      };
    }
    if (tabellaTipo === 'centralino') {
      return {
        vistaAttivaId: null, raggruppaPer: 'stato', colonneNascoste: new Set(colonneNascosteLocali(tabellaTipo)),
        filtroPersona: '', filtroColonna: '', filtroValore: '', filtriAvanzati: [],
        ordineGruppi: ['Da Fare', 'Solo Consulente', 'Solo Cliente', 'Completo'],
        coloriGruppi: {}, ordinamento: null
      };
    }
    return { vistaAttivaId: null, raggruppaPer: '', colonneNascoste: new Set(colonneNascosteLocali(tabellaTipo)), filtroPersona: '', filtroColonna: '', filtroValore: '', filtriAvanzati: [], ordineGruppi: [], coloriGruppi: {}, ordinamento: null };
  }

  function ottieniConfigVista(tabellaTipo) {
    if (!CONFIG_VISTE[tabellaTipo]) {
      CONFIG_VISTE[tabellaTipo] = configPredefinita(tabellaTipo);
    }
    return CONFIG_VISTE[tabellaTipo];
  }

  function cambiaColoreGruppo(tabellaTipo, nomeGruppo, colore) {
    const config = ottieniConfigVista(tabellaTipo);
    if (!config.coloriGruppi) config.coloriGruppi = {};
    config.coloriGruppi[nomeGruppo] = colore;
    salvaConfigVistaCorrente(tabellaTipo);
    ridisegnaTabellaAttiva(tabellaTipo);
  }

  // Ordina i nomi-gruppo secondo l'ordine salvato in config.ordineGruppi; i gruppi nuovi (mai visti prima)
  // vengono aggiunti in coda, così non spariscono. Aggiorna anche config.ordineGruppi con l'elenco completo.
  function ordinaGruppi(tabellaTipo, chiaviGruppi) {
    const config = ottieniConfigVista(tabellaTipo);
    const ordineAttuale = config.ordineGruppi || [];
    const ordinate = ordineAttuale.filter(g => chiaviGruppi.includes(g));
    const nuove = chiaviGruppi.filter(g => !ordineAttuale.includes(g));
    const risultato = ordinate.concat(nuove);
    config.ordineGruppi = risultato;
    return risultato;
  }

  // Ordina un elenco di record secondo config.ordinamento = {colonna, direzione}
  function ordinaDati(dati, ordinamento) {
    if (!ordinamento || !ordinamento.colonna) return dati;
    const { colonna, direzione } = ordinamento;
    const copia = dati.slice();
    copia.sort((a, b) => {
      const va = a[colonna]; const vb = b[colonna];
      const na = parseFloat(va); const nb = parseFloat(vb);
      let cmp;
      if (va !== '' && vb !== '' && va !== undefined && vb !== undefined && !isNaN(na) && !isNaN(nb)) cmp = na - nb;
      else cmp = String(va || '').localeCompare(String(vb || ''), 'it', { sensitivity: 'base' });
      return direzione === 'asc' ? cmp : -cmp;
    });
    return copia;
  }

  function alternaOrdinamento(tabellaTipo, chiave) {
    const config = ottieniConfigVista(tabellaTipo);
    if (!config.ordinamento || config.ordinamento.colonna !== chiave) {
      config.ordinamento = { colonna: chiave, direzione: 'asc' };
    } else if (config.ordinamento.direzione === 'asc') {
      config.ordinamento.direzione = 'desc';
    } else {
      config.ordinamento = null;
    }
    salvaConfigVistaCorrente(tabellaTipo);
    ridisegnaTabellaAttiva(tabellaTipo);
  }

  function iconaOrdinamento(tabellaTipo, chiave) {
    const config = ottieniConfigVista(tabellaTipo);
    if (!config.ordinamento || config.ordinamento.colonna !== chiave) return 'fa-sort';
    return config.ordinamento.direzione === 'asc' ? 'fa-sort-up' : 'fa-sort-down';
  }

  let GRUPPO_TRASCINATO = null;

  function iniziaTrascinamentoGruppo(event, tabellaTipo, nomeGruppo) {
    GRUPPO_TRASCINATO = { tabellaTipo, nomeGruppo };
    event.dataTransfer.effectAllowed = 'move';
    try { event.dataTransfer.setData('text/plain', nomeGruppo); } catch(e) {}
  }

  function consentiTrascinamentoGruppo(event) {
    event.preventDefault();
    event.dataTransfer.dropEffect = 'move';
  }

  function rilasciaGruppoSu(event, tabellaTipo, nomeGruppoDestinazione) {
    event.preventDefault();
    if (!GRUPPO_TRASCINATO || GRUPPO_TRASCINATO.tabellaTipo !== tabellaTipo) return;
    const nomeOrigine = GRUPPO_TRASCINATO.nomeGruppo;
    GRUPPO_TRASCINATO = null;
    if (nomeOrigine === nomeGruppoDestinazione) return;
    const config = ottieniConfigVista(tabellaTipo);
    const lista = (config.ordineGruppi || []).slice();
    const idxOrigine = lista.indexOf(nomeOrigine);
    if (idxOrigine === -1) return;
    lista.splice(idxOrigine, 1);
    const idxDestinazione = lista.indexOf(nomeGruppoDestinazione);
    if (idxDestinazione === -1) { lista.push(nomeOrigine); } else { lista.splice(idxDestinazione, 0, nomeOrigine); }
    config.ordineGruppi = lista;
    salvaConfigVistaCorrente(tabellaTipo);
    ridisegnaTabellaAttiva(tabellaTipo);
  }

  async function sincronizzaViste(tabellaTipo) {
    try {
      const res = await fetch(`${API_VISTE}?tabellaTipo=${tabellaTipo}`);
      if (res.ok) VISTE_CACHE[tabellaTipo] = await res.json();
    } catch(e) {}
  }

  function ridisegnaTabellaAttiva(tabellaTipo) {
    if (tabellaTipo === 'incarichi') disegnaTabellaIncarichiCloud();
    if (tabellaTipo === 'centralino') disegnaTabellaCentralinoCloud();
    if (tabellaTipo === 'concorrenza') ridisegnaVistaConcorrenzaCorrente();
  }

  function cambiaTabVista(tabellaTipo, vistaId) {
    const config = ottieniConfigVista(tabellaTipo);
    MENU_VISTE_APERTO_PER = null;
    if (!vistaId) {
      const predef = configPredefinita(tabellaTipo);
      Object.assign(config, predef);
    } else {
      const vista = (VISTE_CACHE[tabellaTipo] || []).find(v => v._id === vistaId);
      if (!vista) return;
      config.vistaAttivaId = vistaId;
      config.raggruppaPer = vista.raggruppaPer || '';
      config.colonneNascoste = new Set(vista.colonneNascoste || []);
      config.filtroColonna = vista.filtroColonna || '';
      config.filtroValore = vista.filtroValore || '';
      config.filtriAvanzati = vista.filtriAvanzati || [];
      config.filtroPersona = '';
      config.ordineGruppi = (vista.ordineGruppi || []).slice();
      config.coloriGruppi = { ...(vista.coloriGruppi || {}) };
      config.ordinamento = vista.ordinamentoColonna ? { colonna: vista.ordinamentoColonna, direzione: vista.ordinamentoDirezione || 'asc' } : null;
    }
    ridisegnaTabellaAttiva(tabellaTipo);
  }

  async function apriNuovaVistaPrompt(tabellaTipo) {
    let nome = prompt("Nome della nuova vista:"); if(!nome) return;
    const config = ottieniConfigVista(tabellaTipo);
    const res = await fetch(API_VISTE, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({
      tabellaTipo, nome: nome.trim(), raggruppaPer: config.raggruppaPer, colonneNascoste: Array.from(config.colonneNascoste), filtroColonna: config.filtroColonna, filtroValore: config.filtroValore, filtriAvanzati: config.filtriAvanzati || [], ordineGruppi: config.ordineGruppi || [],
      coloriGruppi: config.coloriGruppi || {}, ordinamentoColonna: config.ordinamento ? config.ordinamento.colonna : '', ordinamentoDirezione: config.ordinamento ? config.ordinamento.direzione : ''
    })});
    const data = await res.json();
    await sincronizzaViste(tabellaTipo);
    if (data && data.data) config.vistaAttivaId = data.data._id;
    MENU_VISTE_APERTO_PER = null;
    ridisegnaTabellaAttiva(tabellaTipo);
  }

  async function eliminaVistaCorrente(tabellaTipo, vistaId) {
    const idDaEliminare = vistaId || ottieniConfigVista(tabellaTipo).vistaAttivaId;
    if (!idDaEliminare) return;
    if (!confirm("Eliminare questa vista?")) return;
    await fetch(`${API_VISTE}/${idDaEliminare}`, { method:'DELETE' });
    await sincronizzaViste(tabellaTipo);
    MENU_VISTE_APERTO_PER = null;
    cambiaTabVista(tabellaTipo, null);
  }

  async function salvaConfigVistaCorrente(tabellaTipo) {
    const config = ottieniConfigVista(tabellaTipo);
    if (!config.vistaAttivaId) return; // la Scheda Principale resta locale alla sessione, non si salva
    await fetch(`${API_VISTE}/${config.vistaAttivaId}`, { method:'PUT', headers:{'Content-Type':'application/json'}, body: JSON.stringify({
      raggruppaPer: config.raggruppaPer, colonneNascoste: Array.from(config.colonneNascoste), filtroColonna: config.filtroColonna, filtroValore: config.filtroValore, filtriAvanzati: config.filtriAvanzati || [], ordineGruppi: config.ordineGruppi || [],
      coloriGruppi: config.coloriGruppi || {}, ordinamentoColonna: config.ordinamento ? config.ordinamento.colonna : '', ordinamentoDirezione: config.ordinamento ? config.ordinamento.direzione : ''
    })});
    const v = (VISTE_CACHE[tabellaTipo] || []).find(v => v._id === config.vistaAttivaId);
    if (v) {
      v.raggruppaPer = config.raggruppaPer; v.colonneNascoste = Array.from(config.colonneNascoste); v.filtroColonna = config.filtroColonna; v.filtroValore = config.filtroValore; v.filtriAvanzati = config.filtriAvanzati || [];
      v.ordineGruppi = config.ordineGruppi || []; v.coloriGruppi = config.coloriGruppi || {};
      v.ordinamentoColonna = config.ordinamento ? config.ordinamento.colonna : ''; v.ordinamentoDirezione = config.ordinamento ? config.ordinamento.direzione : '';
    }
  }

  function cambiaFiltroPersona(tabellaTipo, valore) {
    ottieniConfigVista(tabellaTipo).filtroPersona = valore;
    ridisegnaTabellaAttiva(tabellaTipo);
  }

  function cambiaRaggruppamento(tabellaTipo, valore) {
    ottieniConfigVista(tabellaTipo).raggruppaPer = valore;
    salvaConfigVistaCorrente(tabellaTipo);
    ridisegnaTabellaAttiva(tabellaTipo);
  }

  function toggleGruppoTabella(tabellaTipo, idBlocco) {
    if (GRUPPI_CHIUSI_MEMORIA.has(idBlocco)) GRUPPI_CHIUSI_MEMORIA.delete(idBlocco);
    else GRUPPI_CHIUSI_MEMORIA.add(idBlocco);
    ridisegnaTabellaAttiva(tabellaTipo);
  }

  /* Registro dei metadati colonne per tipo di tabella: lo riempie
     renderizzaBarraViste (che li riceve gia'), cosi' il popup "Colonne" e il
     nascondere-colonne sanno quali colonne esistono per QUALSIASI tabella, non
     solo per gli incarichi (prima era cablato solo su 'incarichi'). */
  const COLONNE_META_PER_TABELLA = {};

  /* Nasconde nel DOM le colonne spuntate come non-visibili. Generico: abbina
     l'etichetta della colonna al testo dell'intestazione <th> e nasconde quella
     colonna in tutte le righe (stesso indice). Funziona su tabelle con
     intestazioni fisse (Concorrenza) senza doverle riscrivere a colonne. */
  function applicaColonneNascoste(tabellaTipo) {
    const config = ottieniConfigVista(tabellaTipo);
    if (!config || !config.colonneNascoste || !config.colonneNascoste.size) return;
    const meta = COLONNE_META_PER_TABELLA[tabellaTipo]
      || (tabellaTipo === 'concorrenza' ? COLONNE_META_CONCORRENZA : [])
      || [];
    const nascoste = {};
    meta.forEach(c => { if (config.colonneNascoste.has(c.chiave)) nascoste[(c.etichetta || '').trim().toLowerCase()] = true; });
    if (!Object.keys(nascoste).length) return;
    const cont = document.getElementById('monday-tables-container');
    if (!cont) return;
    cont.querySelectorAll('table').forEach(tab => {
      const ths = tab.querySelectorAll('thead th');
      const indici = [];
      ths.forEach((th, i) => { if (nascoste[(th.textContent || '').trim().toLowerCase()]) indici.push(i); });
      if (!indici.length) return;
      indici.forEach(i => { ths[i].style.display = 'none'; });
      tab.querySelectorAll('tbody tr').forEach(tr => {
        if (tr.children.length !== ths.length) return;   // salto righe speciali (colspan, es. "nessun dato")
        indici.forEach(i => { if (tr.children[i]) tr.children[i].style.display = 'none'; });
      });
    });
  }

  /* Popup "Colonne" ricostruito al volo e agganciato al body: non dipende piu'
     dall'elemento statico (che in alcune situazioni Squarespace non mostra o
     lascia intrappolato dietro), cosi' si apre sempre e sopra tutto. */
  function apriPopupColonneVisibili(tabellaTipo) {
    TABELLA_TIPO_POPUP_COLONNE = tabellaTipo;
    const config = ottieniConfigVista(tabellaTipo);
    const colonneMeta = COLONNE_META_PER_TABELLA[tabellaTipo]
      || (tabellaTipo === 'incarichi' ? COLONNE_INCARICHI
        : tabellaTipo === 'concorrenza' ? COLONNE_META_CONCORRENZA
        : []);
    const righe = (colonneMeta || []).map(c => {
      const visibile = !config.colonneNascoste.has(c.chiave);
      return `<label style="display:flex; align-items:center; gap:10px; padding:8px 10px; border-radius:7px; cursor:pointer; background:#191b1f; border:1px solid #2c2f35;">
        <input type="checkbox" ${visibile ? 'checked' : ''} onchange="toggleColonnaVisibile('${tabellaTipo}', '${c.chiave}', this.checked)" style="width:16px; height:16px; cursor:pointer;">
        <span style="color:#e6e9ef; font-size:13px;">${c.etichetta}</span></label>`;
    }).join('') || `<div style="color:#868b98; font-size:13px;">Nessuna colonna configurabile per questa scheda.</div>`;

    let ov = document.getElementById('popup-colonne-dyn-overlay');
    if (!ov) {
      ov = document.createElement('div');
      ov.id = 'popup-colonne-dyn-overlay';
      ov.style.cssText = 'position:fixed; inset:0; z-index:100060; background:rgba(0,0,0,.6); display:flex; align-items:center; justify-content:center; padding:20px;';
      ov.onclick = (e) => { if (e.target === ov) chiudiPopupColonneVisibili(); };
      document.body.appendChild(ov);
    }
    ov.innerHTML = `<div style="background:#202226; border:1px solid #3e4147; border-radius:12px; padding:22px; width:340px; max-width:92vw; max-height:80vh; overflow-y:auto; font-family:'Plus Jakarta Sans', sans-serif;">
      <h3 style="color:#fff; margin:0 0 6px; font-size:16px;">Colonne visibili</h3>
      <div style="color:#868b98; font-size:12px; margin-bottom:14px;">Togli la spunta per nascondere una colonna.</div>
      <div style="display:flex; flex-direction:column; gap:6px; margin-bottom:18px;">${righe}</div>
      <button onclick="chiudiPopupColonneVisibili()" style="width:100%; background:#00c875; border:none; color:#18191c; padding:11px; border-radius:7px; cursor:pointer; font-weight:700; font-family:inherit;">Chiudi</button>
    </div>`;
    ov.style.display = 'flex';
  }

  function chiudiPopupColonneVisibili() {
    const ov = document.getElementById('popup-colonne-dyn-overlay');
    if (ov) ov.style.display = 'none';
    const statico = document.getElementById('popup-colonne-vista-overlay');   // se restasse la vecchia versione, la chiudo comunque
    if (statico) statico.style.display = 'none';
    if (TABELLA_TIPO_POPUP_COLONNE) { salvaConfigVistaCorrente(TABELLA_TIPO_POPUP_COLONNE); ridisegnaTabellaAttiva(TABELLA_TIPO_POPUP_COLONNE); }
    TABELLA_TIPO_POPUP_COLONNE = null;
  }

  function toggleColonnaVisibile(tabellaTipo, chiave, visibile) {
    const config = ottieniConfigVista(tabellaTipo);
    if (visibile) config.colonneNascoste.delete(chiave); else config.colonneNascoste.add(chiave);
    // Se e' la Scheda Principale (nessuna vista salvata attiva) memorizzo la
    // scelta nel browser, cosi' resta anche dopo il refresh. Le viste salvate
    // su Mongo la conservano da sole (salvaConfigVistaCorrente).
    if (!config.vistaAttivaId) salvaColonneNascosteLocale(tabellaTipo, config.colonneNascoste);
    // Effetto immediato: ridisegno la tabella dietro al popup (che resta aperto),
    // cosi' la colonna sparisce/riappare subito e non sembra che non funzioni.
    ridisegnaTabellaAttiva(tabellaTipo);
  }

  function renderizzaBarraViste(tabellaTipo, colonneMeta, colonneRaggruppabili, datiCorrenti) {
    const config = ottieniConfigVista(tabellaTipo);
    const viste = VISTE_CACHE[tabellaTipo] || [];
    // Memorizzo i metadati colonne di questa tabella, cosi' il popup "Colonne" e
    // applicaColonneNascoste sanno cosa nascondere anche fuori dagli incarichi.
    if (Array.isArray(colonneMeta) && colonneMeta.length) COLONNE_META_PER_TABELLA[tabellaTipo] = colonneMeta;
    // Incarichi: la barra viste non serve (Stato e Colonne stanno nella riga filtri). Registro solo i metadati colonne.
    if (tabellaTipo === 'incarichi') return '';

    // Concorrenza ha 4 viste "integrate" fisse (non salvate su Mongo, sono filtri di base) che
    // compaiono nello stesso menu delle viste personalizzate salvate dall'utente.
    /* Le voci dipendono dalla scheda aperta: la tabella di quel tipo, la mappa,
       e la classifica agenzie solo dove ha senso, cioe' sulla concorrenza. */
    const NOMI_TIPO_CONCORRENZA = { 'agenzia': 'Concorrenza', 'vdp': 'Vdp', 'vdp-no-numero': 'Vdp No Numero' };
    const ICONE_TIPO_CONCORRENZA = { 'agenzia': 'fa-building', 'vdp': 'fa-user', 'vdp-no-numero': 'fa-user-slash' };
    const VISTE_INTEGRATE_CONCORRENZA = [
      { chiave: 'tabella', nome: NOMI_TIPO_CONCORRENZA[TIPO_CONCORRENZA] || 'Concorrenza', icona: ICONE_TIPO_CONCORRENZA[TIPO_CONCORRENZA] || 'fa-building' },
      { chiave: 'kanban', nome: 'Kanban Sviluppo', icona: 'fa-table-columns' },
      { chiave: 'consulenti', nome: 'Analisi Consulenti', icona: 'fa-user-tie' },
      { chiave: 'mappa', nome: 'Mappa', icona: 'fa-map-location-dot' }
    ].concat(TIPO_CONCORRENZA === 'agenzia'
      ? [{ chiave: 'classifica', nome: 'Ranking Agenzie', icona: 'fa-ranking-star' }] : []);
    const eConcorrenza = tabellaTipo === 'concorrenza';

    let nomeVistaCorrente;
    if (eConcorrenza) {
      nomeVistaCorrente = config.vistaAttivaId
        ? ((viste.find(v => v._id === config.vistaAttivaId) || {}).nome || 'Concorrenza Agenzia')
        : ((VISTE_INTEGRATE_CONCORRENZA.find(v => v.chiave === MODO_CONCORRENZA) || {}).nome || 'Concorrenza');
    } else {
      nomeVistaCorrente = config.vistaAttivaId ? ((viste.find(v => v._id === config.vistaAttivaId) || {}).nome || 'Scheda Principale') : 'Scheda Principale';
    }

    const menuVisteApertoQui = MENU_VISTE_APERTO_PER === tabellaTipo;
    let menuVisteHtml = '';
    if (menuVisteApertoQui) {
      let righeMenu = '';
      if (eConcorrenza) {
        VISTE_INTEGRATE_CONCORRENZA.forEach(v => {
          const attiva = !config.vistaAttivaId && MODO_CONCORRENZA === v.chiave;
          righeMenu += `<div class="voce-menu-vista ${attiva ? 'selezionata':''}" onclick="cambiaVistaConcorrenza('${v.chiave}'); cambiaTabVista('${tabellaTipo}', null);"><i class="fa-solid ${v.icona}"></i> ${v.nome}</div>`;
        });
        righeMenu += `<div style="border-top:1px solid #3e4147; margin:6px 0;"></div>`;
      } else {
        righeMenu += `<div class="voce-menu-vista ${!config.vistaAttivaId ? 'selezionata':''}" onclick="cambiaTabVista('${tabellaTipo}', null)"><i class="fa-solid fa-house"></i> Scheda Principale</div>`;
      }
      viste.forEach(v => {
        righeMenu += `<div class="voce-menu-vista ${config.vistaAttivaId === v._id ? 'selezionata':''}">
          <span style="flex:1; cursor:pointer;" onclick="cambiaTabVista('${tabellaTipo}', '${v._id}')"><i class="fa-solid fa-table-list"></i> ${v.nome}</span>
          <span onclick="eliminaVistaCorrente('${tabellaTipo}', '${v._id}')" style="color:#868b98; cursor:pointer; padding:2px 6px;"><i class="fa-solid fa-trash-can"></i></span>
        </div>`;
      });
      menuVisteHtml = `
        <div class="pannello-filtri-avanzati-overlay" style="position:absolute; top:44px; left:0; z-index:500; background:#202226; border:1px solid #3e4147; border-radius:8px; padding:8px; width:220px; box-shadow:0 10px 40px rgba(0,0,0,0.5);">
          ${righeMenu}
          <div style="border-top:1px solid #3e4147; margin-top:6px; padding-top:6px;">
            <div class="voce-menu-vista" style="color:#00c875;" onclick="apriNuovaVistaPrompt('${tabellaTipo}')"><i class="fa-solid fa-plus"></i> Nuova vista</div>
          </div>
        </div>`;
    }

    let persone = new Set();
    // La Concorrenza usa 'consulente' (username); le altre schede teamLeader/listing/buyer (nomi).
    const campiPersona = (tabellaTipo === 'concorrenza') ? ['consulente'] : ['teamLeader','listing','buyer'];
    datiCorrenti.forEach(r => { campiPersona.forEach(c => { if (r[c]) persone.add(r[c]); }); });
    const etichettaPersona = (p) => tabellaTipo === 'concorrenza' ? nomeConsulente(p) : p;
    let opzioniPersona = `<option value="">👤 Persona: tutte</option>` + Array.from(persone).sort().map(p => `<option value="${p}" ${config.filtroPersona === p ? 'selected':''}>${etichettaPersona(p)}</option>`).join('');

    let opzioniRaggruppa = `<option value="">🔀 Raggruppa per: nessuno</option>` + colonneRaggruppabili.map(chiave => {
      const meta = colonneMeta.find(c => c.chiave === chiave);
      return `<option value="${chiave}" ${config.raggruppaPer === chiave ? 'selected':''}>${meta ? meta.etichetta : chiave}</option>`;
    }).join('');

    const filtriAvanzati = config.filtriAvanzati || [];
    const nFiltriAttivi = filtriAvanzati.filter(f => f.colonna).length;
    const panelloApertoQui = PANNELLO_FILTRI_APERTO_PER === tabellaTipo;

    // Negli Incarichi queste tendine non si usano (Scheda Principale, Persona, Filtro, Raggruppa per): le nascondo.
    const eIncarichi = tabellaTipo === 'incarichi';
    const controlliHtml = eIncarichi ? '' : `
        <div class="pillola-monday" style="cursor:pointer; font-weight:700;" onclick="toggleAperturaMenuViste('${tabellaTipo}')">
          <i class="fa-solid fa-table-list icona-pillola"></i>
          <span style="color:white; font-size:13px; font-weight:700;">${nomeVistaCorrente}</span>
          <i class="fa-solid fa-chevron-down freccia-pillola" style="margin-left:2px;"></i>
        </div>
        ${menuVisteHtml}
        <div class="pillola-monday${config.filtroPersona ? ' attiva' : ''}">
          <i class="fa-solid fa-user icona-pillola"></i>
          <select onchange="cambiaFiltroPersona('${tabellaTipo}', this.value)">${opzioniPersona}</select>
          <i class="fa-solid fa-chevron-down freccia-pillola"></i>
        </div>
        <div class="pillola-monday${nFiltriAttivi ? ' attiva' : ''}" style="cursor:pointer;" onclick="toggleAperturaPannelloFiltri('${tabellaTipo}')">
          <i class="fa-solid fa-filter icona-pillola"></i>
          <span style="color:#cbd5e1; font-size:13px; font-weight:600;">Filtro</span>
          ${nFiltriAttivi ? `<span class="badge-contatore-pillola">/ ${nFiltriAttivi}</span>` : ''}
          <i class="fa-solid fa-chevron-down freccia-pillola" style="margin-left:2px;"></i>
        </div>
        <div class="pillola-monday${config.raggruppaPer ? ' attiva' : ''}">
          <i class="fa-solid fa-layer-group icona-pillola"></i>
          <select onchange="cambiaRaggruppamento('${tabellaTipo}', this.value)">${opzioniRaggruppa}</select>
          <i class="fa-solid fa-chevron-down freccia-pillola"></i>
        </div>`;
    return `
      <div style="display:flex; gap:10px; margin-bottom:12px; flex-wrap:wrap; align-items:center; position:relative;">
        ${controlliHtml}
        <button class="pillola-monday" style="cursor:pointer;" onclick="apriPopupColonneVisibili('${tabellaTipo}')"><i class="fa-solid fa-ellipsis-vertical icona-pillola"></i> <span style="color:#cbd5e1; font-size:13px; font-weight:600;">Colonne</span></button>
        ${panelloApertoQui ? costruisciPannelloFiltriAvanzati(tabellaTipo, colonneRaggruppabili, colonneMeta, datiCorrenti) : ''}
      </div>
    `;
  }

  let MENU_VISTE_APERTO_PER = null;

  function toggleAperturaMenuViste(tabellaTipo) {
    MENU_VISTE_APERTO_PER = (MENU_VISTE_APERTO_PER === tabellaTipo) ? null : tabellaTipo;
    PANNELLO_FILTRI_APERTO_PER = null;
    ridisegnaTabellaAttiva(tabellaTipo);
  }

  let PANNELLO_FILTRI_APERTO_PER = null;

  function toggleAperturaPannelloFiltri(tabellaTipo) {
    PANNELLO_FILTRI_APERTO_PER = (PANNELLO_FILTRI_APERTO_PER === tabellaTipo) ? null : tabellaTipo;
    ridisegnaTabellaAttiva(tabellaTipo);
  }

  /* Colonne che hanno un elenco chiuso di valori: li propongo sempre tutti,
     anche quelli che al momento non compaiono in nessuna riga. */
  function opzioniNoteColonna(chiave) {
    const provaSicura = (f) => { try { const v = f(); return Array.isArray(v) ? v : []; } catch (e) { return []; } };

    /* Colonne che nelle tabelle sono menu a tendina: qui riuso le stesse liste,
       cosi' il filtro propone esattamente le voci che trovi nella cella. */
    const elenchi = {
      // concorrenza / vdp
      statoSviluppo:        () => STATI_SVILUPPO_CONCORRENZA.map(s => s.nome),
      statoAnnuncio:        () => ['Attivo', 'Ritirato', 'Venduto'],
      consulente:           () => (typeof REGISTRO_CONSULENTI !== 'undefined' ? REGISTRO_CONSULENTI : []).map(c => c.utente).filter(Boolean),
      privato:              () => ['VDP', 'VDP NO NUMERO'],
      // proposte, preliminari, rogiti
      statoProposta:        () => STATI_PROPOSTA.map(s => s.nome),
      statoAttuale:         () => STATI_PRELIMINARE.concat(STATI_ROGITO),
      vincolo:              () => ['si', 'no'],
      provvAcquirenteStato: () => ['Da incassare', 'Incassata'],
      provvVenditoreStato:  () => ['Da incassare', 'Incassata'],
      // incarichi
      statoImmobile:        () => Object.keys(COLORI_STATO_INCARICO),
      tipologiaContratto:   () => ['Vendita', 'Affitto'],
      contesto:             () => OPZIONI_CONTESTO_INCARICO,
      tipologiaUnita:       () => OPZIONI_TIPOLOGIA_INCARICO,
      unita:                () => OPZIONI_TIPOLOGIA_INCARICO,
      // opportunity e cdv
      fonte:                () => FONTI_OPPORTUNITY,
      esitoUltimaAttivita:  () => ESITI_ATTIVITA,
      statoProprietario:    () => ESITI_ATTIVITA,
      semaforoConcorrenza:  () => SEMAFORO_CONCORRENZA,
      statoZona:            () => STATI_CENSIMENTO,
      statoVdp:             () => STATI_CENSIMENTO,
      attivitaVdp:          () => STATI_CENSIMENTO,
      attivitaConcorrenza:  () => STATI_CENSIMENTO,
      statoNecrologio:      () => STATI_CENSIMENTO,
      attivitaNecrologio:   () => STATI_CENSIMENTO,
      livello:              () => ['Info', 'Opportunity'],
      venditaAffitto:       () => ['Vendita', 'Affitto'],
      ristrutturazione:     () => ['S\u00ec', 'No', 'Da Valutare'],
      riacquisto:           () => ['S\u00ec', 'No', 'Da Valutare'],
      // professionisti
      gruppo:               () => gruppiProfessionisti(),
      tipologia:            () => TIPOLOGIE_PROFESSIONISTA,
      // consulenti
      ruolo:                () => RUOLI_CONSULENTE.map(r => r.nome),
      consulente:           () => REGISTRO_CONSULENTI.map(c => c.utente)
    };

    if (elenchi[chiave]) return provaSicura(elenchi[chiave]);

    // caselle di spunta e campi si/no sparsi nelle varie schede
    const siNo = ['cdv1', 'cdv2', 'cdvFatto', 'incaricoFatto', 'giaVendita', 'piuLivelli', 'piuSpazio',
                  'visuraggio', 'preliminareFatto'];
    if (siNo.indexOf(chiave) !== -1) return ['S\u00ec', 'No'];

    // colonne definite dal motore generico (Opportunity, Cdv e schede future):
    // se la colonna e' un menu, riuso le sue stesse opzioni
    for (const costruttore of ['colonneOpportunity', 'colonneCdv']) {
      const colonne = provaSicura(() => (typeof window !== 'undefined' && typeof window[costruttore] === 'function')
        ? window[costruttore]() : []);
      const trovata = colonne.find(c => c && c.chiave === chiave && Array.isArray(c.opzioni));
      if (trovata) return trovata.opzioni;
    }
    return [];
  }

  /* I valori selezionabili per una colonna: quelli previsti piu' quelli che
     esistono davvero nei dati. Cosi' non si scrive niente a mano. */
  function valoriDisponibiliColonna(chiave, dati) {
    const elenco = [];
    const aggiungi = (v) => {
      const testo = (v === null || v === undefined) ? '' : String(v).trim();
      if (testo && elenco.indexOf(testo) === -1) elenco.push(testo);
    };
    opzioniNoteColonna(chiave).forEach(aggiungi);
    (Array.isArray(dati) ? dati : []).forEach(r => aggiungi(r ? r[chiave] : ''));
    return elenco.sort((a, b) => a.localeCompare(b, 'it'));
  }

  /* Il campo del valore: menu a tendina se la colonna ha un elenco gestibile di valori,
     casella di testo quando si cerca un frammento o i valori sono troppi (titoli, indirizzi...) */
  function campoValoreFiltro(tabellaTipo, indice, filtro, nascondiValore, datiCorrenti) {
    if (nascondiValore) return '<div style="flex:1;"></div>';

    const stileBase = 'flex:1; background:#18191c; border:1px solid #3e4147; color:white; border-radius:4px; padding:6px; font-size:12px;';
    const cercaFrammento = filtro.condizione === 'contiene' || filtro.condizione === 'non-contiene';
    const valori = filtro.colonna ? valoriDisponibiliColonna(filtro.colonna, datiCorrenti) : [];

    if (!filtro.colonna || cercaFrammento || valori.length === 0 || valori.length > 80) {
      return `<input type="text" value="${(filtro.valore||'').replace(/"/g,'&quot;')}" placeholder="${filtro.colonna ? 'Valore' : 'Scegli prima la colonna'}"
        style="${stileBase}" onblur="aggiornaRigaFiltroAvanzato('${tabellaTipo}', ${indice}, 'valore', this.value)"
        onkeydown="if(event.key==='Enter'){event.preventDefault(); this.blur();}">`;
    }

    const scelto = filtro.valore || '';
    // sulla colonna consulente il valore salvato e' lo username: in elenco mostro il nome per esteso
    const etichetta = (v) => filtro.colonna === 'consulente' ? nomeConsulente(v) : v;
    const opzioni = [`<option value="">-- Scegli un valore --</option>`]
      .concat(scelto && valori.indexOf(scelto) === -1 ? [`<option value="${scelto}" selected>${etichetta(scelto)}</option>`] : [])
      .concat(valori.map(v => `<option value="${v}" ${v === scelto ? 'selected' : ''}>${etichetta(v)}</option>`))
      .join('');

    return `<select style="${stileBase}" onchange="aggiornaRigaFiltroAvanzato('${tabellaTipo}', ${indice}, 'valore', this.value)">${opzioni}</select>`;
  }

  function costruisciPannelloFiltriAvanzati(tabellaTipo, colonneRaggruppabili, colonneMeta, datiCorrenti) {
    const config = ottieniConfigVista(tabellaTipo);
    const filtri = config.filtriAvanzati || [];
    const nRisultati = applicaFiltriAvanzati(datiCorrenti, filtri).length;

    const opzioniColonna = (colonnaSelezionata) => `<option value="">Colonna</option>` + colonneRaggruppabili.map(chiave => {
      const meta = colonneMeta.find(c => c.chiave === chiave);
      return `<option value="${chiave}" ${colonnaSelezionata === chiave ? 'selected':''}>${meta ? meta.etichetta : chiave}</option>`;
    }).join('');

    const opzioniCondizione = (condizioneSelezionata) => {
      const condizioni = [['uguale','È uguale a'],['diverso','Non è uguale a'],['contiene','Contiene'],['non-contiene','Non contiene'],['vuoto','È vuoto'],['non-vuoto','Non è vuoto']];
      return condizioni.map(([valore, etichetta]) => `<option value="${valore}" ${condizioneSelezionata === valore ? 'selected':''}>${etichetta}</option>`).join('');
    };

    let righeHtml = '';
    if (filtri.length === 0) {
      righeHtml = `<div style="color:#868b98; font-size:12px; padding:10px 0;">Nessun filtro impostato. Aggiungine uno con "+ Nuovo filtro".</div>`;
    } else {
      filtri.forEach((f, indice) => {
        const nascondiValore = f.condizione === 'vuoto' || f.condizione === 'non-vuoto';
        righeHtml += `
          <div style="display:flex; gap:8px; align-items:center; margin-bottom:8px;">
            ${indice === 0
              ? `<div style="width:70px; color:#868b98; font-size:12px;">Dove</div>`
              : `<select style="width:70px; background:#18191c; border:1px solid #3e4147; color:#cbd5e1; border-radius:4px; padding:6px 4px; font-size:12px;" onchange="aggiornaRigaFiltroAvanzato('${tabellaTipo}', ${indice}, 'connettore', this.value)">
                   <option value="e" ${(f.connettore||'e') === 'e' ? 'selected':''}>e</option>
                   <option value="o" ${f.connettore === 'o' ? 'selected':''}>o</option>
                 </select>`
            }
            <select style="flex:1; background:#18191c; border:1px solid #3e4147; color:white; border-radius:4px; padding:6px; font-size:12px;" onchange="aggiornaRigaFiltroAvanzato('${tabellaTipo}', ${indice}, 'colonna', this.value)">${opzioniColonna(f.colonna)}</select>
            <select style="width:130px; background:#18191c; border:1px solid #3e4147; color:white; border-radius:4px; padding:6px; font-size:12px;" onchange="aggiornaRigaFiltroAvanzato('${tabellaTipo}', ${indice}, 'condizione', this.value)">${opzioniCondizione(f.condizione)}</select>
            ${campoValoreFiltro(tabellaTipo, indice, f, nascondiValore, datiCorrenti)}
            <span onclick="rimuoviRigaFiltroAvanzato('${tabellaTipo}', ${indice})" style="color:#868b98; cursor:pointer; padding:4px;"><i class="fa-solid fa-xmark"></i></span>
          </div>`;
      });
    }

    return `
      <div class="pannello-filtri-avanzati-overlay" style="position:absolute; top:44px; left:0; z-index:500; background:#202226; border:1px solid #3e4147; border-radius:8px; padding:18px; width:520px; box-shadow:0 10px 40px rgba(0,0,0,0.5);">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:14px;">
          <div style="color:white; font-weight:700; font-size:15px;">Filtri avanzati <span style="color:#868b98; font-weight:400; font-size:12px;">${nRisultati} risultati</span></div>
          <div style="display:flex; gap:14px; align-items:center;">
            <span onclick="cancellaTuttiFiltriAvanzati('${tabellaTipo}')" style="color:#868b98; font-size:12px; cursor:pointer;">Cancella tutto</span>
            <button onclick="toggleAperturaPannelloFiltri('${tabellaTipo}')" style="background:#292b2f; border:1px solid #3e4147; color:#cbd5e1; padding:5px 12px; border-radius:4px; cursor:pointer; font-size:12px; font-weight:600;">Chiudi</button>
          </div>
        </div>
        ${righeHtml}
        <div style="margin-top:10px;">
          <span onclick="aggiungiRigaFiltroAvanzato('${tabellaTipo}')" style="color:#0086d6; font-size:13px; font-weight:600; cursor:pointer;">+ Nuovo filtro</span>
        </div>
      </div>
    `;
  }

  function aggiungiRigaFiltroAvanzato(tabellaTipo) {
    const config = ottieniConfigVista(tabellaTipo);
    if (!config.filtriAvanzati) config.filtriAvanzati = [];
    config.filtriAvanzati.push({ connettore: 'e', colonna: '', condizione: 'uguale', valore: '' });
    ridisegnaTabellaAttiva(tabellaTipo);
  }

  function rimuoviRigaFiltroAvanzato(tabellaTipo, indice) {
    const config = ottieniConfigVista(tabellaTipo);
    config.filtriAvanzati.splice(indice, 1);
    salvaConfigVistaCorrente(tabellaTipo);
    ridisegnaTabellaAttiva(tabellaTipo);
  }

  function aggiornaRigaFiltroAvanzato(tabellaTipo, indice, campo, valore) {
    const config = ottieniConfigVista(tabellaTipo);
    config.filtriAvanzati[indice][campo] = valore;
    if (campo === 'condizione' && (valore === 'vuoto' || valore === 'non-vuoto')) config.filtriAvanzati[indice].valore = '';
    salvaConfigVistaCorrente(tabellaTipo);
    ridisegnaTabellaAttiva(tabellaTipo);
  }

  function cancellaTuttiFiltriAvanzati(tabellaTipo) {
    const config = ottieniConfigVista(tabellaTipo);
    config.filtriAvanzati = [];
    salvaConfigVistaCorrente(tabellaTipo);
    ridisegnaTabellaAttiva(tabellaTipo);
  }

  function valutaCondizioneFiltroAvanzato(valoreRiga, condizione, valoreFiltro) {
    const v = (valoreRiga === undefined || valoreRiga === null ? '' : valoreRiga).toString().toLowerCase();
    const f = (valoreFiltro || '').toString().toLowerCase();
    switch (condizione) {
      case 'uguale': return v === f;
      case 'diverso': return v !== f;
      case 'contiene': return f !== '' && v.includes(f);
      case 'non-contiene': return f === '' || !v.includes(f);
      case 'vuoto': return v === '';
      case 'non-vuoto': return v !== '';
      default: return true;
    }
  }

  function applicaFiltriAvanzati(dati, filtriAvanzati) {
    const filtriValidi = (filtriAvanzati || []).filter(f => f.colonna);
    if (filtriValidi.length === 0) return dati;
    return dati.filter(riga => {
      let risultato = null;
      filtriValidi.forEach((f, indice) => {
        const esito = valutaCondizioneFiltroAvanzato(riga[f.colonna], f.condizione, f.valore);
        if (indice === 0) risultato = esito;
        else if (f.connettore === 'o') risultato = risultato || esito;
        else risultato = risultato && esito;
      });
      return risultato === null ? true : risultato;
    });
  }

  function costruisciSubitemRichiesteVisioni(incarico, colspanTotale) {
    const richieste = REGISTRO_BANCA_DATI_CLOUD.filter(bd => bd.immobileFonteRichiesta === incarico.idElemento);
    const visioni = REGISTRO_VISIONI_ADV_CLOUD.filter(v => v.incaricoUfficio === incarico.idElemento);
    const coloreStato = { 'Da Fix': { bg:'#ffffff', col:'#18191c' }, 'In Attesa': { bg:'rgba(226,177,60,0.2)', col:'#e2b13c' }, 'Fissato': { bg:'rgba(0,200,117,0.2)', col:'#00c875' }, 'Non Interessa': { bg:'rgba(244,63,94,0.2)', col:'#f43f5e' }, 'Venduto / Non Disponibile': { bg:'rgba(134,139,152,0.2)', col:'#868b98' } };
    const coloreFeedback = { 'Interessa': { bg:'rgba(0,200,117,0.2)', col:'#00c875' }, 'Valuta': { bg:'rgba(226,177,60,0.2)', col:'#e2b13c' }, 'Non Interessa': { bg:'rgba(244,63,94,0.2)', col:'#f43f5e' } };

    const tabellaRichieste = `
      <div style="margin-bottom:14px;">
        <div style="color:#e2b13c; font-weight:700; font-size:12px; text-transform:uppercase; margin-bottom:6px;"><i class="fa-solid fa-database"></i> Richieste (${richieste.length})</div>
        <table class="monday-sub-table" style="margin:0;">
          <thead><tr>
            <th class="valore-specchio">Nome Cognome</th><th class="valore-specchio">Telefono</th><th class="valore-specchio">Mail</th><th class="valore-specchio">Stato ADV FIX</th>
          </tr></thead>
          <tbody>
            ${richieste.length === 0 ? `<tr><td colspan="4" style="color:#64748b; text-align:center; padding:8px;">Nessuna richiesta collegata</td></tr>` : richieste.map(bd => {
              const c = coloreStato[bd.statoAdvFix] || coloreStato['Da Fix'];
              return `<tr><td>${bd.nomeCognome || ''}</td><td>${bd.telefono || ''}</td><td>${bd.mail || ''}</td><td><span style="background:${c.bg}; color:${c.col}; padding:2px 8px; border-radius:4px; font-weight:700;">${bd.statoAdvFix || '-'}</span></td></tr>`;
            }).join('')}
          </tbody>
        </table>
      </div>
      <div>
        <div style="color:#a855f7; font-weight:700; font-size:12px; text-transform:uppercase; margin-bottom:6px;"><i class="fa-solid fa-eye"></i> Visioni (${visioni.length})</div>
        <table class="monday-sub-table" style="margin:0;">
          <thead><tr>
            <th class="valore-specchio">Nome & Cognome</th><th class="valore-specchio">Numero di Telefono</th><th class="valore-specchio">Mail</th><th class="valore-specchio">Incarico Ufficio</th><th class="valore-specchio">Feedback ADV</th><th class="valore-specchio">Testo Feedback</th><th class="valore-specchio">Valore Percepito</th>
          </tr></thead>
          <tbody>
            ${visioni.length === 0 ? `<tr><td colspan="7" style="color:#64748b; text-align:center; padding:8px;">Nessuna visione collegata</td></tr>` : visioni.map(v => {
              const c = coloreFeedback[v.feedbackAdv] || { bg:'#ffffff', col:'#18191c' };
              return `<tr><td>${v.nomeCognome || ''}</td><td>${v.telefono || ''}</td><td>${v.mail || ''}</td><td>${v.incaricoUfficio || ''}</td><td><span style="background:${c.bg}; color:${c.col}; padding:2px 8px; border-radius:4px; font-weight:700;">${v.feedbackAdv || '-'}</span></td><td>${v.testoFeedback || ''}</td><td>${v.valorePercepito || ''}</td></tr>`;
            }).join('')}
          </tbody>
        </table>
      </div>`;

    const subitemId = `subitem-incarico-${incarico._id}`;
    const chiusa = !NODI_APERTI_MEMORIA.has(subitemId);
    return `<tr id="${subitemId}" style="${chiusa ? 'display:none;' : 'display:table-row;'} background:#14161a;"><td colspan="${colspanTotale}" style="padding:10px 25px;">${tabellaRichieste}</td></tr>`;
  }

  // Spese condominiali: Sì/No; se non è "Sì" azzero il costo annuo
  async function aggiornaSpeseCond(id, valore) {
    const r = REGISTRO_INCARICHI_CLOUD.find(x => x._id === id);
    if (r) { r.haSpeseCondominiali = valore; if (valore !== 'si') r.speseCondominiali = ''; }
    try {
      await fetch(`${API_INCARICHI}/${id}`, {
        method: 'PUT', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ haSpeseCondominiali: valore, speseCondominiali: (valore === 'si' && r ? (r.speseCondominiali || '') : '') })
      });
    } catch (e) {}
    if (AREA_LAVORO_ATTIVA === 'inc-pure') ridisegnaIncarichiMantieniScroll();
  }

  // Colonna Documenti: % di completamento della checklist (quanti hanno link/sono presenti). Clic = apri Gestione Documenti.
  function cellaDocumentiCompletamento(r) {
    const docs = (r.gestioneDocumenti && r.gestioneDocumenti.documenti) || {};
    // escludo i "Non richiesto" (rosso): contano solo i documenti che servono davvero
    const rilevanti = DOC_VENDITORE.filter(d => ((docs[d.k] || {}).stato || 'rosso') !== 'rosso');
    const recuperato = (v) => v.stato === 'verde' || (v.allegato && String(v.allegato).trim()) || (v.stato === 'comune' && v.accessoStato === 'rilasciato');
    const tot = rilevanti.length;
    if (!tot) return `<td onclick="apriPopupGestioneDocumenti('${r._id}')" style="cursor:pointer; color:#5f6672; font-size:12px;" title="Apri Gestione Documenti">— <span style="font-size:10.5px;">nessuno avviato</span></td>`;
    const fatti = rilevanti.filter(d => recuperato(docs[d.k] || {})).length;
    const perc = Math.round(fatti / tot * 100);
    const col = perc === 100 ? '#00c875' : (perc >= 50 ? '#e2b13c' : '#f43f5e');
    return `<td onclick="apriPopupGestioneDocumenti('${r._id}')" style="cursor:pointer;" title="Apri Gestione Documenti">
      <div style="display:flex; align-items:center; gap:8px;">
        <div style="flex:1; height:7px; background:#2a2c31; border-radius:4px; overflow:hidden; min-width:46px;"><div style="height:100%; width:${perc}%; background:${col};"></div></div>
        <span style="color:${col}; font-weight:800; font-size:12px; white-space:nowrap;">${perc}%</span>
      </div>
      <div style="color:#5f6672; font-size:10.5px; margin-top:3px;">${fatti}/${tot} recuperati</div></td>`;
  }

  // Colonna Accesso Atti: stato preso dai documenti "al Comune" (agibilità, titoli edilizi).
  function cellaAccessoAttiStato(r) {
    const docs = (r.gestioneDocumenti && r.gestioneDocumenti.documenti) || {};
    const attivi = DOC_VENDITORE.filter(d => d.comune && (docs[d.k] || {}).stato === 'comune');
    if (!attivi.length) return `<td onclick="apriPopupGestioneDocumenti('${r._id}')" style="cursor:pointer; color:#5f6672; font-size:12px;" title="Apri Gestione Documenti">—</td>`;
    const statoDi = (v) => { v = v || {}; if (v.accessoStato === 'rilasciato' || v.dataRilascio) return 'completato'; if (v.accessoStato === 'presentata' || v.dataPresentazione) return 'richiesto'; return 'da-presentare'; };
    const stati = attivi.map(d => statoDi(docs[d.k]));
    let testo, col;
    if (stati.every(s => s === 'completato')) { testo = 'Completato'; col = '#00c875'; }
    else if (stati.some(s => s === 'richiesto' || s === 'completato')) { testo = 'Richiesto'; col = '#e2b13c'; }
    else { testo = 'Da presentare'; col = '#8792a0'; }
    const nComp = stati.filter(s => s === 'completato').length;
    return `<td onclick="apriPopupGestioneDocumenti('${r._id}')" style="cursor:pointer;" title="Apri Gestione Documenti">
      <span style="color:${col}; font-weight:700; font-size:12px;">${testo}</span>
      ${attivi.length > 1 ? `<div style="color:#5f6672; font-size:10.5px; margin-top:2px;">${nComp}/${attivi.length} rilasciati</div>` : ''}</td>`;
  }

  // Classe APE: al cambio salvo e ridisegno per aggiornare la fascia IPE mostrata
  async function aggiornaClasseApe(id, valore) {
    const r = REGISTRO_INCARICHI_CLOUD.find(x => x._id === id);
    if (r) r.classeApe = valore;
    try { await fetch(`${API_INCARICHI}/${id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ campo: 'classeApe', valore }) }); } catch (e) {}
    if (AREA_LAVORO_ATTIVA === 'inc-pure') ridisegnaIncarichiMantieniScroll();
  }

  // Statistiche portali: una sola colonna, il dettaglio si apre in un popup
  function cellaStatistichePortali(r) {
    const v = r.viste || {};
    const tot = (parseInt(v.immVis) || 0) + (parseInt(v.ideVis) || 0) + (parseInt(v.forteVis) || 0);
    return `<td><button onclick="apriPopupStatistiche('${r._id}')" class="btn-new-element"
      style="background:#0B3B4A; border:1px solid #C6A777; color:#C6A777; padding:6px 12px; font-size:11.5px; white-space:nowrap;">
      <i class="fa-solid fa-chart-simple" style="margin-right:6px;"></i>${tot ? tot + ' viste' : 'Statistiche'}</button></td>`;
  }

  function apriPopupStatistiche(id) {
    const r = REGISTRO_INCARICHI_CLOUD.find(x => x._id === id);
    if (!r) return;
    const v = r.viste || {};
    let box = document.getElementById('popup-statistiche');
    if (!box) { box = document.createElement('div'); box.id = 'popup-statistiche'; document.body.appendChild(box); }
    box.style.cssText = 'position:fixed; inset:0; z-index:100050; background:rgba(0,0,0,.7); display:flex; align-items:center; justify-content:center; padding:16px;';
    const campo = (idc, et, val) => `<div style="display:flex; justify-content:space-between; align-items:center; gap:12px; padding:9px 0; border-bottom:1px solid #2f3136;"><label style="color:#cbd5e1; font-size:13px;">${et}</label><input type="number" id="${idc}" value="${val || ''}" style="width:110px; padding:7px 9px; background:#18191c; border:1px solid #3e4147; color:#fff; border-radius:6px; font-size:13px;"></div>`;
    box.innerHTML = `
      <div style="width:100%; max-width:440px; background:#202226; border:1px solid #3e4147; border-radius:14px; overflow:hidden;">
        <div style="padding:18px 22px; border-bottom:1px solid #2f3136; display:flex; justify-content:space-between; align-items:center;">
          <div style="color:#fff; font-weight:800; font-size:16px;"><i class="fa-solid fa-chart-simple" style="color:#C6A777; margin-right:8px;"></i>Statistiche portali</div>
          <button onclick="chiudiPopupStatistiche()" style="background:none; border:1px solid #3e4147; color:#8b98a5; width:30px; height:30px; border-radius:8px; cursor:pointer; font-size:14px;">&times;</button>
        </div>
        <div style="padding:16px 22px;">
          <div style="color:#C6A777; font-size:11px; text-transform:uppercase; letter-spacing:.5px; font-weight:700; margin-bottom:4px;">Visualizzazioni</div>
          ${campo('st-immVis', 'Immobiliare.it', v.immVis)}
          ${campo('st-ideVis', 'Idealista', v.ideVis)}
          ${campo('st-forteVis', 'Sito Forte', v.forteVis)}
          <div style="color:#C6A777; font-size:11px; text-transform:uppercase; letter-spacing:.5px; font-weight:700; margin:16px 0 4px;">Solo Immobiliare.it</div>
          ${campo('st-immPref', 'Preferiti', v.immPref)}
          ${campo('st-immNasc', 'Nascosti', v.immNasc)}
          <div style="color:#C6A777; font-size:11px; text-transform:uppercase; letter-spacing:.5px; font-weight:700; margin:16px 0 4px;">Altro</div>
          ${campo('st-contatti', 'Contatti ricevuti', v.contatti)}
          <button onclick="salvaStatistiche('${id}')" style="width:100%; margin-top:16px; background:#00c875; border:none; color:#08221a; padding:12px; border-radius:9px; font-weight:800; cursor:pointer; font-family:inherit;">Salva</button>
          ${v.aggiornatoIl ? `<div style="color:#5f6672; font-size:11px; text-align:center; margin-top:8px;">Ultimo aggiornamento: ${(v.aggiornatoIl || '').split('-').reverse().join('/')}</div>` : ''}
        </div>
      </div>`;
  }

  function chiudiPopupStatistiche() { const b = document.getElementById('popup-statistiche'); if (b) b.remove(); }

  async function salvaStatistiche(id) {
    const g = (x) => (document.getElementById(x) || {}).value || '';
    const viste = {
      immVis: g('st-immVis'), ideVis: g('st-ideVis'), forteVis: g('st-forteVis'),
      immPref: g('st-immPref'), immNasc: g('st-immNasc'), contatti: g('st-contatti'),
      aggiornatoIl: new Date().toISOString().slice(0, 10)
    };
    const r = REGISTRO_INCARICHI_CLOUD.find(x => x._id === id); if (r) r.viste = viste;
    try {
      await fetch(`${API_INCARICHI}/${id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ campo: 'viste', valore: viste }) });
    } catch (e) {}
    chiudiPopupStatistiche();
    if (AREA_LAVORO_ATTIVA === 'inc-pure') ridisegnaIncarichiMantieniScroll();
  }

  // Tondino con la foto del consulente della riga (o iniziali se manca la foto). Va prima del nome.
  function tondinoConsulenteIncarico(r) {
    const ut = consulenteDelRecord(r);
    const c = ut ? REGISTRO_CONSULENTI.find(x => x.utente === ut) : null;
    const nome = c ? (c.nomeCognome || '') : '';
    const foto = c && c.fotoProfilo ? c.fotoProfilo : '';
    const base = 'width:26px; height:26px; border-radius:50%; flex-shrink:0; display:inline-flex; align-items:center; justify-content:center; overflow:hidden;';
    if (foto) return `<span title="${(nome || '').replace(/"/g, '&quot;')}" style="${base} border:2px solid #C6A777;"><img src="${foto}" referrerpolicy="no-referrer" style="width:100%; height:100%; object-fit:cover; display:block;"></span>`;
    const iniz = nome ? nome.split(/\s+/).map(w => w[0]).slice(0, 2).join('').toUpperCase() : '';
    return `<span title="${nome || 'Non assegnato'}" style="${base} background:#2a2c31; border:2px solid #3e4147; color:#8792a0; font-size:10px; font-weight:800;">${iniz || '?'}</span>`;
  }

  function costruisciCellaIncarico(r, chiave) {
    switch(chiave) {
      case 'nome': {
        const numFoto = (r.fotoAllegati || []).length;
        const numAltri = [r.linkVideo, r.linkVirtualTour, r.linkDocumenti].filter(x => x).length;
        const numTotale = numFoto + numAltri;
        const numRichieste = REGISTRO_BANCA_DATI_CLOUD.filter(bd => bd.immobileFonteRichiesta === r.idElemento).length;
        const numVisioni = REGISTRO_VISIONI_ADV_CLOUD.filter(v => v.incaricoUfficio === r.idElemento).length;
        const numCollegati = numRichieste + numVisioni;
        const subitemId = `subitem-incarico-${r._id}`;
        return `<td><div style="display:flex; align-items:center; gap:6px;">
          <input type="checkbox" ${INCARICHI_SELEZIONATI.has(r._id) ? 'checked' : ''} onclick="event.stopPropagation(); toggleSelezioneIncarico('${r._id}', this)" title="Seleziona la riga" style="width:15px; height:15px; accent-color:#C6A777; cursor:pointer; flex-shrink:0;">
          ${tondinoConsulenteIncarico(r)}
          <input type="text" class="input-cella-stradario" value="${r.nome || ''}" onchange="aggiornaCampoIncarico('${r._id}', 'nome', this.value)">
          <span style="position:relative; cursor:pointer; flex-shrink:0;" onclick="apriPopupFotoIncarico('${r._id}')" title="Gestisci allegati (${numTotale})">
            <i class="fa-solid fa-paperclip" style="color:${numTotale > 0 ? '#38bdf8' : '#3e4147'};"></i>
            ${numTotale > 0 ? `<span style="position:absolute; top:-9px; right:-11px; background:#38bdf8; color:#18191c; font-size:9px; font-weight:700; border-radius:8px; padding:1px 4px; min-width:14px; text-align:center; line-height:1.3;">${numTotale}</span>` : ''}
          </span>
          <span style="position:relative; cursor:pointer; flex-shrink:0;" onclick="toggleLivelloAlbero(event, '${subitemId}')" title="Richieste e Visioni collegate (${numCollegati})">
            <i class="fa-solid fa-users" style="color:${numCollegati > 0 ? '#e2b13c' : '#3e4147'};"></i>
            ${numCollegati > 0 ? `<span style="position:absolute; top:-9px; right:-11px; background:#e2b13c; color:#18191c; font-size:9px; font-weight:700; border-radius:8px; padding:1px 4px; min-width:14px; text-align:center; line-height:1.3;">${numCollegati}</span>` : ''}
          </span>
          <span style="cursor:pointer; flex-shrink:0;" onclick="apriPopupGestioneDocumenti('${r._id}')" title="Gestione Documenti e Pubblicazione">
            <i class="fa-solid fa-clipboard-list" style="color:#a855f7;"></i>
          </span>
          <span style="cursor:pointer; flex-shrink:0;" onclick="creaVolantinoImmobile('${r._id}')" title="Crea Volantino (fronte + retro)">
            <i class="fa-solid fa-rectangle-ad" style="color:#C6A777;"></i>
          </span>
        </div></td>`;
      }
      case 'idElemento': return `<td><code>${r.idElemento || '-'}</code></td>`;
      case 'statoImmobile': {
        // stessi colori delle vecchie tendine/gruppi (COLORI_TENDINA_INCARICO)
        const infoS = COLORI_TENDINA_INCARICO[r.statoImmobile] || { bg: '#3a3d44', t: '#cbd5e1' };
        const statiElenco = Object.keys(COLORI_TENDINA_INCARICO);
        if (r.statoImmobile && statiElenco.indexOf(r.statoImmobile) === -1) statiElenco.push(r.statoImmobile);
        const opzioniStato = statiElenco.map(s => `<option value="${s}" ${r.statoImmobile === s ? 'selected' : ''}>${s}</option>`).join('');
        return `<td><select class="select-cella-stradario" style="background:${infoS.bg}; color:${infoS.t}; border:1px solid rgba(0,0,0,.25); font-weight:700;" onchange="aggiornaCampoIncarico('${r._id}', 'statoImmobile', this.value)"><option value="">--</option>${opzioniStato}</select></td>`;
      }
      case 'posizione': return `<td><input type="text" class="input-cella-stradario" placeholder="es. Via Roma 12, Legnano" value="${r.posizione || ''}" onchange="aggiornaCampoIncarico('${r._id}', 'posizione', this.value)"></td>`;
      case 'mappa': {
        let indirizzoCompleto = r.posizione || `${r.via || ''} ${r.civico || ''}, ${r.comune || ''}`.trim();
        return `<td style="text-align:center;">${indirizzoCompleto ? `<button onclick="apriGoogleMaps('${indirizzoCompleto.replace(/'/g, "\\'")}')" style="background:none; border:none; color:#0086d6; cursor:pointer; font-size:16px;" title="Apri in Google Maps"><i class="fa-solid fa-map-location-dot"></i></button>` : `<span style="color:#64748b; font-size:12px;">-</span>`}</td>`;
      }
      case 'contesto': {
        let opzioniContesto = `<option value="">--</option>` + OPZIONI_CONTESTO_INCARICO.map(o => `<option value="${o}" ${r.contesto === o ? 'selected':''}>${o}</option>`).join('');
        return `<td><select class="select-cella-stradario" onchange="aggiornaCampoIncarico('${r._id}', 'contesto', this.value)">${opzioniContesto}</select></td>`;
      }
      case 'tipologiaUnita': {
        let opzioniTipologia = `<option value="">--</option>` + OPZIONI_TIPOLOGIA_INCARICO.map(o => `<option value="${o}" ${r.tipologiaUnita === o ? 'selected':''}>${o}</option>`).join('');
        return `<td><select class="select-cella-stradario" onchange="aggiornaCampoIncarico('${r._id}', 'tipologiaUnita', this.value)">${opzioniTipologia}</select></td>`;
      }
      case 'locali': return `<td><input type="number" class="input-cella-stradario" value="${r.locali || ''}" onchange="aggiornaCampoIncarico('${r._id}', 'locali', this.value)"></td>`;
      case 'mq': return `<td><input type="number" class="input-cella-stradario" value="${r.mq || ''}" onchange="aggiornaCampoIncarico('${r._id}', 'mq', this.value)"></td>`;
      case 'boxMq': return `<td><input type="number" min="0" class="input-cella-stradario" placeholder="m² box" value="${r.boxMq || ''}" onchange="aggiornaCampoIncarico('${r._id}', 'boxMq', this.value)"></td>`;
      case 'prezzoIncarico': return `<td><div style="display:flex; align-items:center; gap:3px;"><input type="number" class="input-cella-stradario" style="flex:1; min-width:0;" value="${r.prezzoIncarico || ''}" onchange="aggiornaCampoIncarico('${r._id}', 'prezzoIncarico', this.value)"><span style="color:#00c875; font-weight:700;">€</span></div></td>`;
      case 'consulente': return cellaConsulente('incarichi', r);
      case 'provvigioneVenditore': {
        const _pz = Number(String(r.prezzoIncarico || '').replace(/[^\d]/g, '')) || 0;
        const _q4 = _pz ? Math.round(_pz * 0.04) : 0;
        return `<td><div style="display:flex; align-items:center; gap:3px;"><input type="text" class="input-cella-stradario" style="flex:1; min-width:0;" placeholder="es. 10000 oppure 3%" value="${r.provvigioneVenditore || ''}" onchange="aggiornaCampoIncarico('${r._id}', 'provvigioneVenditore', this.value)"><span style="color:#e2b13c; font-weight:700;">€</span></div>${_q4 ? `<div style="color:#8792a0; font-size:10.5px; margin-top:3px;" title="4% del prezzo, per confronto">4% = € ${_q4.toLocaleString('it-IT')}</div>` : ''}</td>`;
      }
      case 'provvigioneAcquirente': {
        const _pz = Number(String(r.prezzoIncarico || '').replace(/[^\d]/g, '')) || 0;
        const _q4 = _pz ? Math.round(_pz * 0.04) : 0;
        return `<td>${_q4 ? `<span style="color:#00c875; font-weight:700;">€ ${_q4.toLocaleString('it-IT')}</span><div style="color:#8792a0; font-size:10.5px;">proiezione 4%</div>` : '<span style="color:#5f6672;">—</span>'}</td>`;
      }
      case 'tipologiaContratto': {
        const stileTC = r.tipologiaContratto === 'Vendita' ? 'background:rgba(0,200,117,0.15); color:#00c875;' : (r.tipologiaContratto === 'Affitto' ? 'background:rgba(226,177,60,0.15); color:#e2b13c;' : '');
        return `<td><select class="select-cella-stradario" style="${stileTC}" onchange="aggiornaCampoIncarico('${r._id}', 'tipologiaContratto', this.value)"><option value="">--</option><option value="Vendita" ${r.tipologiaContratto === 'Vendita' ? 'selected':''}>Vendita</option><option value="Affitto" ${r.tipologiaContratto === 'Affitto' ? 'selected':''}>Affitto</option></select></td>`;
      }
      case 'dataIncarico': return `<td><input type="date" class="input-cella-stradario" value="${normalizzaValoreDataInput(r.dataIncarico)}" onchange="aggiornaCampoIncarico('${r._id}', 'dataIncarico', this.value)"></td>`;
      case 'dataScadenza': return `<td><input type="date" class="input-cella-stradario" value="${normalizzaValoreDataInput(r.dataScadenza)}" onchange="aggiornaCampoIncarico('${r._id}', 'dataScadenza', this.value)"></td>`;
      case 'catasto': return cellaCatasto(r);
      case 'openHouse': return cellaOpenHouse(r);
      case 'dataPubblicazione':
        return `<td><input type="date" class="input-cella-stradario" value="${normalizzaValoreDataInput(r[chiave])}"
                onchange="aggiornaCampoIncarico('${r._id}', '${chiave}', this.value)"></td>`;
      case 'dataDocumenti': return cellaDocumentiCompletamento(r);
      case 'dataAccessoAtti': return cellaAccessoAttiStato(r);
      case 'statistiche': return cellaStatistichePortali(r);
      case 'immobiliareIt': case 'idealista': case 'wikicasa':
        return cellaPortaleIncarico(r, chiave);
      case 'report':
        return `<td><button onclick="generaReportIncarico('${r._id}')" class="btn-new-element"
                  style="background:#0B3B4A; border:1px solid #C6A777; color:#C6A777; padding:6px 12px; font-size:11.5px; white-space:nowrap;">
                  <i class="fa-solid fa-file-lines" style="margin-right:6px;"></i>Report</button></td>`;
      case 'giorniRimasti': { let g = calcolaGiorniScadenza(r.dataScadenza); return `<td><span style="color:${g.colore}; font-weight:700; font-size:12px;">${g.testo}</span></td>`; }
      case 'teamLeader': {
        const opzioniTL = `<option value="">-- Nessuno --</option>` + REGISTRO_CONSULENTI.map(c => `<option value="${c.nomeCognome}" ${r.teamLeader === c.nomeCognome ? 'selected':''}>${c.nomeCognome}</option>`).join('');
        return `<td><select class="select-cella-stradario" onchange="aggiornaCampoIncarico('${r._id}', 'teamLeader', this.value)">${opzioniTL}</select></td>`;
      }
      case 'listing': {
        const opzioniListing = `<option value="">-- Nessuno --</option>` + REGISTRO_CONSULENTI.map(c => `<option value="${c.nomeCognome}" ${r.listing === c.nomeCognome ? 'selected':''}>${c.nomeCognome}</option>`).join('');
        return `<td><select class="select-cella-stradario" style="color:#e2b13c; font-weight:700;" onchange="aggiornaCampoIncarico('${r._id}', 'listing', this.value)">${opzioniListing}</select></td>`;
      }
      /* A specchio dalla scheda del consulente scelto come listing: non si
         modifica qui, e se manca lo si vede subito invece di scoprirlo da un
         messaggio che non arriva. */
      case 'idTelegramListing': {
        const suaCasella = trovaCampoConsulente(r.listing, 'idTelegram');
        if (!r.listing) {
          return `<td style="color:#5f6672; font-size:11.5px;">nessun listing</td>`;
        }
        return `<td title="Si mette dalla scheda del consulente">${
          suaCasella
            ? `<span style="color:#7fc99a; font-size:11.5px;">${propEsc(suaCasella)}</span>`
            : `<span style="color:#e8a0ad; font-size:11.5px;">manca</span>`
        }</td>`;
      }
      case 'buyer': {
        const opzioniBuyer = `<option value="">-- Nessuno --</option>` + REGISTRO_CONSULENTI.map(c => `<option value="${c.nomeCognome}" ${r.buyer === c.nomeCognome ? 'selected':''}>${c.nomeCognome}</option>`).join('');
        return `<td><select class="select-cella-stradario" onchange="aggiornaCampoIncarico('${r._id}', 'buyer', this.value)">${opzioniBuyer}</select></td>`;
      }
      case 'nomeVenditore': {
        let opzioniVenditore = `<option value="">-- Nessuno --</option>` + DATA_CAPITALE_SOCIALE.map(p => `<option value="${p.nome}" ${r.nomeVenditore === p.nome ? 'selected':''}>${p.nome}</option>`).join('') + `<option value="__nuovo__">+ Nuovo Venditore...</option>`;
        return `<td><select class="select-cella-stradario" style="border-color:#a855f7;" onchange="gestisciCambioVenditore('${r._id}', this.value)">${opzioniVenditore}</select></td>`;
      }
            case 'telefonoVenditore':
        return cellaTelefono(r.telefonoVenditore, `aggiornaCampoIncarico('${r._id}', 'telefonoVenditore', this.value)`);
      /* campi che finiscono nella scheda pubblica dell'immobile (/immobili) */
      case 'bagni':
        return `<td><input type="number" min="0" class="input-cella-stradario" value="${r.bagni || ''}" onchange="aggiornaCampoIncarico('${r._id}', 'bagni', this.value)"></td>`;
      case 'piano':
        return `<td><input type="text" class="input-cella-stradario" placeholder="es. 2 / Terra" value="${(r.piano || '').replace(/"/g,'&quot;')}" onchange="aggiornaCampoIncarico('${r._id}', 'piano', this.value)"></td>`;
      case 'classeApe': {
        const classiApe = ['', 'A4', 'A3', 'A2', 'A1', 'A', 'B', 'C', 'D', 'E', 'F', 'G', 'In corso', 'Esente'];
        const fascia = FASCE_IPE[r.classeApe] || '';
        return `<td>
          <select class="select-cella-stradario" onchange="aggiornaClasseApe('${r._id}', this.value)">${classiApe.map(c => `<option value="${c}" ${(r.classeApe || '') === c ? 'selected' : ''}>${c || '—'}</option>`).join('')}</select>
          <div style="margin-top:5px;">
            <input type="number" class="input-cella-stradario" placeholder="IPE kWh/m²a" value="${r.ipeApe || ''}" onchange="aggiornaCampoIncarico('${r._id}', 'ipeApe', this.value)">
            ${fascia ? `<div style="color:#8792a0; font-size:10px; margin-top:2px;" title="Fascia indicativa della classe">fascia ${fascia}</div>` : ''}
          </div></td>`;
      }
      case 'speseCondominiali': {
        const ha = r.haSpeseCondominiali || (r.speseCondominiali ? 'si' : '');
        return `<td>
          <select class="select-cella-stradario" onchange="aggiornaSpeseCond('${r._id}', this.value)">
            <option value="" ${ha === '' ? 'selected' : ''}>—</option>
            <option value="si" ${ha === 'si' ? 'selected' : ''}>Sì</option>
            <option value="no" ${ha === 'no' ? 'selected' : ''}>No</option>
          </select>
          <div style="${ha === 'si' ? '' : 'display:none;'} margin-top:5px;">
            <input type="text" class="input-cella-stradario" placeholder="€/anno" value="${(r.speseCondominiali || '').replace(/"/g,'&quot;')}" onchange="aggiornaCampoIncarico('${r._id}', 'speseCondominiali', this.value)">
          </div></td>`;
      }
      default: return `<td>-</td>`;
    }
  }

  function disegnaTabellaIncarichiCloud() {
    const container = document.getElementById("monday-tables-container");
    const config = ottieniConfigVista('incarichi');

    let dati = filtraScheda('incarichi', REGISTRO_INCARICHI_CLOUD).slice();
    if (config.filtroPersona) {
      dati = dati.filter(r => [r.teamLeader, r.listing, r.buyer].includes(config.filtroPersona));
    }
    if (FILTRO_STATO_INC) dati = dati.filter(r => (r.statoImmobile || '') === FILTRO_STATO_INC);
    dati = applicaFiltriAvanzati(dati, config.filtriAvanzati);
    dati = ordinaDati(dati, config.ordinamento);
    // se non è stato scelto un ordinamento a mano, ordino alfabeticamente per nome
    if (!config.ordinamento) dati.sort((a, b) => String(a.nome || '').localeCompare(String(b.nome || ''), 'it'));

    const eAdmin = utenteEBroker();
    const impostazioniAdmin = IMPOSTAZIONI_COLONNE_CACHE['incarichi'] || { colonneNascosteConsulenti: [] };
    const colonneVisibili = COLONNE_INCARICHI.filter(c => {
      if (config.colonneNascoste.has(c.chiave)) return false;
      if (!eAdmin && (impostazioniAdmin.colonneNascosteConsulenti || []).includes(c.chiave)) return false;
      return true;
    });
    const larghezzeIncarichi = LARGHEZZE_COLONNE['incarichi'] || {};
    const LARGHEZZE_DEFAULT_INCARICHI = {
      nome: 200, idElemento: 75, statoImmobile: 130, posizione: 260, mappa: 55,
      contesto: 120, tipologiaUnita: 150, locali: 70, mq: 75, bagni: 70, piano: 95, classeApe: 120, speseCondominiali: 120, prezzoIncarico: 120, tipologiaContratto: 100,
      dataIncarico: 135, dataScadenza: 135, giorniRimasti: 115, teamLeader: 150, listing: 150, buyer: 150,
      nomeVenditore: 170, telefonoVenditore: 170
    };
    const larghezzaColonna = (chiave) => larghezzeIncarichi[chiave] || LARGHEZZE_DEFAULT_INCARICHI[chiave] || 130;

    let html = renderizzaFiltriPeriodo('incarichi', dati.length, REGISTRO_INCARICHI_CLOUD.length, REGISTRO_INCARICHI_CLOUD);
    html += renderizzaBarraViste('incarichi', COLONNE_INCARICHI, COLONNE_RAGGRUPPABILI_INCARICHI, dati);

    const costruisciTabellaRighe = (elenco, cHead, tHead) => {
      // header e sfondo prendono il colore della cartella (gruppo). Senza colore (vista non raggruppata) resta lo scuro standard.
      const bgHead = cHead || '#292c33';
      const txtHead = tHead || '#a1a8b3';
      const bgTable = cHead ? ' background:rgba(22,24,28,.82);' : '';
      let t = `<table class="monday-table-centralino" style="table-layout:fixed; width:max-content; min-width:100%; overflow:visible;${bgTable}"><thead><tr>`;
      colonneVisibili.forEach((c, ci) => {
        // la prima colonna (Nome) resta bloccata a sinistra quando si scorre in orizzontale
        const freeze = ci === 0 ? ' left:0; z-index:7; border-right:2px solid #3a3d44;' : '';
        let th = `<th style="position:sticky; top:0; z-index:6;${freeze} background:${bgHead}; color:${txtHead}; overflow:visible;"><span class="th-etichetta-cliccabile" style="color:${txtHead};" onclick="apriMenuColonna(event, 'incarichi', '${c.chiave}', '${c.etichetta.replace(/'/g,"\\'")}')">${c.etichetta}</span> <i class="fa-solid ${iconaOrdinamento('incarichi', c.chiave)}" style="cursor:pointer; font-size:11px; color:${txtHead}; opacity:.7;" title="Ordina per questa colonna" onclick="event.stopPropagation(); alternaOrdinamento('incarichi', '${c.chiave}')"></i><span class="resize-handle-colonna" onmousedown="iniziaRidimensionamento(event, 'incarichi', '${c.chiave}')"></span></th>`;
        t += decorareCellaColonna(th, c.chiave, larghezzaColonna(c.chiave));
      });
      t += `<th style="position:sticky; top:0; z-index:6; background:${bgHead};"></th></tr></thead><tbody>`;
      if (elenco.length === 0) {
        t += `<tr><td colspan="${colonneVisibili.length + 1}" style="text-align:center; padding:20px; color:#868b98;">Nessun incarico in questo gruppo.</td></tr>`;
      } else {
        elenco.forEach(r => {
          t += INCARICHI_SELEZIONATI.has(r._id) ? `<tr style="background:rgba(198,167,119,.14);">` : `<tr>`;
          colonneVisibili.forEach(c => t += decorareCellaColonna(costruisciCellaIncarico(r, c.chiave), c.chiave, larghezzaColonna(c.chiave)));
          t += `<td><button class="btn-cestino-riga" onclick="eliminaIncaricoCloud('${r._id}', '${(r.nome||'').replace(/'/g,"\\'")}')"><i class="fa-solid fa-trash-can"></i></button></td></tr>`;
          t += costruisciSubitemRichiesteVisioni(r, colonneVisibili.length + 1);
        });
      }
      t += `</tbody></table>`;
      return t;
    };

    if (dati.length === 0 && REGISTRO_INCARICHI_CLOUD.length === 0) {
      html += `<p style="text-align:center; padding:30px; color:#868b98;">Nessun incarico presente. Usa "Carica file XLSX" per importare un export, o "Inserisci a mano".</p>`;
    } else if (!config.raggruppaPer) {
      html += '<div class="scroll-incarichi" style="max-height:72vh; overflow:auto; max-width:100%; box-sizing:border-box;">' + costruisciTabellaRighe(dati) + '</div>';
    } else {
      const gruppi = {};
      dati.forEach(r => {
        const chiaveGruppo = r[config.raggruppaPer] || 'Senza Valore';
        if (!gruppi[chiaveGruppo]) gruppi[chiaveGruppo] = [];
        gruppi[chiaveGruppo].push(r);
      });
      const chiaviOrdinate = ordinaGruppi('incarichi', Object.keys(gruppi));
      const coloriScelti = config.coloriGruppi || {};
      chiaviOrdinate.forEach((nomeGruppo, idx) => {
        const coloreAuto = COLORI_STATO_INCARICO[nomeGruppo] || PALETTE_GRUPPI_TABELLE[idx % PALETTE_GRUPPI_TABELLE.length];
        const colore = coloriScelti[nomeGruppo] || coloreAuto;
        const idBlocco = `gruppo-incarichi-${idx}-${nomeGruppo.replace(/[^a-zA-Z0-9]/g,'')}`;
        // fisarmonica: resta aperto un solo gruppo alla volta (di default "On Line")
        const chiusa = (String(nomeGruppo) !== String(GRUPPO_APERTO_INCARICHI));
        const nomeGruppoEscaped = nomeGruppo.toString().replace(/'/g, "\\'");
        // sfondo tendina colorato per stato; testo scuro dove lo sfondo è chiaro
        const infoT = COLORI_TENDINA_INCARICO[nomeGruppo];
        const bgTendina = coloriScelti[nomeGruppo] || (infoT ? infoT.bg : colore);
        const txtTendina = infoT ? infoT.t : '#ffffff';
        const chiaro = ['#ffffff', '#fff', '#f2e08a', '#8fd07a'].indexOf(String(bgTendina).toLowerCase()) !== -1;
        const bordoTendina = chiaro ? 'border:1px solid rgba(0,0,0,.18);' : 'border:1px solid rgba(0,0,0,.22);';
        html += `<div class="albero-comune-block" draggable="true"
            ondragstart="iniziaTrascinamentoGruppo(event, 'incarichi', '${nomeGruppoEscaped}')"
            ondragover="consentiTrascinamentoGruppo(event)"
            ondrop="rilasciaGruppoSu(event, 'incarichi', '${nomeGruppoEscaped}')">
          <div class="riga-livello-1" style="background:${bgTendina}; ${bordoTendina} border-left:6px solid rgba(0,0,0,.28); border-radius:6px 6px 0 0; cursor:grab; display:flex; justify-content:space-between; align-items:center;" onclick="toggleGruppoIncarichi('${nomeGruppoEscaped}')">
            <span style="color:${txtTendina};"><i class="fa-solid fa-grip-vertical" style="margin-right:10px; opacity:.55;" title="Trascina per riordinare"></i><i class="fa-solid ${chiusa ? 'fa-chevron-right':'fa-chevron-down'}" style="margin-right:8px;"></i> <strong>${nomeGruppo.toString().toUpperCase()}</strong> <span style="font-weight:500; font-size:12px; opacity:.85;">(${gruppi[nomeGruppo].length})</span></span>
            <input type="color" value="${String(bgTendina).length === 7 ? bgTendina : '#0086d6'}" onclick="event.stopPropagation()" onchange="cambiaColoreGruppo('incarichi', '${nomeGruppoEscaped}', this.value)" title="Scegli il colore di questo gruppo" style="width:24px; height:24px; border:none; background:none; cursor:pointer; padding:0; opacity:.9;">
          </div>
          <div class="scroll-incarichi" style="display:${chiusa?'none':'block'}; padding:0 8px 8px; background:${bgTendina}; max-height:72vh; overflow:auto; max-width:100%; box-sizing:border-box; border-radius:0 0 6px 6px;">${costruisciTabellaRighe(gruppi[nomeGruppo], bgTendina, txtTendina)}</div>
        </div>`;
      });
    }

    container.innerHTML = html;
  }

  async function aggiornaCampoIncarico(id, campo, valore) {
    const record = REGISTRO_INCARICHI_CLOUD.find(r => r._id === id);
    if (record) record[campo] = valore;
    try {
      await fetch(`${API_INCARICHI}/${id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ campo, valore }) });
    } catch (e) { console.error('Errore aggiornamento incarico:', e); }
    if (AREA_LAVORO_ATTIVA === 'inc-pure') {
      // ridisegno solo se il campo cambia gruppo/colonne derivate: così una modifica
      // normale (mq, box, prezzo...) NON fa saltare la tabella a sinistra.
      const cfg = ottieniConfigVista('incarichi');
      const strutturale = ['statoImmobile', 'dataScadenza', 'listing'].indexOf(campo) !== -1 || campo === cfg.raggruppaPer;
      if (strutturale) ridisegnaIncarichiMantieniScroll();
    }
    if (AREA_LAVORO_ATTIVA === 'centralino') disegnaTabellaCentralinoCloud();
  }

  async function modificaLinkIncarico(id, campo, titolo) {
    const record = REGISTRO_INCARICHI_CLOUD.find(r => r._id === id);
    const attuale = record ? (record[campo] || '') : '';
    const nuovo = prompt(`Link ${titolo}:`, attuale);
    if (nuovo === null) return; // annullato
    await aggiornaCampoIncarico(id, campo, nuovo.trim());
  }

  let INCARICO_FOTO_ATTIVO = null;

  /* ==========================================
     GOOGLE DRIVE PICKER (selezione foto reale da Drive)
  ========================================== */
  const LOGO_FORTE_ORIZZONTALE_BASE64 = "https://drive.google.com/thumbnail?id=1jSlWZ19VPikaMbTpAf9xz8zJCxaA_TcQ&sz=w800";
  const GOOGLE_API_KEY = 'AIzaSyCnavYGmflxXULw5aOWIwT0kcxDUa5jW7c';
  const GOOGLE_MAPS_API_KEY = 'AIzaSyBlDMXfhfO2a00Qcgsz6n_red-vDrKI6jQ';
  const GOOGLE_CLIENT_ID = '97310670593-pu47hgchah3bjk8838nmf1djt4hvtuo7.apps.googleusercontent.com';
  let TOKEN_CLIENT_GOOGLE = null;
  let GOOGLE_ACCESS_TOKEN = null;

  function apriSelettoreGoogleDrive() {
    if (typeof google === 'undefined' || !google.accounts) {
      alert("Il collegamento a Google Drive si sta ancora caricando: riprova tra un secondo.");
      return;
    }
    if (!TOKEN_CLIENT_GOOGLE) {
      TOKEN_CLIENT_GOOGLE = google.accounts.oauth2.initTokenClient({
        client_id: GOOGLE_CLIENT_ID,
        scope: 'https://www.googleapis.com/auth/drive',
        callback: (risposta) => {
          if (risposta.error) { console.error('Errore autenticazione Google:', risposta); alert("Accesso a Google Drive annullato o non riuscito."); return; }
          GOOGLE_ACCESS_TOKEN = risposta.access_token;
          mostraGooglePicker();
        }
      });
    }
    if (GOOGLE_ACCESS_TOKEN) { mostraGooglePicker(); } else { TOKEN_CLIENT_GOOGLE.requestAccessToken(); }
  }

  function mostraGooglePicker() {
    if (typeof gapi === 'undefined') {
      alert("La libreria Google non è ancora pronta: riprova tra un secondo.");
      return;
    }
    gapi.load('picker', () => {
      const vista = new google.picker.DocsView(google.picker.ViewId.DOCS)
        .setIncludeFolders(true)
        .setSelectFolderEnabled(false)
        .setMimeTypes('image/png,image/jpeg,image/gif,image/webp');
      const selettore = new google.picker.PickerBuilder()
        .addView(vista)
        .setOAuthToken(GOOGLE_ACCESS_TOKEN)
        .setDeveloperKey(GOOGLE_API_KEY)
        .enableFeature(google.picker.Feature.MULTISELECT_ENABLED)
        .setCallback(gestisciSelezioneGoogleDrive)
        .build();
      selettore.setVisible(true);
    });
  }

  async function rendiPubblicoFileDrive(fileId) {
    try {
      await fetch(`https://www.googleapis.com/drive/v3/files/${fileId}/permissions`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${GOOGLE_ACCESS_TOKEN}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ role: 'reader', type: 'anyone' })
      });
    } catch (e) { console.error('Errore impostazione permessi Drive:', e); }
  }

  async function gestisciSelezioneGoogleDrive(dato) {
    if (dato.action !== google.picker.Action.PICKED) return;
    const file = dato.docs || [];
    if (file.length === 0) return;
    // Rendiamo ogni foto scelta visibile "a chiunque abbia il link": altrimenti Drive la blocca
    // quando la brochure prova a mostrarla, perché di base i file restano privati.
    await Promise.all(file.map(f => rendiPubblicoFileDrive(f.id)));
    const nuoviLink = file.map(f => `https://drive.google.com/file/d/${f.id}/view`);
    const r = REGISTRO_INCARICHI_CLOUD.find(x => x._id === INCARICO_FOTO_ATTIVO);
    if (!r) return;
    if (!r.fotoAllegati) r.fotoAllegati = [];
    r.fotoAllegati.push(...nuoviLink);
    await salvaFotoAllegatiIncarico();
    renderizzaListaFotoPopup();
  }

  async function rendiPubblicheFotoEsistenti() {
    const r = REGISTRO_INCARICHI_CLOUD.find(x => x._id === INCARICO_FOTO_ATTIVO);
    if (!r || !r.fotoAllegati || r.fotoAllegati.length === 0) { alert("Nessuna foto da sistemare."); return; }
    if (typeof google === 'undefined' || !google.accounts) { alert("Il collegamento a Google si sta ancora caricando: riprova tra un secondo."); return; }
    if (!GOOGLE_ACCESS_TOKEN) {
      alert("Devi prima autorizzare l'accesso a Google Drive: premi \"Scegli da Google Drive\" una volta, poi riprova questo pulsante.");
      return;
    }
    const idUnivoci = new Set();
    r.fotoAllegati.forEach(link => {
      const m = link.match(/\/d\/([a-zA-Z0-9_-]+)/);
      if (m) idUnivoci.add(m[1]);
    });
    await Promise.all(Array.from(idUnivoci).map(id => rendiPubblicoFileDrive(id)));
    alert(`Fatto: ${idUnivoci.size} foto rese visibili a chiunque abbia il link.`);
  }

  /* ==========================================
     POPUP GESTIONE DOCUMENTI E PUBBLICAZIONE INCARICO
  ========================================== */
  let INCARICO_GESTIONE_DOC_ATTIVO = null;

